INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH0' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'BAI_0', 'MỞ ĐẦU', 6, 0, $JSON$
{
  "content": [
    "MỞ ĐẦU",
    "",
    "MỤC TIÊU:",
    "– Nêu được đối tượng nghiên cứu của hoá học.",
    "– Trình bày được phương pháp học tập và nghiên cứu hoá học.",
    "– Nêu được vai trò của hoá học đối với đời sống, sản xuất,...",
    "",
    "❓",
    "Hoá học là một trong các nội dung của môn Khoa học tự nhiên ở cấp Trung học cơ sở và trở thành môn học độc lập ở cấp Trung học phổ thông. Đối tượng nghiên cứu của môn Hoá học là gì? Hoá học có vai trò như thế nào đối với đời sống và sản xuất? Làm thế nào để học tập tốt môn Hoá học?",
    "",
    "I ĐỐI TƯỢNG NGHIÊN CỨU CỦA HOÁ HỌC",
    "",
    "Hoá học nghiên cứu về thành phần, cấu trúc, tính chất, sự biến đổi của các chất và các hiện tượng kèm theo. Hoá học có mối liên hệ chặt chẽ với các ngành khoa học tự nhiên nghiên cứu về chất và vật thể như vật lí, sinh học và địa chất.",
    "",
    "Đối tượng nghiên cứu của hoá học bao gồm các chất hữu cơ, các chất vô cơ, các loại vật liệu tự nhiên và nhân tạo.",
    "",
    "Môn Khoa học tự nhiên cấp Trung học cơ sở đã trình bày những khái niệm ban đầu của hoá học như mol (lượng chất), liên kết hoá học và tương tác giữa các chất để hiểu được các hoạt động của thế giới sinh học và các hiện tượng vật lí.",
    "",
    "Theo truyền thống, hoá học được chia thành các chuyên ngành như hoá lí, hoá học vô cơ, hoá học hữu cơ, hoá học phân tích, hoá sinh,...",
    "",
    "Hoá lí",
    "Hoá sinh",
    "Hoá học hữu cơ",
    "Hoá học phân tích",
    "Hoá học vô cơ",
    "",
    "Hình 2. Một số chuyên ngành trong hoá học",
    "",
    "6",
    "",
    "Ngày nay, sự phát triển của khoa học làm xuất hiện nhiều chuyên ngành mới không thuộc các ngành truyền thống như khoa học vật liệu, hoá dược, công nghệ hoá học,... Tuy nhiên, sự phân biệt các chuyên ngành như vậy chỉ có tính chất tương đối. Để giải quyết một bài toán hoá học trong thực tế cần biết vận dụng các kiến thức tổng hợp một cách hợp lí.",
    "",
    "❓",
    "1. Đối tượng nghiên cứu của hoá học là sự biến đổi chất, hãy lấy 5 ví dụ về sự biến đổi hoá học.",
    "2. Hãy cho biết khái niệm chất vô cơ và chất hữu cơ.",
    "",
    "💡 EM CÓ BIẾT",
    "Sơ lược về lịch sử hoá học",
    "Từ hàng nghìn năm trước đây, hoá học được hình thành do sự mong ước tìm được thuốc \"trường sinh bất lão\" hay tìm được \"hòn đá phù thuỷ\" dùng để biến đổi các chất rẻ tiền thành gold (vàng). Các nhà giả kim thuật khi tiến hành các thí nghiệm đã tạo ra nhiều dụng cụ thí nghiệm mà đến tận ngày nay, chúng vẫn còn được sử dụng trong hoá học.",
    "",
    "Thời điểm đánh dấu việc hoá học tách khỏi khoa học giả kim là năm 1661, với tác phẩm \"Nhà hoá học hoài nghi\" (The Skeptical Chemist) của Robert Boyle (Rô-bớt Boi-lơ) và sự kiện đánh dấu hoá học trở thành môn khoa học độc lập là sự tìm ra khí oxygen vào năm 1783 bởi Antoine Lavoisier (Ăng-toan La-voa-di-ê). Hoá học đã phát triển mạnh mẽ vào thế kỉ XIX qua những nghiên cứu về tác động của phân bón đến nông nghiệp và những nỗ lực tìm kiếm chất màu tổng hợp để nhuộm vải, tạo tiền đề cho ngành hoá học hữu cơ.",
    "",
    "Ngày nay, hoá học đã thu được nhiều thành tựu vượt bậc, nhưng các nhà khoa học vẫn không ngừng khám phá sâu hơn bản chất của thế giới vật chất, tìm tòi nghiên cứu ra các sản phẩm mới để phục vụ cho đời sống của con người.",
    "KẾT NỐI TRI THỨC VỚI CUỘC SỐNG",
    "",
    "II VAI TRÒ CỦA HOÁ HỌC VỚI ĐỜI SỐNG VÀ SẢN XUẤT",
    "",
    "Hoá học có vai trò vô cùng quan trọng với đời sống và sản xuất. Các chất hoá học có trong mọi thứ xung quanh ta như lương thực – thực phẩm; nhiên liệu; nguyên liệu, vật liệu để sản xuất; các loại thuốc chữa bệnh;...",
    "",
    "Ngành công nghiệp hoá học sản xuất các hoá chất từ đơn giản đến phức tạp. Mỗi năm, hàng triệu tấn các hoá chất cơ bản như sulfuric acid hay ammonia, phân bón, chất dẻo,... được sản xuất để phục vụ nhu cầu của đời sống và công nghiệp.",
    "",
    "Hình 3. Phân bón hoá học làm tăng năng suất cây trồng",
    "",
    "7",
    "",
    "Hoá học phóng xạ nghiên cứu và sử dụng sự phân rã hạt nhân cho các quá trình hoá lí, sinh hoá,...",
    "",
    "Nguồn năng lượng được coi như vô tận đối với loài người là năng lượng từ Mặt Trời. Việc sử dụng năng lượng mặt trời là lĩnh vực phát triển rất nhanh trong thời gian gần đây với những trang trại pin mặt trời phổ biến ở nhiều nước trên thế giới. Các nhà hoá học có đóng góp rất lớn trong việc chế tạo vật liệu mới giúp tăng hiệu suất chuyển hoá năng lượng mặt trời.",
    "",
    "Những thách thức mới về khoa học công nghệ đang là động lực thúc đẩy hoá học tự phát triển và cùng phát triển với các lĩnh vực khác.",
    "",
    "Hình 4. Thuốc - sản phẩm của ngành hoá dược",
    "",
    "❓",
    "3. Hãy kể tên một số sản phẩm hoá học trong đời sống hằng ngày.",
    "4. Người nông dân sử dụng sản phẩm nào của hoá học để tăng năng suất cây trồng?",
    "",
    "💡 EM CÓ BIẾT",
    "Một số nghề nghiệp liên quan đến hoá học",
    "• Nhà hoá học (cử nhân và kĩ sư hoá học) kiểm tra tính chất vật lí và hoá học của sản phẩm. Họ có thể nghiên cứu để tạo ra sản phẩm mới hoặc cải tiến các sản phẩm đang có. Họ có thể tư vấn, hỗ trợ kĩ thuật về sản phẩm.",
    "• Nhà hoá học có thể làm giáo viên dạy môn Khoa học tự nhiên ở cấp Trung học cơ sở và môn Hoá học ở cấp Trung học phổ thông. Họ cũng có thể vừa giảng dạy và vừa nghiên cứu hoá học ở các trường đại học, cao đẳng và dạy nghề.",
    "• Nhà hoá học có thể làm việc trong lĩnh vực môi trường. Họ vừa có thể kiểm tra mức độ ô nhiễm của môi trường cũng như tìm cách xử lí để giúp môi trường trong lành hơn.",
    "• Nhà hoá học có thể làm việc trong các cơ sở pháp y hay xét nghiệm y học để phân tích các mẫu lấy từ hiện trường vụ án hoặc bệnh phẩm để tìm sự hiện diện của ma tuý hoặc các chất gây bệnh.",
    "• Nhà hoá học có thể góp phần bảo vệ hoặc khôi phục các bức tranh, đồ cổ hoặc phát hiện ra các tác phẩm giả mạo.",
    "Hoá học là ngành khoa học thiết thực có nhiều ứng dụng. Trên đây chỉ là một số ngành nghề cơ bản có sự tham gia của các nhà hoá học, ngoài ra còn rất nhiều ngành nghề khác, thậm chí trong tương lai có thể có rất nhiều ngành nghề mới xuất hiện liên quan đến môn học thú vị này.",
    "",
    "8",
    "",
    "III PHƯƠNG PHÁP HỌC TẬP VÀ NGHIÊN CỨU HOÁ HỌC",
    "",
    "Hình 6. Phòng thí nghiệm hoá học",
    "",
    "1. Khi học tập môn Hoá học, học sinh cần thực hiện các hoạt động tìm kiếm thông tin, xử lí thông tin và nắm vững những thông tin cần thiết qua sách giáo khoa. Cụ thể:",
    "– Xuất phát từ mục tiêu của mỗi bài học, học sinh tìm hiểu kiến thức qua sách giáo khoa: nội dung học tập, quan sát thí nghiệm, dự đoán kết quả, đồng thời liên hệ với các thông tin đã biết từ các hiện tượng tự nhiên, từ cuộc sống hằng ngày,...",
    "– Xử lí các thông tin đã có để đưa ra các giải thích, dự đoán và kết luận cần thiết, trả lời câu hỏi, giải bài tập.",
    "– Ghi nhớ những kiến thức cốt lõi, làm cơ sở cho việc tiếp tục học tập hay nghiên cứu.",
    "– Vận dụng những kiến thức, kĩ năng đã học vào các tình huống trong thực tiễn.",
    "",
    "2. Để học tốt môn Hoá học, học sinh cần nắm vững và vận dụng các kiến thức đã học, đồng thời chú ý rèn các kĩ năng thực hiện thí nghiệm, phát hiện, giải quyết vấn đề và sáng tạo:",
    "– Biết làm thí nghiệm hoá học an toàn và thành công. Biết quan sát, ghi chép, mô tả và giải thích các hiện tượng xảy ra không chỉ trong phòng thí nghiệm mà cả trong tự nhiên và thực tế cuộc sống.",
    "– Rèn luyện thói quen tìm tòi, khám phá, tư duy và hành động, suy luận và sáng tạo, quan sát và liên kết giữa các hiện tượng, sự vật trong cuộc sống.",
    "– Hình thành, nuôi dưỡng sự hứng thú, say mê và chủ động trong việc học tập. Rèn luyện kĩ năng tra cứu, mở rộng kiến thức từ các nguồn tài liệu khác nhau phù hợp với bài học và lứa tuổi.",
    "",
    "3. Học, tìm hiểu và nghiên cứu hoá học có nhiều điểm chung với các môn Khoa học tự nhiên khác, cụ thể là quy trình nghiên cứu cần thực hiện các bước theo sơ đồ dưới đây:",
    "",
    "9",
    "",
    "Bước 1. Quan sát và đặt câu hỏi",
    "Quan sát các hiện tượng hoá học và đặt câu hỏi về bản chất hoá học của hiện tượng hay một vấn đề cần giải quyết.",
    "Ví dụ: Chất tẩy rửa X có khả năng loại bỏ dầu mỡ tốt hơn chất tẩy rửa Y. Tại sao?",
    "↓",
    "Bước 2. Đặt ra giả thuyết khoa học",
    "Đưa ra một hay một số giả thuyết giải thích cho hiện tượng quan sát được (có thể cần tham khảo thêm từ sách giáo khoa hoặc các tài liệu khác, kể cả qua Internet).",
    "Ví dụ: Đọc thành phần chất tẩy rửa ghi trên các nhãn của X và Y. Trong X và Y đều có thành phần sodium hydroxide. Sodium hydroxide được sử dụng trong chất tẩy rửa nhà bếp để loại bỏ dầu mỡ.",
    "Giả thuyết khoa học đặt ra là X có thể chứa nhiều sodium hydroxide hơn Y.",
    "↓",
    "Bước 3. Lập kế hoạch thí nghiệm để kiểm chứng giả thuyết khoa học",
    "– Các dụng cụ và hoá chất cần sử dụng; số người tham gia nhóm thí nghiệm; phân công công việc cho mỗi thành viên trong nhóm.",
    "– Lập kế hoạch chi tiết các công việc để thực hiện thí nghiệm.",
    "Ví dụ: Lập kế hoạch thí nghiệm để xác định hàm lượng sodium hydroxide trong các chất tẩy rửa X và Y.",
    "↓",
    "Bước 4. Tiến hành thí nghiệm",
    "Thực hành thí nghiệm như kế hoạch đã lập ở bước 3 và ghi chép lại các kết quả thí nghiệm.",
    "↓",
    "Bước 5. Phân tích kết quả thí nghiệm",
    "Có thể trình bày các kết quả thí nghiệm thành bảng, biểu, đồ thị hoặc thực hiện các tính toán cần thiết để phân tích kết quả thí nghiệm.",
    "↓",
    "Bước 6. So sánh kết quả với giả thuyết",
    "So sánh kết quả thí nghiệm với các giả thuyết đã đặt ra ban đầu. Đưa ra kết luận giả thuyết nào là hợp lí, phù hợp với kết quả thí nghiệm, giả thuyết nào không phù hợp.",
    "Ví dụ: Hàm lượng sodium hydroxide của hai chất tẩy rửa như nhau cho thấy giả thuyết khoa học ở bước 2 không đúng thì thực hiện lại quy trình nghiên cứu từ bước 2.",
    "↓",
    "Bước 7. Báo cáo kết quả",
    "Ghi lại vào báo cáo thí nghiệm hoặc trình bày trước giáo viên và các bạn trong lớp về tiến trình thí nghiệm, kết quả thí nghiệm và kết luận.",
    "",
    "10",
    "",
    "4. Phương pháp mô hình được sử dụng để mô tả, mô phỏng cấu tạo của các hạt quá nhỏ không quan sát được bằng mắt thường như phân tử, nguyên tử và các hạt nhỏ hơn. Từ đó suy ra cấu tạo các vật thể thật trong cuộc sống.",
    "",
    "Mô hình cấu tạo nguyên tử của Rutherford (Rơ-dơ-pho) là một thí dụ. Từ thực nghiệm bắn phá lá vàng bằng tia $\\alpha$, Rutherford phát hiện ra cấu tạo rỗng của nguyên tử, phát hiện ra lõi nguyên tử là hạt nhân có khối lượng xấp xỉ khối lượng nguyên tử. Rutherford đề xuất mô hình hành tinh nguyên tử, coi các electron quay xung quanh hạt nhân như các hành tinh quay xung quanh Mặt Trời.",
    "",
    "Phương pháp mô hình được sử dụng phổ biến trong ba chương đầu tiên về nguyên tử, phân tử, liên kết hoá học và bảng tuần hoàn các nguyên tố hoá học (bảng tuần hoàn).",
    "",
    "5. Phương pháp thực nghiệm đóng vai trò cốt lõi của nghiên cứu hoá học. Các giả thuyết và mô hình hoá đều phải được kiểm chứng bằng thực nghiệm và từ thực nghiệm người ta có thể mô hình hoá thành quy luật. Phương pháp thực nghiệm được sử dụng xuyên suốt toàn bộ Chương trình Giáo dục phổ thông môn Hoá học.",
    "Ví dụ: Sử dụng phương pháp thực nghiệm để nghiên cứu chlorine:",
    "– Từ hiểu biết về cấu tạo nguyên tử và liên kết hoá học để dự đoán tính chất hoá học đặc trưng của chlorine.",
    "– Thực hiện các thí nghiệm cho chlorine tác dụng với kim loại, hydrogen, dung dịch muối của halogen để chứng minh dự đoán trên.",
    "– Vận dụng tính chất hoá học của chlorine vào thực tế: dùng dung dịch nước chlorine, clorua vôi,... để tẩy trắng.",
    "",
    "Các em hãy bắt đầu học hoá học với sự tò mò khoa học, kiên trì từ những bước đầu tiên với những thí nghiệm đơn giản để có thể nhận ra rằng \"Hoá học thật là đơn giản!\" và sau đó sẽ thấy \"Hoá học thật là lí thú!\".",
    "",
    "EM ĐÃ HỌC",
    "• Hoá học nghiên cứu về chất, sự biến đổi của chất và các hiện tượng đi kèm với những biến đổi hoá học.",
    "• Hoá học có vai trò quan trọng với đời sống và sản xuất.",
    "• Cách học tập, nghiên cứu về hoá học qua quan sát và đặt câu hỏi, đặt ra giả thuyết khoa học, chứng minh bằng thí nghiệm, phân tích kết quả thí nghiệm, trình bày kết quả thu được và báo cáo.",
    "",
    "EM CÓ THỂ",
    "Biết vận dụng phương pháp học tập và nghiên cứu hoá học để học tốt môn Hoá học và giải quyết một số tình huống trong đời sống.",
    "",
    "11"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'BAI_1', 'THÀNH PHẦN CỦA NGUYÊN TỬ', 13, 1, $JSON$
{
  "content": [
    "BÀI 1 THÀNH PHẦN CỦA NGUYÊN TỬ",
    "",
    "MỤC TIÊU:",
    "– Trình bày được thành phần của nguyên tử (nguyên tử vô cùng nhỏ; nguyên tử gồm 2 phần: hạt nhân và lớp vỏ nguyên tử; hạt nhân tạo nên bởi các hạt proton (p), neutron (n); lớp vỏ tạo nên bởi các electron (e); điện tích, khối lượng mỗi loại hạt).",
    "– So sánh được khối lượng của electron với proton và neutron, kích thước của hạt nhân với kích thước nguyên tử.",
    "",
    "❓",
    "Nguyên tử gồm các loại hạt cơ bản nào? Các nhà khoa học đã phát hiện ra các loại hạt cơ bản đó như thế nào?",
    "",
    "I CÁC LOẠI HẠT CẤU TẠO NÊN NGUYÊN TỬ",
    "",
    "Năm 1897, J. J. Thomson (Tôm-xơn, người Anh) thực hiện thí nghiệm phóng điện qua không khí loãng đã phát hiện ra chùm tia phát ra từ cực âm và bị hút lệch về phía cực dương của điện trường, chứng tỏ chúng mang điện tích âm (xem Hình 1.1). Đó chính là chùm các hạt electron. Electron là một thành phần của nguyên tử.",
    "",
    "Năm 1911, E. Rutherford (Rơ-dơ-pho, người Niu Di-lân) thực hiện thí nghiệm bắn phá lá vàng rất mỏng bằng chùm hạt $\\alpha^{(*)}$ (alpha) (Hình 1.2). Ông sử dụng màn huỳnh quang bao quanh lá vàng để quan sát vị trí va chạm của hạt $\\alpha$. Kết quả thí nghiệm cho thấy hầu hết các hạt $\\alpha$ đều xuyên thẳng qua lá vàng, chứng tỏ nguyên tử có cấu tạo rỗng, ở tâm chứa một hạt nhân mang điện tích dương và có kích thước rất nhỏ so với kích thước nguyên tử.",
    "",
    "Năm 1918, E. Rutherford và các cộng sự khi dùng hạt $\\alpha$ bắn phá nitrogen đã phát hiện ra hạt proton.",
    "",
    "Năm 1932, J. Chadwick (Chat-uých, người Anh), cộng sự của Rutherford, đã phát hiện ra hạt neutron khi bắn phá beryllium bằng các hạt $\\alpha$.",
    "",
    "Proton, neutron và electron là các hạt cấu tạo nên nguyên tử (trừ trường hợp $^{1}_{1}\\text{H}^{(**)}$).",
    "",
    "Tấm kim loại tích điện làm thay đổi đường đi của chùm tia",
    "Cực dương",
    "Cực âm",
    "Màn huỳnh quang",
    "Hình 1.1. Thí nghiệm phát hiện hạt electron",
    "",
    "Lá vàng mỏng",
    "Hộp phóng ra chùm hạt $\\alpha$",
    "Màn huỳnh quang",
    "Khe hở",
    "Hình 1.2. Thí nghiệm phát hiện hạt nhân nguyên tử",
    "",
    "(*) Hạt $\\alpha$: hạt nhân helium, mang điện tích dương.",
    "(**) $^{1}_{1}\\text{H}$ là một loại nguyên tử của nguyên tố hydrogen (sẽ được học trong bài Nguyên tố hoá học).",
    "",
    "13",
    "",
    "Thành phần cấu tạo của nguyên tử gồm:",
    "– *Hạt nhân*: ở tâm của nguyên tử, chứa các proton mang điện tích dương và các neutron không mang điện (trừ trường hợp $^{1}_{1}\\text{H}$).",
    "– *Vỏ nguyên tử*: chứa các electron mang điện tích âm, chuyển động rất nhanh xung quanh hạt nhân.",
    "",
    "*Bảng 1.1. Khối lượng, điện tích của các loại hạt cấu tạo nên nguyên tử*",
    "",
    "| Hạt | Kí hiệu | Khối lượng (kg) | Khối lượng (amu) | Điện tích (C) | Điện tích tương đối |",
    "| :--- | :---: | :---: | :---: | :---: | :---: |",
    "| Proton | p | $1,673 \\cdot 10^{-27}$ | $\\approx 1$ | $+1,602 \\cdot 10^{-19}$ | $+1$ |",
    "| Neutron | n | $1,675 \\cdot 10^{-27}$ | $\\approx 1$ | 0 | 0 |",
    "| Electron | e | $9,109 \\cdot 10^{-31}$ | $\\frac{1}{1837} \\approx 0,00055$ | $-1,602 \\cdot 10^{-19}$ | $-1$ |",
    "",
    "Trong nguyên tử, số proton bằng số electron. Nguyên tử trung hoà về điện.",
    "",
    "Khối lượng của electron rất nhỏ, không đáng kể so với khối lượng của proton hay neutron nên khối lượng của nguyên tử tập trung hầu hết ở hạt nhân.",
    "",
    "❓",
    "1. Nguyên tử chứa những hạt mang điện là",
    "   A. proton và hạt $\\alpha$.",
    "   B. proton và neutron.",
    "   C. proton và electron.",
    "   D. electron và neutron.",
    "2. Quan sát hình ảnh mô phỏng kết quả thí nghiệm bắn phá lá vàng thực hiện bởi Rutherford (Hình 1.3) và nhận xét về đường đi của các hạt $\\alpha$.",
    "",
    "Hình 1.3. Mô phỏng kết quả thí nghiệm bắn phá lá vàng",
    "",
    "14",
    "",
    "II KÍCH THƯỚC VÀ KHỐI LƯỢNG CỦA NGUYÊN TỬ",
    "",
    "1. Kích thước",
    "Kích thước của nguyên tử là khoảng không gian tạo bởi sự chuyển động của các electron. Các nguyên tử khác nhau có số electron khác nhau nên có kích thước khác nhau. Nếu coi nguyên tử như một khối cầu thì đường kính của nó chỉ khoảng $10^{-10}\\text{ m}$.",
    "",
    "Kích thước nguyên tử rất nhỏ nên thường được biểu diễn bằng đơn vị picomet (pm) hay Ăngstrôm (Å).",
    "$1\\text{ pm} = 10^{-12}\\text{ m}$; $1\\text{ Å} = 10^{-10}\\text{ m}$. Nguyên tử hydrogen có bán kính khoảng $53\\text{ pm}$.",
    "",
    "Hạt nhân nguyên tử có đường kính khoảng $10^{-2}\\text{ pm}$, kích thước nhỏ hơn nhiều so với kích thước nguyên tử.",
    "",
    "💡 EM CÓ BIẾT",
    "Một lượng chất rất nhỏ cũng chứa số nguyên tử lớn tới mức khó hình dung được. Ví dụ: trong 1 lít nước chứa khoảng $9 \\cdot 10^{25}$ các nguyên tử oxygen và hydrogen. Do đó, không thể nhìn thấy nguyên tử bằng mắt thường, thậm chí bằng kính hiển vi có độ phóng đại rất lớn (hàng chục triệu lần).",
    "",
    "2. Khối lượng",
    "Khối lượng nguyên tử bằng tổng khối lượng các hạt proton, neutron và electron có trong nguyên tử. Khối lượng nguyên tử rất nhỏ nên một lượng chất rất nhỏ cũng chứa tới hàng tỉ tỉ nguyên tử. Ví dụ: Trong 2 g carbon chứa khoảng $10^{23}$ nguyên tử carbon.",
    "",
    "Có thể biểu thị khối lượng nguyên tử theo đơn vị khối lượng nguyên tử, kí hiệu amu.",
    "",
    "Ví dụ: Một nguyên tử oxygen có khối lượng là $2,656 \\cdot 10^{-26}\\text{ kg}$.",
    "$1\\text{ amu} = 1,661 \\cdot 10^{-27}\\text{ kg}$ nên khối lượng một nguyên tử oxygen là 15,990 amu.",
    "",
    "💡 EM CÓ BIẾT",
    "Khối lượng tính ra kg của 1 nguyên tử carbon-12 là $19,926 \\cdot 10^{-27}\\text{ kg}$.",
    "1 amu được định nghĩa bằng $\\frac{1}{12}$ khối lượng 1 nguyên tử carbon-12:",
    "$1\\text{ amu} = \\frac{19,926 \\cdot 10^{-27}\\text{ kg}}{12} = 1,661 \\cdot 10^{-27}\\text{ kg}$.",
    "",
    "❓",
    "3. Nếu phóng đại một nguyên tử vàng lên 1 tỉ ($10^{9}$) lần thì kích thước của nó tương đương một quả bóng rổ (có đường kính 30 cm) và kích thước của hạt nhân tương đương một hạt cát (có đường kính 0,003 cm). Hãy cho biết kích thước nguyên tử vàng lớn hơn so với hạt nhân bao nhiêu lần.",
    "4. Một loại nguyên tử nitrogen có 7 proton và 7 neutron trong hạt nhân. Dựa vào Bảng 1.1, hãy tính và so sánh:",
    "   a) Khối lượng hạt nhân với khối lượng nguyên tử.",
    "   b) Khối lượng hạt nhân với khối lượng vỏ nguyên tử.",
    "",
    "15",
    "",
    "III ĐIỆN TÍCH HẠT NHÂN VÀ SỐ KHỐI",
    "",
    "Số proton trong hạt nhân nguyên tử bằng số đơn vị điện tích hạt nhân, kí hiệu là Z.",
    "Ví dụ: Hạt nhân nguyên tử Na có 11 proton nên số đơn vị điện tích hạt nhân là Z = 11.",
    "Tổng số proton và tổng số neutron (kí hiệu là N) trong hạt nhân của một nguyên tử được gọi là số khối (hay số nucleon), kí hiệu là A.",
    "A = Z + N",
    "Ví dụ: Hạt nhân nguyên tử Na có số proton là 11 và số neutron là 12 nên số khối của hạt nhân nguyên tử Na là:",
    "A = 11 + 12 = 23",
    "",
    "❓",
    "5. Aluminium (nhôm) là kim loại phổ biến nhất trên vỏ Trái Đất, được sử dụng trong các ngành xây dựng, ngành điện hoặc sản xuất đồ gia dụng. Hạt nhân của nguyên tử aluminium có điện tích bằng +13 và số khối bằng 27. Tính số proton, số neutron và số electron có trong nguyên tử aluminium.",
    "",
    "EM ĐÃ HỌC",
    "• Nguyên tử vô cùng nhỏ nhưng được tạo thành từ các hạt nhỏ hơn, gồm hạt nhân (chứa proton mang điện tích dương và neutron không mang điện) và vỏ nguyên tử (chứa các electron mang điện tích âm). Nguyên tử trung hoà về điện. Trong nguyên tử, số proton bằng số electron.",
    "• Khối lượng nguyên tử tập trung ở hạt nhân (do khối lượng của electron rất nhỏ so với khối lượng của proton và neutron).",
    "• Hạt nhân nguyên tử có kích thước vô cùng nhỏ so với nguyên tử.",
    "",
    "EM CÓ THỂ",
    "Vận dụng phương pháp mô hình để mô tả cấu tạo nguyên tử.",
    "",
    "16"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_1' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'BAI_2', 'NGUYÊN TỬ HOÁ HỌC', 17, 2, $JSON$
{
  "content": [
    "BÀI 2 NGUYÊN TỐ HOÁ HỌC",
    "",
    "MỤC TIÊU:",
    "– Trình bày được khái niệm về nguyên tố hoá học, số hiệu nguyên tử và kí hiệu nguyên tử.",
    "– Phát biểu được khái niệm đồng vị, nguyên tử khối.",
    "– Tính được nguyên tử khối trung bình (theo amu) dựa vào khối lượng nguyên tử và phần trăm số nguyên tử của các đồng vị theo phổ khối lượng được cung cấp.",
    "",
    "❓",
    "Các nguyên tử có cùng số đơn vị điện tích hạt nhân thì có đặc điểm gì chung? Giữa số đơn vị điện tích hạt nhân, số proton và số electron có mối liên hệ như thế nào?",
    "",
    "I NGUYÊN TỐ HOÁ HỌC",
    "",
    "Nguyên tố hoá học là tập hợp các nguyên tử có cùng số đơn vị điện tích hạt nhân. Trong nguyên tử, số đơn vị điện tích hạt nhân bằng số electron ở vỏ nguyên tử. Các electron trong nguyên tử quyết định tính chất hoá học của nguyên tử, nên các nguyên tử của cùng một nguyên tố hoá học có tính chất hoá học giống nhau.",
    "",
    "Ví dụ: Tất cả nguyên tử có cùng số đơn vị điện tích hạt nhân là 6 đều thuộc nguyên tố carbon dù chúng có thể có số neutron khác nhau.",
    "",
    "Đến năm 2016, con người đã biết 118 nguyên tố hoá học, trong đó có 94 nguyên tố hoá học tồn tại trong tự nhiên và 24 nguyên tố được tạo ra trong phòng thí nghiệm, thậm chí có những nguyên tố mới chỉ tạo ra được một lượng rất ít, thời gian tồn tại rất ngắn$^{(*)}$.",
    "",
    "❓",
    "1. Cho các nguyên tử sau: L (Z = 8, A = 16), D (Z = 9, A = 19), E (Z = 8, A = 18), G (Z = 7, A = 15). Trong các nguyên tử trên, các nguyên tử nào thuộc cùng một nguyên tố hoá học?",
    "",
    "II KÍ HIỆU NGUYÊN TỬ",
    "",
    "Số đơn vị điện tích hạt nhân nguyên tử của một nguyên tố hoá học (còn được gọi là số hiệu nguyên tử (Z) của nguyên tố đó) và số khối (A) là những đặc trưng cơ bản của một nguyên tử.",
    "",
    "Số khối A",
    "Số hiệu nguyên tử Z",
    "Kí hiệu nguyên tố X",
    "Hình 2.1. Kí hiệu nguyên tử",
    "",
    "(*) Nguồn: Liên minh Quốc tế về Hoá học cơ bản và Hoá học ứng dụng (IUPAC) (2016).",
    "",
    "17",
    "",
    "Khi viết kí hiệu nguyên tử, đặt hai chỉ số đặc trưng ở bên trái kí hiệu nguyên tố, trong đó số hiệu nguyên tử Z ở phía dưới và số khối A ở phía trên.",
    "Ví dụ: Kí hiệu $^{4}_{2}\\text{He}$ cho biết nguyên tử helium có kí hiệu là He; số hiệu nguyên tử helium bằng 2 nên trong hạt nhân helium có 2 proton, vỏ nguyên tử có 2 electron; số khối của nguyên tử He là 4 nên trong hạt nhân có số neutron là 4 – 2 = 2.",
    "",
    "❓",
    "2. Kí hiệu một nguyên tử cho biết những thông tin gì? Cho ví dụ.",
    "3. Hãy biểu diễn kí hiệu của một số nguyên tử sau:",
    "   a) Nitrogen (số proton = 7 và số neutron = 7).",
    "   b) Phosphorus (số proton = 15 và số neutron = 16).",
    "   c) Copper (đồng) (số proton = 29 và số neutron = 34).",
    "",
    "III ĐỒNG VỊ",
    "",
    "Một số nguyên tử có cùng số đơn vị điện tích hạt nhân (có cùng số proton) nhưng có số neutron khác nhau. Những nguyên tử như thế gọi là các đồng vị (cùng vị trí trong bảng tuần hoàn các nguyên tố hoá học) của một nguyên tố hoá học.",
    "",
    "a) Protium ($^{1}_{1}\\text{H}$)",
    "b) Deuterium ($^{2}_{1}\\text{H}$)",
    "c) Tritium ($^{3}_{1}\\text{H}$)",
    "Hạt electron",
    "Hạt proton",
    "Hạt neutron",
    "Hình 2.2. Mô hình cấu tạo nguyên tử các đồng vị của nguyên tố hydrogen",
    "",
    "Các đồng vị khác nhau về số neutron nên khác nhau về khối lượng của hạt nhân nguyên tử, đồng thời khác nhau về một số tính chất vật lí. Ví dụ: Ở dạng đơn chất, đồng vị $^{37}_{17}\\text{Cl}$ có tỉ khối lớn hơn, nhiệt độ nóng chảy và nhiệt độ sôi cao hơn đồng vị $^{35}_{17}\\text{Cl}$.",
    "",
    "Ngoài các đồng vị bền, các nguyên tố hoá học còn có một số đồng vị không bền. Các đồng vị không bền được gọi là đồng vị phóng xạ. Nhiều đồng vị phóng xạ được sử dụng trong y học, nông nghiệp, nghiên cứu khoa học,...",
    "",
    "❓",
