{
  "content": [
    "IV NGUYÊN TỬ KHỐI",
    "",
    "1. Nguyên tử khối",
    "Nguyên tử khối là khối lượng tương đối của nguyên tử. Nguyên tử khối của một nguyên tử cho biết khối lượng của nguyên tử đó nặng gấp bao nhiêu lần đơn vị khối lượng nguyên tử. Do khối lượng proton và neutron đều xấp xỉ 1,0 amu, còn khối lượng electron nhỏ hơn rất nhiều (0,00055 amu), nên có thể coi nguyên tử khối xấp xỉ số khối.",
    "",
    "Ví dụ: Nguyên tử của nguyên tố potassium (kali) có số proton = 19; số neutron = 20 nên nguyên tử khối của potassium là A = 19 + 20 = 39.",
    "",
    "2. Nguyên tử khối trung bình",
    "Hầu hết các nguyên tố trong tự nhiên là hỗn hợp của nhiều đồng vị, mỗi đồng vị có tỉ lệ phần trăm số nguyên tử xác định. Nguyên tử khối của một nguyên tố là nguyên tử khối trung bình (kí hiệu là $\\overline{A}$) của hỗn hợp các đồng vị của nguyên tố đó.",
    "",
    "Biểu thức tổng quát tính nguyên tử khối trung bình ($\\overline{A}$):",
    "$\\overline{A} = \\frac{(X \\cdot a) + (Y \\cdot b) + \\dots}{100}$",
    "Trong đó, $\\overline{A}$ là nguyên tử khối trung bình; X và Y,... lần lượt là nguyên tử khối của các đồng vị X và Y,...; a và b,... lần lượt là % số nguyên tử của các đồng vị X và Y,...",
    "",
    "Ví dụ: Bằng phương pháp phổ khối lượng, người ta xác định được trong tự nhiên, nguyên tố chlorine có hai đồng vị bền là $^{35}_{17}\\text{Cl}$ (chiếm 75,77%) và $^{37}_{17}\\text{Cl}$ (chiếm 24,23% số nguyên tử) (Hình 2.3).",
    "",
    "Tỉ lệ % số nguyên tử",
    "$^{35}_{17}\\text{Cl}$ (75,77%)",
    "$^{37}_{17}\\text{Cl}$ (24,23%)",
    "m/z$^{(*)}$",
    "Hình 2.3. Phổ khối lượng của chlorine",
    "",
    "Nguyên tử khối trung bình của chlorine:",
    "$\\overline{A} = \\frac{(75,77 \\cdot 35) + (24,23 \\cdot 37)}{100} = 35,48$",
    "",
    "(*) m là khối lượng, z là số đơn vị điện tích của ion. Đối với phổ khối lượng của chlorine: z = 1 nên m/z có giá trị bằng khối lượng nguyên tử hay nguyên tử khối.",
    "",
    "19",
    "",
    "❓",
    "5. Tỉ lệ phần trăm số nguyên tử các đồng vị của neon (Ne) được xác định theo phổ khối lượng (Hình 2.4). Tính nguyên tử khối trung bình của Ne.",
    "6. Vì sao trong bảng tuần hoàn các nguyên tố hoá học, giá trị nguyên tử khối của chromium (Cr) không phải là số nguyên, mà là 51,996?",
    "",
    "Tỉ lệ % số nguyên tử",
    "$^{20}_{10}\\text{Ne}$ (90,0%)",
    "$^{22}_{10}\\text{Ne}$ (9,0%)",
    "$^{21}_{10}\\text{Ne}$ (1,0%)",
    "m/z$^{(*)}$",
    "Hình 2.4. Phổ khối lượng của neon",
    "",
    "7. Copper (đồng) được sử dụng làm dây dẫn điện, huy chương, trống đồng,... Nguyên tử khối trung bình của copper bằng 63,546. Copper tồn tại trong tự nhiên dưới hai dạng đồng vị $^{63}_{29}\\text{Cu}$ và $^{65}_{29}\\text{Cu}$. Tính phần trăm số nguyên tử của đồng vị $^{63}_{29}\\text{Cu}$ tồn tại trong tự nhiên.",
    "",
    "EM ĐÃ HỌC",
    "• Nguyên tố hoá học là tập hợp các nguyên tử có cùng số đơn vị điện tích hạt nhân.",
    "• Đồng vị là những nguyên tử có cùng số đơn vị điện tích hạt nhân (cùng số proton) nhưng có số neutron khác nhau.",
    "• Kí hiệu của nguyên tử: $^{A}_{Z}\\text{X}$.",
    "• Nguyên tử khối cho biết khối lượng nguyên tử đó nặng gấp bao nhiêu lần đơn vị khối lượng nguyên tử.",
    "• Nguyên tử khối của một nguyên tố là nguyên tử khối trung bình của hỗn hợp các đồng vị của nguyên tố đó.",
    "",
    "EM CÓ THỂ",
    "• Xác định được: nguyên tử khối, nguyên tử khối trung bình và phần trăm số nguyên tử các đồng vị của một nguyên tố hoá học.",
    "• Giải thích được vì sao nguyên tử khối của các nguyên tố hoá học không phải là các trị số nguyên và hiểu được sự đa dạng của nguyên tố hoá học trong tự nhiên thông qua khái niệm đồng vị.",
    "",
    "(*) Đối với phổ khối lượng của neon: z = 1 nên m/z có giá trị bằng khối lượng nguyên tử hay nguyên tử khối.",
    "",
    "20",
    "",
    "BÀI 3 CẤU TRÚC LỚP VỎ ELECTRON NGUYÊN TỬ",
    "",
    "MỤC TIÊU:",
    "– Trình bày và so sánh được mô hình của Rutherford – Bohr với mô hình hiện đại mô tả sự chuyển động của electron trong nguyên tử.",
    "– Nêu được khái niệm về orbital nguyên tử (AO), mô tả được hình dạng của AO (s, p), số lượng electron trong 1 AO.",
    "– Trình bày được khái niệm lớp, phân lớp electron và mối quan hệ về số lượng phân lớp trong một lớp. Liên hệ được về số lượng AO trong một phân lớp, trong một lớp.",
    "– Viết được cấu hình electron nguyên tử theo lớp, phân lớp electron và theo ô orbital khi biết số hiệu nguyên tử Z của 20 nguyên tố đầu tiên trong bảng tuần hoàn.",
    "– Dựa vào đặc điểm cấu hình electron lớp ngoài cùng của nguyên tử dự đoán được tính chất hoá học cơ bản (kim loại hay phi kim) của nguyên tố tương ứng.",
    "",
    "❓",
    "Trong nguyên tử các electron chuyển động như thế nào? Sự sắp xếp các electron ở các lớp, các phân lớp tuân theo nguyên lí và quy tắc nào?",
    "",
    "I CHUYỂN ĐỘNG CỦA ELECTRON TRONG NGUYÊN TỬ",
    "",
    "Đến đầu thế kỉ XX, người ta vẫn cho rằng các electron chuyển động xung quanh hạt nhân nguyên tử theo những quỹ đạo tròn hay bầu dục, giống như quỹ đạo của các hành tinh quay xung quanh Mặt Trời (Hình 3.1).",
    "",
    "Mô hình hành tinh nguyên tử đã có ảnh hưởng rất lớn, thúc đẩy sự phát triển lí thuyết cấu tạo nguyên tử, nhưng không đầy đủ để giải thích nhiều tính chất của nguyên tử.",
    "",
    "Electron",
    "Hạt nhân",
    "Quỹ đạo electron",
    "Hình 3.1. Mô hình hành tinh nguyên tử của E.Rutherford (Rơ-dơ-pho), N. Bohr (Bo) và A. Sommerfeld (Zom-mơ-phen)",
    "",
    "Theo mô hình hiện đại, trong nguyên tử, electron chuyển động rất nhanh, không theo quỹ đạo xác định. Tuy nhiên, người ta có thể xác định được vùng không gian xung quanh hạt nhân mà ở đó xác suất có mặt (xác suất tìm thấy) electron là lớn nhất (khoảng 90%). Vùng không gian xung quanh hạt nhân tìm thấy electron có thể hình dung như một đám mây electron, được gọi là orbital nguyên tử (Hình 3.2). Orbital nguyên tử được kí hiệu là AO (Atomic Orbital).",
    "",
    "Hình 3.2. Mô hình đám mây electron của nguyên tử hydrogen",
    "",
    "21",
    "",
    "1. Hình dạng orbital nguyên tử",
    "",
    "Khi chuyển động trong nguyên tử, các electron có những mức năng lượng khác nhau đặc trưng cho trạng thái chuyển động của nó. Dựa trên sự khác nhau về hình dạng, sự định hướng của orbital trong nguyên tử để phân loại orbital thành orbital s, orbital p, orbital d và orbital f. Các orbital s có dạng hình cầu và orbital p có dạng hình số 8 nổi (Hình 3.3).",
    "",
