    "  Có thể thay 1$s^2$ bằng kí hiệu [He]. Cấu hình electron của nguyên tử O là 1$s^2$2$s^2$2$p^4$ hoặc [He]2$s^2$2$p^4$ hoặc (2, 6).",
    "  Electron cuối cùng điền vào phân lớp p nên oxygen là nguyên tố p.",
