    "1$s^2$  2$s^2$     2$p^3$",
    "",
    "Hai ô orbital 1s và 2s có đủ 2 electron được biểu diễn bằng hai mũi tên ngược chiều nhau (nguyên lí Pauli). 3 electron còn lại được sắp xếp vào 3 ô orbital 2p bằng 3 mũi tên đi lên để số electron độc thân là tối đa (quy tắc Hund).",
    "",
    "❓",
    "6. Cấu hình electron của nguyên tử có Z = 16 là",
    "   A. 1$s^2$2$s^2$2$p^6$3$s^2$3$p^3$.",
    "   B. 1$s^2$2$s^2$2$p^6$3$s^2$3$p^5$.",
    "   C. 1$s^2$2$s^2$2$p^6$3$s^2$3$p^4$.",
    "   D. 1$s^2$2$s^2$2$p^5$3$s^2$3$p^5$.",
    "7. Biểu diễn cấu hình electron của các nguyên tử có Z = 8 và Z = 11 theo ô orbital.",
    "",
    "24",
    "",
    "3. Đặc điểm của lớp electron ngoài cùng",
    "Các electron lớp ngoài cùng quyết định tính chất hoá học cơ bản của nguyên tố (kim loại, phi kim, khí hiếm).",
    "Các nguyên tử có 8 electron lớp ngoài cùng đều rất bền vững, chúng hầu như không tham gia vào các phản ứng hoá học, đó là các nguyên tử khí hiếm (riêng He có số electron lớp ngoài cùng là 2).",
    "Các nguyên tố mà nguyên tử có 1, 2, 3 electron ở lớp ngoài cùng là kim loại (trừ H, He, B).",
    "Các nguyên tố mà nguyên tử có 5, 6, 7 electron ở lớp ngoài cùng thường là phi kim.",
    "Các nguyên tố mà nguyên tử có 4 electron ở lớp ngoài cùng có thể là kim loại hoặc phi kim.",
    "",
    "❓",
    "8. Silicon được sử dụng trong nhiều ngành công nghiệp: gốm, men sứ, thuỷ tinh, luyện thép, vật liệu bán dẫn,... Hãy biểu diễn cấu hình electron của nguyên tử silicon (Z = 14) theo ô orbital, chỉ rõ việc áp dụng các nguyên lí vững bền, nguyên lí Pauli và quy tắc Hund.",
    "9. Chlorine (Z = 17) thường được sử dụng để khử trùng nước máy trong sinh hoạt. Viết cấu hình electron của nguyên tử chlorine và cho biết tại sao chlorine là phi kim.",
    "",
    "EM ĐÃ HỌC",
    "• Khái niệm về orbital nguyên tử theo mô hình hiện đại về sự chuyển động của electron trong nguyên tử (hình dạng các orbital s, p và biểu diễn ô orbital).",
    "• Lớp electron: chứa các electron có mức năng lượng gần bằng nhau.",
    "• Phân lớp electron: chứa các electron có mức năng lượng bằng nhau.",
    "• Số orbital trong một phân lớp: s(1); p(3); d(5); f(7) và số orbital trong một lớp: $n^2$ (n $\\leq$ 4).",
    "• Cấu hình electron của nguyên tử và cách viết cấu hình electron của 20 nguyên tố đầu tiên trong bảng tuần hoàn tuân theo: nguyên lí vững bền, nguyên lí Pauli và quy tắc Hund.",
    "• Dựa vào đặc điểm về cấu hình electron lớp ngoài cùng để dự đoán tính chất hoá học cơ bản của nguyên tố:",
    "  – Nguyên tố mà nguyên tử đủ 8 electron lớp ngoài cùng là khí hiếm (trừ He).",
    "  – Nguyên tố mà nguyên tử có 1, 2, 3 electron lớp ngoài cùng thường là nguyên tố kim loại.",
    "  – Các nguyên tố mà nguyên tử có 4 electron ở lớp ngoài cùng có thể là kim loại hoặc phi kim.",
    "  – Nguyên tố mà nguyên tử có 5, 6, 7 electron lớp ngoài cùng thường là nguyên tố phi kim.",
    "",
    "EM CÓ THỂ",
    "Viết được cấu hình electron nguyên tử của một số nguyên tố hoá học quen thuộc trong thực tế như: nitrogen, oxygen, aluminium,... và dự đoán được tính chất hoá học cơ bản của chúng.",
    "",
    "25",
    "",
    "BÀI 4 ÔN TẬP CHƯƠNG 1",
    "",
    "I HỆ THỐNG HOÁ KIẾN THỨC",
    "Hoàn thành sơ đồ hệ thống hoá kiến thức sau:",
    "",
    "HẠT NHÂN",
    "|— Hạt neutron —> Khối lượng = ..?..; Điện tích = ..?..",
    "|— Hạt proton —> Khối lượng = ..?..; Điện tích = ..?..",
    "",
    "Kích thước: ..?..",
    "Khối lượng: ..?..",
    "Z = ..?.. = ..?..",
    "",
    "NGUYÊN TỬ",
    "|— VỎ NGUYÊN TỬ",
    "    |— Hạt electron —> Khối lượng = ..?..; Điện tích = ..?..",
    "    |— AO s có dạng ..?..; AO p gồm ..?.., ..?.., ..?..; AO p có dạng ..?..",
    "    |— n | 1 | 2 | 3 | 4",
    "       Lớp electron | | | |",
    "       Phân lớp | | | |",
    "       Số AO | | | |",
    "       Số electron tối đa | | | |",
    "    |— Thứ tự các phân lớp có năng lượng từ thấp đến cao: ...?...",
    "    |— Cấu hình electron",
    "       Nguyên lí vững bền: ..?..",
    "       Nguyên lí Pauli: ..?..",
    "       Quy tắc Hund: ..?..",
    "       Đặc điểm của lớp electron ngoài cùng",
    "       Số electron | 1, 2, 3 | 4 | 5, 6, 7 | 8",
    "       Loại nguyên tố | | | |",
    "",
    "NGUYÊN TỐ HOÁ HỌC",
    "|— Số khối (A) = ..?.. + ..?..",
    "|— Kí hiệu nguyên tử $^{A}_{Z}\\text{X}$",
    "|— Đồng vị $^{b}_{a}\\text{X}$ và $^{d}_{a}\\text{X}$ $\\Rightarrow \\overline{\\text{A}} = \\frac{..?.. \\times ..?.. + ..?.. \\times ..?..}{..?.. + ..?..}$",
    "",
    "26",
    "",
    "II LUYỆN TẬP",
    "",
    "Câu 1. Số proton, neutron và electron của $^{39}_{19}\\text{K}$ lần lượt là",
    "A. 19, 20, 39.          B. 20, 19, 39.          C. 19, 20, 19.          D. 19, 19, 20.",
    "",
    "Câu 2. Nguyên tử của nguyên tố nào sau đây có 3 electron thuộc lớp ngoài cùng?",
    "A. $^{23}_{11}\\text{Na}$.          B. $^{14}_{7}\\text{N}$.          C. $^{27}_{13}\\text{Al}$.          D. $^{12}_{6}\\text{C}$.",
    "",
    "Câu 3. Nguyên tử của nguyên tố potassium có 19 electron. Ở trạng thái cơ bản, potassium có số orbital chứa electron là",
    "A. 8.          B. 9.          C. 11.          D. 10.",
    "",
    "Câu 4. Nguyên tử của nguyên tố sodium (natri) (Z=11) có cấu hình electron là",
    "A. 1$s^2$2$s^2$2$p^6$3$s^2$.          B. 1$s^2$2$s^2$2$p^6$.          C. 1$s^2$2$s^2$2$p^6$3$s^1$.          D. 1$s^2$2$s^2$2$p^5$3$s^2$.",
    "",
    "Câu 5. Tổng số hạt proton, neutron và electron trong nguyên tử X là 58. Số hạt mang điện nhiều hơn số hạt không mang điện là 18. X là",
    "A. Cl.          B. Ca.          C. K.          D. S.",
    "",
    "Câu 6. Nguyên tố chlorine có Z = 17. Hãy cho biết số lớp electron, số electron thuộc lớp ngoài cùng, số electron độc thân của nguyên tử chlorine.",
    "",
    "Câu 7. Nguyên tử khối trung bình của vanadium (V) là 50,9975. Nguyên tố V có 2 đồng vị trong đó đồng vị $^{50}_{23}\\text{V}$ chiếm 0,25%. Tính số khối của đồng vị còn lại.",
    "",
    "Câu 8. Cấu hình electron của:",
    "– Nguyên tử X: 1$s^2$2$s^2$2$p^6$3$s^2$3$p^6$4$s^1$;",
    "– Nguyên tử Y: 1$s^2$2$s^2$2$p^6$3$s^2$3$p^4$.",
    "a) Mỗi nguyên tử X và Y chứa bao nhiêu electron?",
    "b) Hãy cho biết số hiệu nguyên tử của X và Y.",
    "c) Lớp electron nào trong nguyên tử X và Y có mức năng lượng cao nhất?",
    "d) Mỗi nguyên tử X và Y có bao nhiêu lớp electron, bao nhiêu phân lớp electron?",
    "e) X và Y là nguyên tố kim loại, phi kim hay khí hiếm?",
    "",
    "Câu 9. Nguyên tố X được dùng để chế tạo hợp kim nhẹ, bền, dùng trong nhiều lĩnh vực: hàng không, ô tô, xây dựng, hàng tiêu dùng,... Nguyên tố Y ở dạng $\\text{YO}^{3-}_4$, đóng vai trò quan trọng trong các phân tử sinh học như DNA và RNA. Các tế bào sống sử dụng $\\text{YO}^{3-}_4$ để vận chuyển năng lượng. Nguyên tử của nguyên tố X có cấu hình electron kết thúc ở phân lớp 3$p^1$. Nguyên tử của nguyên tố Y có cấu hình electron kết thúc ở phân lớp 3$p^3$. Viết cấu hình electron nguyên tử của X và Y. Tính số electron trong các nguyên tử X và Y. Nguyên tố X và Y có tính kim loại hay phi kim?",
    "",
    "Câu 10. Nguyên tử của nguyên tố X có tổng số hạt cơ bản (proton, electron, neutron) là 49, trong đó số hạt không mang điện bằng 53,125% số hạt mang điện. Xác định điện tích hạt nhân, số proton, số electron, số neutron và số khối của X.",
    "",
    "27"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

