INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'BAI_5', 'CẤU TẠO CỦA BẢNG TUẦN HOÀN CÁC NGUYÊN TỐ HOÁ HỌC', 30, 5, $JSON$
{
  "content": [
    "BÀI 5 CẤU TẠO CỦA BẢNG TUẦN HOÀN CÁC NGUYÊN TỐ HOÁ HỌC",
    "",
    "MỤC TIÊU:",
    "– Nêu được lịch sử phát minh định luật tuần hoàn và bảng tuần hoàn các nguyên tố hoá học.",
    "– Mô tả được cấu tạo của bảng tuần hoàn các nguyên tố hoá học và nêu được các khái niệm liên quan (ô, chu kì, nhóm).",
    "– Nêu được nguyên tắc sắp xếp của bảng tuần hoàn các nguyên tố hoá học (dựa theo cấu hình electron).",
    "– Phân loại được nguyên tố (dựa theo cấu hình electron: nguyên tố s, p, d, f; dựa theo tính chất hoá học: kim loại, phi kim, khí hiếm).",
    "",
    "❓",
    "Bảng tuần hoàn các nguyên tố hoá học có cấu tạo như thế nào? Trong bảng tuần hoàn, các nguyên tố được sắp xếp theo nguyên tắc nào?",
    "",
    "I LỊCH SỬ PHÁT MINH BẢNG TUẦN HOÀN CÁC NGUYÊN TỐ HOÁ HỌC",
    "",
    "Khi đã biết một số đáng kể các nguyên tố hoá học, người ta đã tìm cách phân loại chúng. Cách phân loại đầu tiên được A. Lavoisier (La-voa-di-ê, người Pháp) thực hiện năm 1789, xếp 33 nguyên tố hoá học thành nhóm các chất khí, kim loại, phi kim và \"đất\".",
    "Năm 1829, J. W. Döbereiner (Đô-be-rai-nơ, người Đức) phân loại các nguyên tố thành các nhóm có tính chất hoá học giống nhau, ví dụ: lithium, sodium và potassium là nhóm các kim loại mềm, dễ phản ứng. Năm 1866, J. Newlands (Niu-lan, người Anh) đã xếp các nguyên tố hoá học theo chiều tăng khối lượng nguyên tử thành các octave (quãng tám), trong đó nguyên tố thứ tám lặp lại tính chất của nguyên tố đầu tiên.",
    "Năm 1869, hai nhà hoá học, D. I. Mendeleev (Men-đê-lê-ép, người Nga) và J. L. Meyer (May-ơ, người Đức) đều sắp xếp các nguyên tố theo chiều tăng khối lượng nguyên tử vào các hàng và cột, bắt đầu mỗi hàng (bảng của Mendeleev) hoặc cột mới (bảng của Meyer) khi các tính chất của nguyên tố bắt đầu lặp lại. Trong bảng tuần hoàn các nguyên tố hoá học của mình, Mendeleev đã thay đổi vị trí một số nguyên tố để tính chất của nguyên tố phù hợp với quy luật, đồng thời để trống một số chỗ cho các nguyên tố chưa biết.",
    "Sau này, các nguyên tố ở vị trí còn trống đó được tìm ra và tính chất của chúng đều phù hợp với dự đoán của Mendeleev.",
    "",
    "Hình 5.1. Bảng tuần hoàn của D. I. Mendeleev năm 1869",
    "",
    "30",
    "",
    "Đến năm 2016, với những hiểu biết về cấu tạo nguyên tử, bảng tuần hoàn các nguyên tố hoá học hiện đại sắp xếp 118 nguyên tố theo chiều tăng của điện tích hạt nhân nguyên tử.",
    "",
    "❓",
    "1. Theo tiến trình lịch sử, các nhà khoa học đã phân loại các nguyên tố hoá học dựa trên các cơ sở nào?",
    "",
    "II NGUYÊN TẮC SẮP XẾP CÁC NGUYÊN TỐ TRONG BẢNG TUẦN HOÀN",
    "",
    "Bảng tuần hoàn chứa 118 nguyên tố hoá học được sắp xếp theo các nguyên tắc sau:",
    "• Các nguyên tố được sắp xếp theo chiều tăng dần điện tích hạt nhân nguyên tử.",
    "• Các nguyên tố có cùng số lớp electron trong nguyên tử được xếp thành một hàng.",
    "• Các nguyên tố có cùng số electron hoá trị trong nguyên tử được xếp thành một cột.",
    "Khi sắp xếp như vậy, sự tuần hoàn tính chất của các đơn chất và hợp chất được thể hiện qua chu kì (hàng) và nhóm (cột).",
    "",
    "EM CÓ BIẾT",
    "Electron hoá trị là các electron có khả năng tham gia tạo thành liên kết hoá học, chúng thường nằm ở lớp electron ngoài cùng và phân lớp sát lớp ngoài cùng.",
    "",
    "❓",
    "2. Trong bảng tuần hoàn, các nguyên tố hoá học được sắp xếp theo ba nguyên tắc, nguyên tắc nào sau đây là đúng?",
    "A. Nguyên tử khối tăng dần.                 B. Cùng số lớp electron xếp cùng cột.",
    "C. Điện tích hạt nhân tăng dần.               D. Cùng số electron hoá trị xếp cùng hàng.",
    "",
    "III CẤU TẠO CỦA BẢNG TUẦN HOÀN",
    "1. Ô nguyên tố",
    "Trong bảng tuần hoàn, mỗi nguyên tố được xếp vào một ô, gọi là ô nguyên tố. Số thứ tự của ô là số hiệu nguyên tử của nguyên tố đó. Mỗi ô nguyên tố có các thông tin quan trọng nhất về nguyên tố hoá học. Tuỳ theo từng loại bảng, các thông tin này có thể là số hiệu nguyên tử, kí hiệu nguyên tố, tên nguyên tố, nguyên tử khối trung bình,...",
    "",
    "Số hiệu nguyên tử",
    "|",
    "13      Al  — Kí hiệu nguyên tố",
    "|",
    "aluminium  — Tên nguyên tố",
    "26,982  — Nguyên tử khối trung bình",
    "",
    "Hình 5.2. Một ô nguyên tố",
    "",
    "31",
    "",
    "2. Chu kì",
    "Chu kì là dãy các nguyên tố mà nguyên tử của chúng có cùng số lớp electron, được xếp theo chiều điện tích hạt nhân tăng dần.",
    "Bảng tuần hoàn hiện nay có 7 chu kì. Số thứ tự của chu kì bằng số lớp electron của nguyên tử các nguyên tố trong chu kì.",
    "*Chu kì 1:* gồm 2 nguyên tố là H và He, đều có 1 lớp electron",
    "*Chu kì 2:* gồm 8 nguyên tố từ Li đến Ne, đều có 2 lớp electron.",
    "*Chu kì 3:* gồm 8 nguyên tố từ Na đến Ar, đều có 3 lớp electron.",
    "*Chu kì 4:* gồm 18 nguyên tố từ K đến Kr, đều có 4 lớp electron.",
    "*Chu kì 5:* gồm 18 nguyên tố từ Rb đến Xe, đều có 5 lớp electron.",
    "*Chu kì 6$^{\\text{(*)}}$:* gồm 32 nguyên tố từ Cs đến Rn, đều có 6 lớp electron.",
    "*Chu kì 7$^{\\text{(*)}}$:* gồm 32 nguyên tố từ Fr đến Og, đều có 7 lớp electron.",
    "",
    "3. Nhóm nguyên tố",
    "Nhóm nguyên tố gồm các nguyên tố mà nguyên tử của chúng có cấu hình electron tương tự nhau, do đó có tính chất hoá học gần giống nhau và được xếp thành một cột.",
    "Bảng tuần hoàn hiện nay có 18 cột, chia thành 8 nhóm A (IA đến VIIIA) và 8 nhóm B (IB đến VIIIB). Mỗi nhóm là một cột, riêng nhóm VIIIB gồm 3 cột.",
    "Ví dụ: Nhóm kim loại kiềm – nhóm IA, nhóm halogen – nhóm VIIA.",
    "Nguyên tử các nguyên tố trong cùng một nhóm A có số electron hoá trị bằng nhau và bằng số thứ tự của nhóm (trừ He).",
    "",
    "4. Phân loại nguyên tố",
    "a) Theo cấu hình electron",
    "Các nguyên tố s, p, d, f là những nguyên tố mà nguyên tử có electron cuối cùng được điền vào phân lớp s, p, d, f tương ứng.",
    "Ví dụ: $_{11}\\text{Na}$: 1s$^2$2s$^2$2p$^6$3s$^1$ (nguyên tố s);",
    "       $_{13}\\text{Al}$: 1s$^2$2s$^2$2p$^6$3s$^2$3p$^1$ (nguyên tố p).",
    "Các nhóm A: gồm các nguyên tố s (IA, IIA) và nguyên tố p (từ IIIA đến VIIIA, trừ He).",
    "Các nhóm B: gồm các nguyên tố d (từ IB đến VIIIB) và các nguyên tố f (lanthanides và actinides).",
    "",
    "b) Theo tính chất hoá học",
    "Các nhóm IA, IIA, IIIA: gồm các nguyên tố s và p là kim loại (trừ H và B).",
    "Các nhóm VA, VIA, VIIA: gồm các nguyên tố p, thường là phi kim.",
    "Nhóm VIIIA: gồm các nguyên tố khí hiếm.",
    "Các nhóm B: gồm các nguyên tố d và f đều là kim loại chuyển tiếp.",
    "",
    "(* ) 14 nguyên tố từ La đến Lu thuộc chu kì 6 (các nguyên tố họ lanthanide) và 14 nguyên tố từ Ac đến Lr thuộc chu kì 7 (các nguyên tố họ actinide) được xếp thành hai hàng ở cuối bảng do có tính chất hoá học tương tự nhau.",
    "",
    "32",
    "",
    "❓",
    "3. Ô nguyên tố trong bảng tuần hoàn cho ta biết những thông tin gì? Lấy ví dụ minh hoạ.",
    "4. Dựa vào bảng tuần hoàn, hãy cho biết cấu hình electron và số electron hoá trị của các nguyên tố: C, Mg và Cl.",
    "5. Dựa vào bảng tuần hoàn, hãy cho biết: $_{12}\\text{Mg}$, $_{15}\\text{P}$, $_{26}\\text{Fe}$, $_{18}\\text{Ar}$ thuộc loại nguyên tố nào sau đây.",
    "   a) s, p, d hay f?                    b) phi kim, kim loại hay khí hiếm?",
    "6. Nguyên tố phosphorus có Z = 15, có trong thành phần của một số loại phân bón, diêm, pháo hoa; nguyên tố calcium có Z = 20, đóng vai trò rất quan trọng đối với cơ thể, đặc biệt là xương và răng. Xác định vị trí của hai nguyên tố trên trong bảng tuần hoàn và cho biết chúng thuộc loại nguyên tố s, p hay d; là kim loại, phi kim hay khí hiếm.",
    "7. Sulfur (lưu huỳnh) là chất rắn, xốp, màu vàng nhạt ở điều kiện thường. Sulfur và hợp chất của nó được sử dụng trong acquy, bột giặt, thuốc diệt nấm; do dễ cháy nên sulfur còn được dùng để sản xuất các loại diêm, thuốc súng, pháo hoa,... Trong bảng tuần hoàn, nguyên tố sulfur nằm ở chu kì 3, nhóm VIA.",
    "   a) Nguyên tử của nguyên tố sulfur có bao nhiêu electron thuộc lớp ngoài cùng?",
    "   b) Các electron lớp ngoài cùng thuộc những phân lớp nào?",
    "   c) Viết cấu hình electron nguyên tử của sulfur.",
    "   d) Sulfur là nguyên tố kim loại hay phi kim?",
    "",
    "EM ĐÃ HỌC",
    "• Các nguyên tố trong bảng tuần hoàn được sắp xếp theo chiều tăng dần của điện tích hạt nhân, thành các hàng và các cột.",
    "• Cấu tạo của bảng tuần hoàn các nguyên tố hoá học:",
    "  – Ô nguyên tố: cho biết số hiệu nguyên tử, kí hiệu nguyên tố, tên nguyên tố và nguyên tử khối trung bình,...",
    "  – Chu kì là dãy các nguyên tố mà nguyên tử của chúng có cùng số lớp electron, được xếp theo chiều điện tích hạt nhân tăng dần.",
    "  – Nhóm gồm các nguyên tố mà nguyên tử có cấu hình electron tương tự nhau, do đó có tính chất hoá học gần giống nhau.",
    "",
    "EM CÓ THỂ",
    "Xác định được vị trí các nguyên tố hoá học trong bảng tuần hoàn và phân loại được thành nguyên tố s, p, d, f hay nguyên tố kim loại, phi kim, khí hiếm.",
    "",
    "33"
  ]
}
