    "1. Dựa vào Bảng 6.1, cho biết số electron lớp ngoài cùng của nguyên tử các nguyên tố: Li, Al, Ar, Ca, Si, Se, P, Br.",
    "2. Nêu vị trí trong bảng tuần hoàn của các nguyên tố có Z = 8; Z = 11; Z = 17 và Z = 20. Xác định số electron hoá trị của nguyên tử các nguyên tố đó.",
