    "*Hình 6.3. Sự biến đổi năng lượng ion hoá thứ nhất của các nguyên tố chu kì 1, 2 và 3*",
    "",
    "Năng lượng ion hoá thứ nhất của nguyên tử là năng lượng tối thiểu cần thiết để tách electron thứ nhất ra khỏi nguyên tử ở thể khí, ở trạng thái cơ bản: X(g)$^{(*)}$ $\\rightarrow$ X$^+$(g) + e",
    "Năng lượng ion hoá thứ nhất kí hiệu là I$_1$, đơn vị là kJ/mol.",
