    "36",
    "",
    "*Bảng 6.2. Giá trị độ âm điện tương đối theo L. C. Pauling*",
    "",
    "| Nhóm \\ Chu kì | IA | IIA | IIIA | IVA | VA | VIA | VIIA |",
    "|---|---|---|---|---|---|---|---|",
    "| 1 | $_1\\text{H}$ (2,20) | | | | | | |",
    "| 2 | $_3\\text{Li}$ (0,98) | $_4\\text{Be}$ (1,57) | $_5\\text{B}$ (2,04) | $_6\\text{C}$ (2,55) | $_7\\text{N}$ (3,04) | $_8\\text{O}$ (3,44) | $_9\\text{F}$ (3,98) |",
    "| 3 | $_{11}\\text{Na}$ (0,93) | $_{12}\\text{Mg}$ (1,31) | $_{13}\\text{Al}$ (1,61) | $_{14}\\text{Si}$ (1,90) | $_{15}\\text{P}$ (2,19) | $_{16}\\text{S}$ (2,58) | $_{17}\\text{Cl}$ (3,16) |",
    "| 4 | $_{19}\\text{K}$ (0,82) | $_{20}\\text{Ca}$ (1,00) | $_{31}\\text{Ga}$ (1,81) | $_{32}\\text{Ge}$ (2,01) | $_{33}\\text{As}$ (2,18) | $_{34}\\text{Se}$ (2,55) | $_{35}\\text{Br}$ (2,96) |",
    "| 5 | $_{37}\\text{Rb}$ (0,82) | $_{38}\\text{Sr}$ (0,95) | $_{49}\\text{In}$ (1,78) | $_{50}\\text{Sn}$ (1,96) | $_{51}\\text{Sb}$ (2,05) | $_{52}\\text{Te}$ (2,10) | $_{53}\\text{I}$ (2,66) |",
    "| 6 | $_{55}\\text{Cs}$ (0,79) | $_{56}\\text{Ba}$ (0,89) | $_{81}\\text{Tl}$ (1,62) | $_{82}\\text{Pb}$ (2,33) | $_{83}\\text{Bi}$ (2,02) | $_{84}\\text{Po}$ (2,00) | $_{85}\\text{At}$ (2,20) |",
    "",
    "Độ âm điện",
    "4,0",
    "3,0",
    "2,0",
    "1,0",
    "5       10      15      20",
    "Số đơn vị điện tích hạt nhân",
    "",
    "*Hình 6.4. Sự biến đổi độ âm điện theo chu kì và nhóm*",
    "",
    "Xu hướng biến đổi độ âm điện theo chiều tăng dần của điện tích hạt nhân:",
    "• Độ âm điện tăng từ trái qua phải trong một chu kì.",
    "Trong một chu kì, khi số electron lớp ngoài cùng tăng, điện tích hạt nhân tăng thì lực hút giữa hạt nhân với các electron lớp ngoài cùng tăng nên độ âm điện tăng.",
    "• Độ âm điện giảm từ trên xuống dưới trong một nhóm A.",
    "Trong một nhóm A, khi số lớp electron tăng, lực hút giữa hạt nhân với các electron lớp ngoài cùng giảm nên độ âm điện giảm.",
    "",
    "❓",
    "4. Dãy các nguyên tố được sắp xếp theo thứ tự độ âm điện tăng dần là Ca, Mg, P, S. Hãy giải thích sự sắp xếp này dựa trên sự biến đổi độ âm điện theo chu kì và nhóm A.",
    "5. Almelec là hợp kim của aluminium với một lượng nhỏ magnesium và silicon (98,8% aluminium; 0,7% magnesium và 0,5% silicon). Almelec được sử dụng làm dây điện cao thế do nhẹ, dẫn điện tốt và bền. Dựa vào bảng tuần hoàn các nguyên tố hoá học, hãy:",
    "   a) Sắp xếp theo thứ tự tăng dần về bán kính nguyên tử của các nguyên tố hoá học có trong almelec.",
    "   b) Cho biết thứ tự giảm dần về độ âm điện của các nguyên tố hoá học có trong almelec.",
    "",
    "37",
    "",
    "IV TÍNH KIM LOẠI VÀ TÍNH PHI KIM",
    "",
    "1. Khái niệm",
    "Tính kim loại là tính chất của một nguyên tố mà nguyên tử của nó dễ nhường electron để trở thành ion dương. Nguyên tử của nguyên tố nào càng dễ nhường electron để trở thành ion dương, tính kim loại của nguyên tố đó càng mạnh.",
    "Tính phi kim là tính chất của một nguyên tố mà nguyên tử của nó dễ nhận electron để trở thành ion âm. Nguyên tử của nguyên tố nào càng dễ nhận electron để trở thành ion âm, tính phi kim của nguyên tố đó càng mạnh.",
    "",
    "2. Sự biến đổi tính kim loại, tính phi kim",
    "1. So sánh tính kim loại của sodium và magnesium",
    "*Chuẩn bị:* kim loại Na; Mg; dung dịch phenolphthalein; nước; cốc thuỷ tinh.",
    "*Tiến hành:*",
    "– Lấy hai cốc thuỷ tinh, mỗi cốc có chứa khoảng 200 mL nước, nhỏ tiếp vài giọt dung dịch phenolphthalein.",
    "– Cho một mẩu nhỏ Na vào cốc (1), một dây Mg vào cốc (2).",
    "*Lưu ý: Hầu hết các kim loại kiềm phản ứng với nước mãnh liệt, chỉ sử dụng các kim loại kiềm với lượng nhỏ; cần làm sạch bề mặt dây Mg trước khi cho vào cốc (2).*",
    "*Quan sát hiện tượng và thực hiện yêu cầu sau:*",
    "1. Viết phương trình hoá học của các phản ứng.",
    "2. So sánh mức độ phản ứng của sodium và magnesium với nước.",
    "",
    "2. So sánh tính phi kim của chlorine và iodine",
    "*Chuẩn bị:* Hình ảnh hoặc video phản ứng của nước chlorine với dung dịch potassium iodide$^{(*)}$.",
    "*Tiến hành:* Quan sát hình ảnh hoặc xem video phản ứng của nước chlorine với dung dịch potassium iodide.",
    "*Câu hỏi:* So sánh tính phi kim của chlorine và iodine.",
    "",
    "Nước chlorine",
    "$\\rightarrow$",
    "Dung dịch potassium iodide",
    "",
    "*Hình 6.5. Phản ứng của nước chlorine với dung dịch potassium iodide*",
    "",
    "Xu hướng biến đổi tính kim loại và tính phi kim:",
    "– Trong một chu kì, theo chiều tăng dần của điện tích hạt nhân, tính kim loại giảm dần và tính phi kim tăng dần. Do bán kính nguyên tử giảm, lực hút giữa hạt nhân với các electron lớp ngoài cùng tăng, dẫn đến khả năng nhường electron giảm nên tính kim loại giảm, khả năng nhận electron tăng nên tính phi kim tăng.",
    "",
    "(* ) Nguồn: Youtube.com",
    "",
    "38",
    "",
    "Ví dụ:",
    "",
    "| Chu kì 3 | $_{11}\\text{Na}$ | $_{12}\\text{Mg}$ | $_{13}\\text{Al}$ | $_{14}\\text{Si}$ | $_{15}\\text{P}$ | $_{16}\\text{S}$ | $_{17}\\text{Cl}$ |",
    "|---|---|---|---|---|---|---|---|",
    "| | Kim loại điển hình | Kim loại mạnh | Kim loại hoạt động | Phi kim rất yếu | Phi kim yếu | Phi kim trung bình | Phi kim điển hình |",
    "",
    "Chiều giảm tính kim loại và tăng tính phi kim $\\rightarrow$",
    "",
    "– Trong một nhóm A, theo chiều tăng dần của điện tích hạt nhân, tính kim loại tăng dần và tính phi kim giảm dần. Tuy điện tích hạt nhân tăng, nhưng bán kính nguyên tử tăng nhanh và chiếm ưu thế hơn nên lực hút giữa hạt nhân với các electron lớp ngoài cùng giảm dẫn đến khả năng nhường electron tăng, do đó tính kim loại tăng, khả năng nhận electron giảm nên tính phi kim giảm.",
    "",
    "Ví dụ:",
    "Nhóm IA: $_{3}\\text{Li}$ $_{11}\\text{Na}$ $_{19}\\text{K}$ $_{37}\\text{Rb}$ $_{55}\\text{Cs}$",
    "Chiều tăng tính kim loại $\\rightarrow$",
    "",
    "Nhóm VIIA: $_{9}\\text{F}$ $_{17}\\text{Cl}$ $_{35}\\text{Br}$ $_{53}\\text{I}$",
    "Chiều giảm tính phi kim $\\rightarrow$",
    "",
    "❓",
    "6. Dựa vào bảng tuần hoàn các nguyên tố hoá học, sắp xếp các nguyên tố Ba, Mg, Ca, Sr theo thứ tự giảm dần tính kim loại và giải thích.",
    "7. Trong các nguyên tố O, F, Cl, Se, nguyên tố có tính phi kim mạnh nhất là",
    "   A. O.               B. F.               C. Se.              D. Cl.",
    "",
    "EM ĐÃ HỌC",
    "Theo chiều tăng dần của điện tích hạt nhân nguyên tử:",
    "• Trong một chu kì:",
    "  – Bán kính nguyên tử giảm dần, độ âm điện tăng dần.",
    "  – Tính kim loại giảm dần và tính phi kim tăng dần.",
    "  – Số electron hoá trị của nguyên tử các nguyên tố nhóm A tăng lần lượt từ 1 đến 8.",
    "• Trong một nhóm A:",
    "  – Bán kính nguyên tử tăng dần, độ âm điện giảm dần.",
    "  – Tính kim loại tăng dần và tính phi kim giảm dần.",
    "",
    "EM CÓ THỂ",
    "So sánh và giải thích được xu hướng biến đổi một số tính chất của các nguyên tố theo vị trí của chúng trong bảng tuần hoàn các nguyên tố hoá học.",
    "",
    "39"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'BAI_7', 'XU HƯỚNG BIẾN ĐỔI THÀNH PHẦN VÀ MỘT SỐ TÍNH CHẤT CỦA HỢP CHẤT TRONG MỘT CHU KÌ', 40, 7, $JSON$
{
  "content": [
    "BÀI 7 XU HƯỚNG BIẾN ĐỔI THÀNH PHẦN VÀ MỘT SỐ TÍNH CHẤT CỦA HỢP CHẤT TRONG MỘT CHU KÌ",
    "",
    "MỤC TIÊU:",
    "Nhận xét được xu hướng biến đổi thành phần và tính acid – base của các oxide và các hydroxide theo chu kì. Viết được phương trình hoá học minh hoạ.",
    "",
    "❓",
    "Trong một chu kì của bảng tuần hoàn, tính chất của các oxide và hydroxide biến đổi theo xu hướng nào?",
    "",
    "I THÀNH PHẦN CỦA CÁC OXIDE VÀ HYDROXIDE",
    "",
    "Hoá trị cao nhất của các nguyên tố nhóm A trong hợp chất với oxygen tăng từ I đến VII khi đi từ trái qua phải trong một chu kì (trừ chu kì 1 và nguyên tố fluorine ở chu kì 2), do đó thành phần của các oxide và hydroxide có sự lặp lại theo chu kì.",
    "",
    "*Bảng 7.1. Công thức oxide, hydroxide ứng với hoá trị cao nhất của các nguyên tố thuộc chu kì 2, 3*",
    "",
    "| | Nhóm | IA | IIA | IIIA | IVA | VA | VIA | VIIA |",
    "|---|---|---|---|---|---|---|---|---|",
    "| Oxide | Chu kì 2 | Li$_2$O | BeO | B$_2$O$_3$ | CO$_2$ | N$_2$O$_5$ | | |",
    "| | Chu kì 3 | Na$_2$O | MgO | Al$_2$O$_3$ | SiO$_2$ | P$_2$O$_5$ | SO$_3$ | Cl$_2$O$_7$ |",
    "| Hydroxide | Chu kì 2 | LiOH | Be(OH)$_2$ | H$_3$BO$_3$ | H$_2$CO$_3$ | HNO$_3$ | | |",
    "| | Chu kì 3 | NaOH | Mg(OH)$_2$ | Al(OH)$_3$ | H$_2$SiO$_3$ | H$_3$PO$_4$ | H$_2$SO$_4$ | HClO$_4$ |",
    "",
    "❓",
    "1. Nguyên tố gallium thuộc nhóm IIIA và nguyên tố selenium thuộc nhóm VIA của bảng tuần hoàn. Viết công thức hoá học của oxide, hydroxide (ứng với hoá trị cao nhất) của hai nguyên tố trên.",
    "",
    "40",
    "",
    "II TÍNH CHẤT CỦA OXIDE VÀ HYDROXIDE",
    "",
    "1. Phản ứng của oxide với nước",
    "Trong một thí nghiệm, cho lần lượt các oxide Na$_2$O, MgO, P$_2$O$_5$ vào nước, nhúng giấy quỳ tím vào dung dịch sau phản ứng, hiện tượng phản ứng được trình bày trong bảng sau:",
    "",
    "| Oxide | Hiện tượng |",
    "|---|---|",
    "| Na$_2$O | Tan hoàn toàn trong nước. Quỳ tím chuyển màu xanh đậm. |",
    "| MgO | Tan một phần trong nước. Quỳ tím chuyển màu xanh nhạt. |",
    "| P$_2$O$_5$ | Tan hoàn toàn trong nước. Quỳ tím chuyển màu đỏ. |",
    "",
    "*Thực hiện các yêu cầu sau:*",
    "1. Viết phương trình hoá học của các phản ứng xảy ra trong thí nghiệm trên.",
    "2. So sánh tính acid – base của các oxide và hydroxide tương ứng.",
    "",
    "2. Phản ứng của muối với dung dịch acid",
    "*Chuẩn bị:* dung dịch Na$_2$CO$_3$; dung dịch HNO$_3$ loãng; ống nghiệm.",
    "*Tiến hành:*",
    "Thêm từng giọt dung dịch Na$_2$CO$_3$ vào ống nghiệm chứa dung dịch HNO$_3$.",
    "*Quan sát hiện tượng và thực hiện yêu cầu sau:*",
    "a) Viết phương trình hoá học của phản ứng.",
    "b) Hãy so sánh độ mạnh, yếu giữa hai acid HNO$_3$ và H$_2$CO$_3$.",
    "",
    "Các oxide, hydroxide ứng với hoá trị cao nhất của các nguyên tố chu kì 3 có tính base hoặc acid (Bảng 7.2).",
    "",
    "*Bảng 7.2. Tính acid – base của oxide và hydroxide ứng với hoá trị cao nhất của các nguyên tố chu kì 3*",
    "",
    "| Na$_2$O | MgO | Al$_2$O$_3$ | SiO$_2$ | P$_2$O$_5$ | SO$_3$ | Cl$_2$O$_7$ |",
    "|---|---|---|---|---|---|---|",
    "| basic oxide | basic oxide | oxide lưỡng tính | acidic oxide | acidic oxide | acidic oxide | acidic oxide |",
    "| NaOH | Mg(OH)$_2$ | Al(OH)$_3$ | H$_2$SiO$_3$ | H$_3$PO$_4$ | H$_2$SO$_4$ | HClO$_4$ |",
    "| base mạnh | base yếu | hydroxide lưỡng tính | acid yếu | acid trung bình | acid mạnh | acid rất mạnh |",
    "",
    "Chiều giảm tính base và tăng tính acid $\\rightarrow$",
    "",
    "Nói chung, hydroxide của các nguyên tố nhóm IA thể hiện tính base mạnh, hydroxide ứng với hoá trị cao nhất của các nguyên tố nhóm VIIA (trừ fluorine) thể hiện tính acid mạnh.",
    "",
    "41",
    "",
    "Trong một chu kì, theo chiều tăng dần của điện tích hạt nhân, tính base của oxide và hydroxide tương ứng giảm dần, đồng thời tính acid của chúng tăng dần.",
    "",
    "❓",
    "2. Trong các chất dưới đây, chất nào có tính acid yếu nhất?",
    "   A. H$_2$SO$_4$.             B. HClO$_4$.",
    "   C. H$_3$PO$_4$.             D. H$_2$SiO$_3$.",
    "3. Dãy gồm các chất có tính base tăng dần là",
    "   A. Al(OH)$_3$, Mg(OH)$_2$, NaOH.",
    "   B. NaOH, Mg(OH)$_2$, Al(OH)$_3$.",
    "   C. Mg(OH)$_2$, Al(OH)$_3$, NaOH.",
    "   D. Al(OH)$_3$, NaOH, Mg(OH)$_2$.",
    "4. Những đại lượng và tính chất nào của nguyên tố hoá học cho dưới đây không biến đổi tuần hoàn theo chiều tăng của điện tích hạt nhân nguyên tử?",
    "   A. Tính kim loại và phi kim.",
    "   B. Tính acid – base của các hydroxide.",
    "   C. Khối lượng nguyên tử.",
    "   D. Cấu hình electron lớp ngoài cùng của nguyên tử.",
    "",
    "EM ĐÃ HỌC",
    "Trong một chu kì: theo chiều tăng dần của điện tích hạt nhân, tính base của oxide và hydroxide tương ứng giảm dần, đồng thời tính acid của chúng tăng dần.",
    "",
    "EM CÓ THỂ",
    "So sánh được tính acid và base của các oxide và hydroxide dựa vào vị trí của nguyên tố tạo nên chúng trong bảng tuần hoàn các nguyên tố hoá học.",
    "",
    "42"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'BAI_8', 'ĐỊNH LUẬT TUẦN HOÀN. Ý NGHĨA CỦA BẢNG TUẦN HOÀN CÁC NGUYÊN TỐ HOÁ HỌC', 43, 8, $JSON$
{
  "content": [
    "BÀI 8 ĐỊNH LUẬT TUẦN HOÀN. Ý NGHĨA CỦA BẢNG TUẦN HOÀN CÁC NGUYÊN TỐ HOÁ HỌC",
    "",
    "MỤC TIÊU:",
    "– Phát biểu được định luật tuần hoàn.",
    "– Trình bày được ý nghĩa của bảng tuần hoàn các nguyên tố hoá học: Mối liên hệ giữa vị trí (trong bảng tuần hoàn các nguyên tố hoá học) với tính chất và ngược lại.",
    "",
    "❓",
    "Định luật tuần hoàn đóng vai trò như thế nào trong việc dự đoán tính chất của các chất?",
    "",
    "I ĐỊNH LUẬT TUẦN HOÀN",
    "Nội dung của định luật tuần hoàn: “Tính chất của các nguyên tố và đơn chất, cũng như thành phần và tính chất của các hợp chất tạo nên từ các nguyên tố đó biến đổi tuần hoàn theo chiều tăng của điện tích hạt nhân nguyên tử”.",
    "",
    "❓",
    "1. Nêu một số tính chất của các đơn chất biến đổi tuần hoàn theo chu kì để minh hoạ nội dung của định luật tuần hoàn.",
    "",
    "II Ý NGHĨA CỦA BẢNG TUẦN HOÀN",
    "• Vị trí của nguyên tố trong bảng tuần hoàn các nguyên tố hoá học cho biết cấu hình electron nguyên tử, cấu hình electron nguyên tử quyết định tính chất của các nguyên tố. Vì vậy, có thể dự đoán được tính chất hoá học của các nguyên tố khi biết vị trí của nó trong bảng tuần hoàn các nguyên tố hoá học hay cấu hình electron của nó.",
    "",
    "Cấu hình electron $\\leftrightarrow$ Vị trí của nguyên tố trong bảng tuần hoàn $\\leftrightarrow$ Tính chất của nguyên tố",
    "",
    "Ví dụ 1: Nguyên tố sulfur (S) ở ô số 16, nhóm VIA, chu kì 3.",
    "– Nguyên tử S có:",
    "  + 16 proton, 16 electron (do số proton = số electron = Z).",
    "  + 3 lớp electron (do số lớp electron bằng số thứ tự chu kì).",
    "  + 6 electron lớp ngoài cùng (do số electron lớp ngoài cùng bằng số thứ tự nhóm A).",
    "",
    "EM CÓ BIẾT",
    "Dựa trên xu hướng biến đổi tính chất của các nguyên tố hoá học khi sắp xếp theo chiều tăng dần khối lượng nguyên tử, D. I. Mendeleev đã đưa ra hai quyết định quan trọng.",
    "Thứ nhất, ông đã dành chỗ trống cho các nguyên tố khi đó chưa được tìm ra và dự đoán tính chất của chúng (ví dụ: nguyên tố gallium và germanium).",
    "Thứ hai, ông bỏ qua trật tự cứng nhắc theo chiều tăng của khối lượng nguyên tử để sắp xếp các nguyên tố theo xu hướng biến đổi tính chất (ví dụ: nguyên tố tellirium có số khối lớn hơn được xếp trước nguyên tố iodine trong bảng tuần hoàn). Các quyết định này của ông phù hợp với nguyên tắc sắp xếp các nguyên tố theo chiều tăng của điện tích hạt nhân.",
    "",
    "43",
    "",
    "– Cấu hình electron của S: 1s$^2$2s$^2$2p$^6$3s$^2$3p$^4$. S là nguyên tố phi kim. Oxide cao nhất (SO$_3$) là acidic oxide và acid tương ứng H$_2$SO$_4$ là acid mạnh.",
    "",
    "Ví dụ 2: Cấu hình electron của nguyên tử phosphorus (P) là 1s$^2$2s$^2$2p$^6$3s$^2$3p$^3$.",
    "– Nguyên tử P có Z = 15 (do số proton = số electron = Z).",
    "– Nguyên tố P ở chu kì 3, nhóm VA (do có 3 lớp electron và có 5 electron ở lớp ngoài cùng).",
    "– P là nguyên tố phi kim. Oxide cao nhất (P$_2$O$_5$) là acidic oxide và acid tương ứng là (HPO$_3$ hay H$_3$PO$_4$) là acid trung bình.",
    "",
    "• Dựa vào định luật tuần hoàn, có thể so sánh tính chất của một nguyên tố với các nguyên tố xung quanh.",
    "Ví dụ: So sánh tính phi kim của P (Z = 15) với N (Z = 7) và S (Z = 16).",
    "Nguyên tố P và N cùng nhóm nên N có tính phi kim mạnh hơn P, P và S cùng chu kì nên P có tính phi kim yếu hơn S.",
    "",
    "❓",
    "2. Nguyên tố magnesium thuộc ô số 12, chu kì 3, nhóm IIA của bảng tuần hoàn.",
    "   a) Viết cấu hình electron của magnesium, nêu một số tính chất cơ bản của đơn chất và oxide, hydroxide chứa magnesium.",
    "   b) So sánh tính kim loại của magnesium với các nguyên tố lân cận trong bảng tuần hoàn.",
    "3. Potassium (Z = 19) là nguyên tố dinh dưỡng thiết yếu cho thực vật và con người.",
    "   a) Nêu vị trí của potassium trong bảng tuần hoàn.",
    "   b) Nêu một số tính chất cơ bản của đơn chất và hợp chất chứa potassium.",
    "",
    "EM ĐÃ HỌC",
    "• Định luật tuần hoàn: Tính chất của các nguyên tố và đơn chất, cũng như thành phần và tính chất của các hợp chất tạo nên từ các nguyên tố đó biến đổi tuần hoàn theo chiều tăng của điện tích hạt nhân nguyên tử.",
    "• Ý nghĩa của bảng tuần hoàn:",
    "Cấu hình electron $\\leftrightarrow$ Vị trí của nguyên tố trong bảng tuần hoàn $\\leftrightarrow$ Tính chất của nguyên tố",
    "",
    "EM CÓ THỂ",
    "Từ vị trí của nguyên tố trong bảng tuần hoàn, có thể:",
    "• Viết được cấu hình electron của nguyên tử và ngược lại.",
    "• Dự đoán được tính chất (tính kim loại, tính phi kim) của nguyên tố đó.",
    "• Viết được công thức oxide, hydroxide và nêu tính acid, base tương ứng.",
    "",
    "44"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_2' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'BAI_9', 'ÔN TẬP CHƯƠNG 2', 45, 9, $JSON$
{
  "content": [
    "BÀI 9 ÔN TẬP CHƯƠNG 2",
    "",
    "I HỆ THỐNG HOÁ KIẾN THỨC",
    "1. Cấu tạo bảng tuần hoàn",
    "a) Điền các cụm từ “số lớp electron”; “điện tích hạt nhân” và “số electron hoá trị” vào chỗ trống thích hợp trong các mệnh đề sau theo đúng các nguyên tắc sắp xếp các nguyên tố trong bảng tuần hoàn.",
    "• ...............?............... tăng dần.",
    "• Cùng ...............?............... $\\Rightarrow$ cùng chu kì (hàng).",
    "• Cùng ...............?............... $\\Rightarrow$ cùng nhóm (cột).",
    "b) Trong bảng tuần hoàn (đến năm 2016) có bao nhiêu nguyên tố, bao nhiêu chu kì, bao nhiêu nhóm?",
    "",
    "[Sơ đồ cấu trúc bảng tuần hoàn: Hàng ngang ghi \"Chu kì\", cột dọc ghi \"Nhóm\", các ô vuông đại diện cho các nguyên tố. Ô đầu tiên ghi chữ \"ô\"]",
    "",
    "2. Xu hướng biến đổi trong bảng tuần hoàn",
    "Điền các đại lượng và tính chất dưới đây vào bên trong các mũi tên (theo chiều tăng dần) để thấy xu hướng biến đổi của các đại lượng và tính chất đó.",
    "• Bán kính nguyên tử",
    "• Giá trị độ âm điện",
    "• Tính kim loại",
    "• Tính phi kim",
    "• Tính acid – base của các oxide và hydroxide",
    "",
    "[Sơ đồ minh hoạ xu hướng biến đổi:",
    "- Hai mũi tên dọc hướng xuống dưới, bên trong có dấu hỏi chấm \"?\"",
    "- Hai mũi tên ngang hướng sang phải, bên trong có dấu hỏi chấm \"?\"",
    "- Một mũi tên ngang hướng sang trái ở phía dưới, bên trong có dấu hỏi chấm \"?\"]",
    "",
    "45",
    "",
    "3. Bảng tuần hoàn và cấu tạo nguyên tử",
    "Điền các cụm từ “số proton”; “số lớp electron”; “số Z”; “số thứ tự nhóm A”; “số electron”; “số thứ tự chu kì”; “số hiệu nguyên tử”; “số electron lớp ngoài cùng” thích hợp thay cho các số sau đây để cho thấy ý nghĩa của bảng tuần hoàn các nguyên tố hoá học.",
    "",
    ".........(1)......... = .........(2)......... = .........(3)......... = .........(4).........",
    ".........(5)......... = .........(6).........",
    ".........(7)......... = .........(8).........",
    "",
    "4. Định luật tuần hoàn",
    "Chọn từ hoặc cụm từ thích hợp để hoàn thành nội dung của định luật tuần hoàn:",
    "Tính chất của các ...?... và đơn chất cũng như thành phần và ...?... của các hợp chất tạo nên từ các nguyên tố đó biến đổi tuần hoàn theo chiều tăng của ...?... nguyên tử.",
    "",
    "II LUYỆN TẬP",
    "Câu 1. Cho vị trí của các nguyên tố E, T, Q, X, Y trong bảng tuần hoàn rút gọn (chỉ biểu diễn các nguyên tố nhóm A) như sau:",
    "",
    "| | IA | IIA | IIIA | IVA | VA | VIA | VIIA | VIIIA |",
    "|---|---|---|---|---|---|---|---|---|",
    "| | Y | E | | X | | | T | |",
    "| | | | | | | | | |",
    "| | | | | | | | Q | |",
    "| | | | | | | | | |",
    "",
    "Có các nhận xét sau:",
    "(1) Thứ tự giảm dần tính kim loại là Y, E, X.",
    "(2) Thứ tự tăng dần độ âm điện là Y, X, T.",
    "(3) Thứ tự tăng dần tính phi kim là T, Q.",
    "(4) Thứ tự giảm dần bán kính nguyên tử là Y, E, X, T.",
    "Số nhận xét đúng là",
    "A. 1.               B. 2.               C. 3.               D. 4.",
    "",
    "46",
    "",
    "Câu 2. Sulfur (S) là nguyên tố thuộc nhóm VIA, chu kì 3 của bảng tuần hoàn. Trong các phát biểu sau:",
    "(1) Nguyên tử S có 3 lớp electron và có 10 electron p.",
    "(2) Nguyên tử S có 5 electron hoá trị và 6 electron s.",
    "(3) Công thức oxide cao nhất của S có dạng SO$_3$ và là acidic oxide.",
    "(4) Nguyên tố S có tính phi kim mạnh hơn so với nguyên tố có số hiệu nguyên tử là 8.",
    "(5) Hydroxide cao nhất của S có dạng H$_2$SO$_4$ và có tính acid.",
    "Số phát biểu đúng là",
    "A. 2.               B. 3.               C. 4.               D. 5.",
    "",
    "Câu 3. X và Y là hai nguyên tố thuộc nhóm A, trong cùng một chu kì của bảng tuần hoàn. Oxide cao nhất của X và Y có dạng là XO và YO$_3$. Trong các phát biểu sau:",
    "(1) X và Y thuộc 2 nhóm A kế tiếp nhau.",
    "(2) X là kim loại, Y là phi kim.",
    "(3) XO là basic oxide và YO$_3$ là acidic oxide.",
    "(4) Hydroxide cao nhất của Y có dạng Y(OH)$_6$ và có tính base.",
    "Số phát biểu đúng là",
    "A. 2.               B. 3.               C. 4.               D. 1.",
    "",
    "Câu 4. Borax (Na$_2$B$_4$O$_7$ $\\cdot$ 10H$_2$O), còn gọi là hàn the, là khoáng chất dạng tinh thể. Nhờ có khả năng hoà tan oxide của kim loại, borax được dùng để làm sạch bề mặt kim loại trước khi hàn, chế tạo thuỷ tinh quang học, men đồ sứ,... Một lượng lớn borax được dùng để sản xuất bột giặt.",
    "a) Nêu vị trí trong bảng tuần hoàn của mỗi nguyên tố có trong thành phần của borax và viết cấu hình electron của nguyên tử các nguyên tố đó.",
    "b) Sắp xếp các nguyên tố trên (trừ H) theo chiều bán kính nguyên tử tăng dần và giải thích.",
    "c) Sắp xếp các nguyên tố trên (trừ H) theo chiều độ âm điện giảm dần và giải thích.",
    "",
    "Câu 5. Công thức cấu tạo của phân tử cafein, một chất gây đắng tìm thấy nhiều trong cafe và trà được biểu diễn ở hình bên.",
    "a) Nêu vị trí của các nguyên tố tạo nên cafein trong bảng tuần hoàn.",
    "b) So sánh tính phi kim, bán kính nguyên tử và độ âm điện của các nguyên tố đó (trừ H) và giải thích.",
    "[Hình ảnh cấu trúc phân tử cafein]",
    "",
    "Câu 6. Một loại hợp kim nhẹ, bền được sử dụng rộng rãi trong kĩ thuật hàng không chứa hai nguyên tố A, B đứng kế tiếp nhau trong cùng một chu kì của bảng tuần hoàn và có tổng số đơn vị điện tích hạt nhân là 25.",
    "a) Viết cấu hình electron, từ đó xác định vị trí của hai nguyên tố A và B trong bảng tuần hoàn.",
    "b) So sánh tính chất hoá học của A với B và giải thích.",
    "",
    "47"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'BAI_10', 'QUY TẮC OCTET', 49, 10, $JSON$
{
  "content": [
    "BÀI 10 QUY TẮC OCTET",
    "",
    "MỤC TIÊU:",
    "Trình bày và vận dụng được quy tắc octet trong quá trình hình thành liên kết hoá học cho các nguyên tố nhóm A.",
    "",
    "❓",
    "Khi các nguyên tử kết hợp với nhau tạo thành phân tử theo một tỉ lệ xác định, yếu tố nào quyết định tỉ lệ số nguyên tử của mỗi nguyên tố trong phân tử đó?",
    "",
    "I KHÁI NIỆM LIÊN KẾT HOÁ HỌC",
    "Theo thuyết cấu tạo hoá học, sự liên kết giữa các nguyên tử tạo thành phân tử hay tinh thể được giải thích bằng sự giảm năng lượng khi các nguyên tử kết hợp lại với nhau. Khi tạo liên kết hoá học thì nguyên tử có xu hướng đạt tới cấu hình electron bền vững của khí hiếm.",
    "",
    "Liên kết hoá học là sự kết hợp giữa các nguyên tử tạo thành phân tử hay tinh thể bền vững hơn.",
    "",
    "Trong các phản ứng hoá học, chỉ có các electron thuộc lớp ngoài cùng và phân lớp sát lớp ngoài cùng tham gia vào quá trình tạo thành liên kết (electron hoá trị).",
    "",
    "Các electron hoá trị của nguyên tử một nguyên tố được quy ước biểu diễn bằng các dấu chấm đặt xung quanh kí hiệu nguyên tố.",
    "",
    "*Bảng 10.1. Biểu diễn electron hoá trị của một số nguyên tử*",
    "",
    "| Nhóm | IA | IIA | IIIA | IVA | VA | VIA | VIIA | VIIIA |",
    "|---|---|---|---|---|---|---|---|---|",
    "| Số electron hoá trị | 1 | 2 | 3 | 4 | 5 | 6 | 7 | 8 |",
    "| Biểu diễn nguyên tử với electron hoá trị | H $\\cdot$ | | | | | | | He $\\mathbf{:}$ |",
    "| | Li $\\cdot$ | $\\cdot$ Be $\\cdot$ | $\\cdot$ $\\dot{\\text{B}}$ $\\cdot$ | $\\cdot$ $\\ddot{\\text{C}}$ $\\cdot$ | $\\cdot$ $\\ddot{\\text{N}}$ $\\cdot$ | $\\mathbf{:}$ $\\ddot{\\text{O}}$ $\\cdot$ | $\\mathbf{:}$ $\\ddot{\\text{F}}$ $\\mathbf{:}$ | $\\mathbf{:}$ $\\ddot{\\text{Ne}}$ $\\mathbf{:}$ |",
    "| | Na $\\cdot$ | $\\cdot$ Mg $\\cdot$ | $\\cdot$ $\\dot{\\text{Al}}$ $\\cdot$ | $\\cdot$ $\\ddot{\\text{Si}}$ $\\cdot$ | $\\cdot$ $\\ddot{\\text{P}}$ $\\cdot$ | $\\mathbf{:}$ $\\ddot{\\text{S}}$ $\\cdot$ | $\\mathbf{:}$ $\\ddot{\\text{Cl}}$ $\\mathbf{:}$ | $\\mathbf{:}$ $\\ddot{\\text{Ar}}$ $\\mathbf{:}$ |",
    "",
    "❓",
    "1. Khi nguyên tử fluorine nhận thêm 1 electron thì ion tạo thành có cấu hình electron của nguyên tử nguyên tố nào?",
    "2. Để giảm năng lượng, các nguyên tử kết hợp lại thành phân tử theo xu hướng nào?",
    "",
    "49",
    "",
    "II QUY TẮC OCTET",
    "Khi hình thành liên kết hoá học, các nguyên tử có xu hướng nhường, nhận hoặc góp chung electron để đạt tới cấu hình electron bền vững của nguyên tử khí hiếm. Vì các khí hiếm (trừ helium) đều có 8 electron lớp ngoài cùng nên quy tắc này được gọi là quy tắc octet.",
    "",
    "Khi hình thành liên kết hoá học trong phân tử Cl$_2$, nguyên tử chlorine có 7 electron hoá trị, mỗi nguyên tử chlorine cần thêm 1 electron để đạt cấu hình electron bão hoà theo quy tắc octet nên mỗi nguyên tử chlorine góp chung 1 electron.",
    "Phân tử Cl$_2$ được biểu diễn : $\\mathbf{:}$ $\\ddot{\\text{Cl}}$ $\\mathbf{:}$ $\\ddot{\\text{Cl}}$ $\\mathbf{:}$ . Xung quanh mỗi nguyên tử chlorine đều có 8 electron.",
    "Khi hình thành liên kết hoá học trong phân tử H$_2$O, nguyên tử hydrogen có 1 electron hoá trị, nguyên tử oxygen có 6 electron hoá trị, mỗi nguyên tử hydrogen cần thêm 1 electron và nguyên tử oxygen cần thêm 2 electron để đạt cấu hình electron bão hoà theo quy tắc octet.",
    "Phân tử H$_2$O được biểu diễn H $\\mathbf{:}$ $\\ddot{\\text{O}}$ $\\mathbf{:}$ H. Xung quanh nguyên tử oxygen có 8 electron.",
    "Khi hình thành liên kết hoá học trong phân tử NaF, nguyên tử Na có 1 electron hoá trị, nguyên tử F có 7 electron hoá trị, nguyên tử Na nhường 1 electron hoá trị tạo thành hạt mang điện tích dương, nguyên tử F nhận 1 electron tạo thành hạt mang điện tích âm. Các hạt này đều đạt cấu hình electron bão hoà theo quy tắc octet và có điện tích trái dấu nên hút nhau.",
    "",
    "EM CÓ BIẾT",
    "Quy tắc octet chỉ đúng cho sự tạo thành liên kết hoá học giữa các nguyên tử của các nguyên tố thuộc chu kì 2 của bảng tuần hoàn và một số nguyên tử của các nguyên tố có tính kim loại, phi kim điển hình. Ngoài ra có các ngoại lệ.",
    "Ví dụ: Trong phân tử PCl$_5$, lớp ngoài cùng của P có 10 electron.",
    "[Hình ảnh biểu diễn PCl5 với các chấm electron]",
    "",
    "❓",
    "3. Vận dụng quy tắc octet để giải thích sự hình thành liên kết trong các phân tử: F$_2$, CCl$_4$ và NF$_3$.",
    "4. Phosphine là hợp chất hoá học giữa phosphorus với hydrogen, có công thức hoá học là PH$_3$. Đây là chất khí không màu, có mùi tỏi, rất độc, không bền. Phosphine sinh ra khi phân huỷ xác động, thực vật và thường lẫn một lượng nhỏ diphosphine (P$_2$H$_4$) nên nó có thể tự cháy trong không khí ở điều kiện thường và tạo thành khối phát sáng bay lơ lửng (hiện tượng “ma trơi”).",
    "Vận dụng quy tắc octet để giải thích sự tạo thành liên kết hoá học trong phosphine.",
    "",
    "EM ĐÃ HỌC",
    "• Liên kết hoá học là sự kết hợp giữa các nguyên tử tạo thành phân tử hay tinh thể bền vững hơn.",
    "• Quy tắc octet: Khi hình thành liên kết hoá học, các nguyên tử có xu hướng nhường, nhận hoặc góp chung electron để đạt tới cấu hình electron bền vững của nguyên tử khí hiếm.",
    "",
    "EM CÓ THỂ",
    "Vận dụng quy tắc octet để giải thích sự hình thành liên kết hoá học trong một số phân tử của các nguyên tố từ nguyên tố nhóm A.",
    "",
    "50"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'BAI_11', 'LIÊN KẾT ION', 51, 11, $JSON$
{
  "content": [
    "BÀI 11 LIÊN KẾT ION",
    "",
    "MỤC TIÊU:",
    "– Trình bày được khái niệm và sự hình thành liên kết ion (nêu một số ví dụ điển hình tuân theo quy tắc octet).",
    "– Nêu được cấu tạo tinh thể NaCl. Giải thích được vì sao các hợp chất ion thường ở trạng thái rắn trong điều kiện thường (dạng tinh thể ion).",
    "– Lắp được mô hình tinh thể NaCl (theo mô hình có sẵn).",
    "",
    "❓",
    "Hợp chất NaCl nóng chảy ở nhiệt độ cao và có khả năng dẫn điện khi nóng chảy hoặc khi hoà tan trong dung dịch. Yếu tố nào trong phân tử NaCl gây ra các tính chất trên?",
    "",
    "I SỰ TẠO THÀNH ION",
    "Kim loại điển hình (ví dụ: sodium) phản ứng rất mạnh với phi kim điển hình (ví dụ: chlorine) tạo ra hợp chất ion. Khi đó, nguyên tử kim loại nhường electron để tạo thành ion mang điện tích dương (cation) còn nguyên tử phi kim nhận electron để trở thành ion mang điện tích âm (anion). Có thể mô tả quá trình tạo thành ion như sau:",
    "",
    "Na $\\xrightarrow{\\text{nhường e}}$ Na$^+$",
    "1s$^2$2s$^2$2p$^6$3s$^1$ $\\rightarrow$ 1s$^2$2s$^2$2p$^6$",
    "Nguyên tử sodium $\\rightarrow$ Cation sodium",
    "Sự tạo thành ion dương (cation)",
    "",
    "Cl $\\xrightarrow{\\text{nhận e}}$ Cl$^-$",
    "1s$^2$2s$^2$2p$^6$3s$^2$3p$^5$ $\\rightarrow$ 1s$^2$2s$^2$2p$^6$3s$^2$3p$^6$",
    "Nguyên tử chlorine $\\rightarrow$ Anion chloride",
    "Sự tạo thành ion âm (anion)",
    "",
    "Số đơn vị điện tích của ion dương (cation) bằng số electron mà nguyên tử đã nhường.",
    "Ví dụ: ",
    "Na $\\longrightarrow$ Na$^+$ + 1e",
    "Tên gọi: cation sodium",
    "",
    "Mg $\\longrightarrow$ Mg$^{2+}$ + 2e",
    "cation magnesium",
    "",
    "Al $\\longrightarrow$ Al$^{3+}$ + 3e",
    "cation aluminium",
    "",
    "Số đơn vị điện tích của ion âm (anion) bằng số electron mà nguyên tử đã nhận.",
    "Ví dụ: ",
    "Cl + 1e $\\longrightarrow$ Cl$^-$",
    "Tên gọi: anion chloride",
    "",
    "F + 1e $\\longrightarrow$ F$^-$",
    "anion fluoride",
    "",
    "S + 2e $\\longrightarrow$ S$^{2-}$",
    "anion sulfide",
    "",
    "Các ion thường có cấu hình electron bền vững của nguyên tử khí hiếm gần nhất với nguyên tố tạo thành ion đó trong bảng tuần hoàn.",
    "",
    "EM CÓ BIẾT",
    "Ngoài các ion được tạo thành từ một nguyên tử (ion đơn nguyên tử) như Na$^+$, Mg$^{2+}$, Cl$^-$,... còn có các ion tạo thành từ hai hay nhiều nguyên tử (ion đa nguyên tử), ví dụ: NH$_4^+$, OH$^-$, NO$_3^-$, HCO$_3^-$, SO$_4^{2-}$, PO$_4^{3-}$,...",
    "",
    "51",
    "",
    "❓",
    "1. Hoàn thành các sơ đồ tạo thành ion sau:",
    "a) Li $\\rightarrow$ Li$^+$ + ?    b) Be $\\rightarrow$ ? + 2e    c) Br + ? $\\rightarrow$ Br$^-$    d) O + 2e $\\rightarrow$ ?",
    "2. Viết cấu hình electron của các ion: K$^+$, Mg$^{2+}$, F$^-$, S$^{2-}$. Mỗi cấu hình đó giống với cấu hình electron của nguyên tử khí hiếm nào?",
    "3. Vì sao một ion O$^{2-}$ kết hợp được với hai ion Li$^+$?",
    "",
    "II SỰ TẠO THÀNH LIÊN KẾT ION",
    "• Sodium chloride: Khi kim loại sodium kết hợp với phi kim chlorine, tạo thành các ion Na$^+$ và Cl$^-$, các ion này mang điện trái dấu sẽ hút nhau tạo thành liên kết ion.",
    "Có thể biểu diễn sự tạo thành liên kết ion trong phân tử NaCl như sau:",
    "Na + Cl $\\longrightarrow$ Na$^+$ + Cl$^-$",
    "1s$^2$2s$^2$2p$^6$3s$^1$   1s$^2$2s$^2$2p$^6$3s$^2$3p$^5$   1s$^2$2s$^2$2p$^6$   1s$^2$2s$^2$2p$^6$3s$^2$3p$^6$",
    "Hoặc",
    "Na $\\cdot$ + $\\mathbf{:}$ $\\ddot{\\text{Cl}}$ $\\cdot$ $\\longrightarrow$ Na$^+$ + Cl$^-$ $\\longrightarrow$ NaCl",
    "• Calcium chloride: Khi kim loại calcium kết hợp với phi kim chlorine, tạo thành các ion Ca$^{2+}$ và Cl$^-$. Các ion này mang điện trái dấu sẽ hút nhau tạo thành liên kết ion.",
    "Có thể biểu diễn sự tạo thành liên kết ion trong phân tử CaCl$_2$ như sau:",
    "$\\mathbf{:}$ $\\ddot{\\text{Cl}}$ $\\cdot$ + $\\cdot$ Ca $\\cdot$ + $\\cdot$ $\\ddot{\\text{Cl}}$ $\\mathbf{:}$ $\\longrightarrow$ Cl$^-$ + Ca$^{2+}$ + Cl$^-$ $\\longrightarrow$ CaCl$_2$",
    "",
    "Lực hút tĩnh điện giữa các ion mang điện trái dấu trong phân tử (hay tinh thể) tạo ra liên kết ion. Liên kết ion thường được hình thành giữa kim loại điển hình và phi kim điển hình. Các hợp chất tạo nên từ các ion được gọi là những hợp chất ion.",
    "",
    "❓",
    "4. Cho các ion: Na$^+$, Mg$^{2+}$, O$^{2-}$, Cl$^-$. Những ion nào có thể kết hợp với nhau tạo thành liên kết ion?",
    "5. Mô tả sự tạo thành liên kết ion trong:",
    "a) Calcium oxide.",
    "b) Magnesium chloride.",
    "",
    "52",
    "",
    "III TINH THỂ ION",
    "1. Cấu trúc của tinh thể ion",
    "Các ion được sắp xếp theo một trật tự nhất định trong không gian theo kiểu mạng lưới, trong đó ở các nút của mạng lưới là những ion dương và ion âm được sắp xếp luân phiên, liên kết chặt chẽ với nhau do sự cân bằng giữa lực hút (các ion trái dấu hút nhau) và lực đẩy (các ion cùng dấu đẩy nhau), tạo thành mạng tinh thể ion.",
    "Ví dụ: xét tinh thể muối ăn.",
    "[Hình ảnh mô hình đặc và rỗng của mạng tinh thể NaCl]",
    "Hình 11.1. Sự sắp xếp của các ion trong tinh thể sodium chloride:",
    "a) Mô hình đặc b) Mô hình rỗng",
    "Trong tinh thể sodium chloride, mỗi ion sodium được bao quanh bởi 6 ion chloride gần nhất và mỗi ion chloride cũng được bao quanh bởi 6 ion sodium gần nhất.",
    "Trong tinh thể ion, số ion cùng dấu bao quanh một ion trái dấu phụ thuộc vào kiểu mạng lưới tinh thể, số điện tích và kích thước của ion.",
    "Do lực hút giữa các cation và anion không có tính bão hoà và tính định hướng nên chúng có xu hướng hút lẫn nhau, tạo ra mạng lưới các ion trong không gian ba chiều.",
    "",
    "Lắp ráp mô hình tinh thể NaCl",
    "Chuẩn bị: bộ mô hình tinh thể NaCl.",
    "Tiến hành:",
    "– Chọn hình cầu có màu sắc khác nhau đại diện cho ion Na$^+$ và ion Cl$^-$.",
    "– Lắp các hình cầu và que nối theo mẫu (Hình 11.1b).",
    "Quan sát mô hình và xác định số ion gần nhất bao quanh một ion trái dấu ở giữa mô hình.",
    "",
    "2. Độ bền và tính chất của hợp chất ion",
    "Trong tinh thể ion, giữa các ion có lực hút tĩnh điện rất mạnh nên các hợp chất ion thường là chất rắn, khó nóng chảy, khó bay hơi ở điều kiện thường. Ví dụ: Nhiệt độ nóng chảy của MgO là 2852 $^\\circ$C.",
    "Do lực hút tĩnh điện rất mạnh giữa các ion nên các tinh thể ion khá rắn chắc, nhưng khá giòn. Đây là tính chất đặc trưng của tinh thể ion.",
    "Ví dụ: Tinh thể muối ăn ở dạng rắn, cứng, nhưng khi tác dụng một lực mạnh thì bị vỡ vụn.",
    "",
    "53",
    "",
    "Các hợp chất ion thường tan nhiều trong nước. Khi tan trong nước, các ion bị tách khỏi mạng lưới tinh thể, chuyển động khá tự do và là tác nhân dẫn điện.",
    "Ở trạng thái rắn, các ion không di chuyển tự do được nên hợp chất ion không dẫn điện. Tuy nhiên, ở trạng thái nóng chảy, các ion có thể chuyển động khá tự do nên hợp chất ion dẫn điện.",
    "[Hình ảnh pin alkaline]",
    "Hình 11.2. Potassium hydroxide là hợp chất ion được dùng làm chất dẫn điện trong pin alkaline (pin kiềm)",
    "",
    "Thử tính dẫn điện của hợp chất",
    "Chuẩn bị: muối ăn dạng hạt, dung dịch muối ăn bão hoà, dung dịch nước đường, dụng cụ thử tính dẫn điện, cốc thuỷ tinh.",
    "Tiến hành: Sử dụng dụng cụ thử tính dẫn điện như Hình 11.3, lần lượt cho chân kim loại của dụng cụ thử tính dẫn điện tiếp xúc với:",
    "– Dung dịch nước đường.",
    "– Muối ăn khan.",
    "– Dung dịch muối ăn bão hoà.",
    "Nếu đèn sáng thì chất dẫn điện, nếu đèn không sáng thì chất không dẫn điện.",
    "Quan sát hiện tượng và cho biết trường hợp nào dẫn điện, trường hợp nào không dẫn điện. Giải thích.",
    "[Hình ảnh dụng cụ thử tính dẫn điện]",
    "Hình 11.3. Dụng cụ thử tính dẫn điện",
    "",
    "❓",
    "6. a) Vì sao muối ăn có nhiệt độ nóng chảy cao (801 $^\\circ$C)?",
    "b) Hợp chất ion dẫn điện trong trường hợp nào? Vì sao?",
    "",
    "EM ĐÃ HỌC",
    "• Nguyên tử nhường electron tạo thành cation hoặc nhận electron tạo thành anion.",
    "• Liên kết ion trong phân tử hay tinh thể được tạo thành nhờ lực hút tĩnh điện của các ion mang điện tích trái dấu. Liên kết ion thường tạo thành từ các nguyên tử kim loại điển hình và phi kim điển hình, phân tử thu được là hợp chất ion.",
    "• Cấu trúc của mạng tinh thể ion: các ion được sắp xếp theo trật tự nhất định trong không gian theo kiểu mạng lưới (ở các nút mạng là các ion dương và ion âm xếp luân phiên liên kết chặt chẽ với nhau do cân bằng lực hút và lực đẩy).",
    "• Các hợp chất ion thường là chất rắn có nhiệt độ nóng chảy và nhiệt độ sôi cao, có khả năng dẫn điện khi tan trong nước hay khi nóng chảy.",
    "",
    "EM CÓ THỂ",
    "Giải thích được một số tính chất đặc trưng của hợp chất ion và một số ứng dụng phổ biến của chúng trong đời sống.",
    "",
    "54"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'BAI_12', 'LIÊN KẾT CỘNG HOÁ TRỊ', 55, 12, $JSON$
{
  "content": [
    "BÀI 12 LIÊN KẾT CỘNG HOÁ TRỊ",
    "",
    "MỤC TIÊU:",
    "– Trình bày được khái niệm và lấy được ví dụ về liên kết cộng hoá trị (liên kết đơn, đôi, ba) khi áp dụng quy tắc octet.",
    "– Viết được công thức Lewis của một số chất đơn giản.",
    "– Trình bày được khái niệm về liên kết cho – nhận.",
    "– Phân biệt được các loại liên kết (liên kết cộng hoá trị không phân cực, phân cực, liên kết ion) dựa theo độ âm điện.",
    "– Giải thích được sự hình thành liên kết $\\sigma$ và liên kết $\\pi$ qua sự xen phủ AO.",
    "– Trình bày được khái niệm năng lượng liên kết (cộng hoá trị).",
    "– Lắp ráp được mô hình một số phân tử có liên kết cộng hoá trị.",
    "",
    "❓",
    "Nguyên tử hydrogen và chlorine dễ dàng kết hợp để tạo thành phân tử hydrogen chloride (HCl), liên kết trong trường hợp này có gì khác so với liên kết ion trong phân tử sodium chloride (NaCl)?",
    "",
    "I SỰ TẠO THÀNH LIÊN KẾT CỘNG HOÁ TRỊ",
    "Nguyên tử phi kim có lớp electron hoá trị gần bão hoà và có xu hướng nhận thêm electron để đạt cấu hình electron bền vững của nguyên tử khí hiếm. Khi hai nguyên tử phi kim kết hợp với nhau tạo thành phân tử, chúng sẽ góp một hoặc nhiều electron để tạo thành các cặp electron dùng chung. Các cặp electron dùng chung được tính cho cả hai nguyên tử trong phân tử nên mỗi nguyên tử đều đạt được cấu hình bền vững theo quy tắc octet. Cặp electron dùng chung tạo ra liên kết cộng hoá trị giữa hai nguyên tử.",
    "Cặp electron dùng chung giữa hai nguyên tử có thể được tạo thành theo hai kiểu khác nhau:",
    "– Mỗi nguyên tử góp một hay nhiều electron để tạo thành các cặp electron dùng chung:",
    "Ví dụ: A $\\cdot$ + $\\cdot$ B $\\rightarrow$ A $\\mathbf{:}$ B hoặc A – B (liên kết A – B là liên kết cộng hoá trị).",
    "– Cặp electron dùng chung chỉ do một nguyên tử đóng góp, liên kết giữa hai nguyên tử là liên kết cộng hoá trị kiểu cho – nhận.",
    "Ví dụ: Khi cặp electron dùng chung chỉ do nguyên tử B đóng góp, nguyên tử B là nguyên tử cho electron, nguyên tử A là nguyên tử nhận electron. Kí hiệu B $\\rightarrow$ A.",
    "",
    "1. Sự tạo thành phân tử có liên kết đơn",
    "• Phân tử chlorine: Mỗi nguyên tử chlorine có 7 electron hoá trị, hai nguyên tử chlorine liên kết với nhau bằng cách mỗi nguyên tử chlorine góp 1 electron, tạo thành một cặp electron dùng chung. Khi đó, trong phân tử Cl$_2$, mỗi nguyên tử đều có 8 electron ở lớp ngoài cùng, thoả mãn quy tắc octet:",
    "",
    "55",
    "",
    "[Hình ảnh sơ đồ tạo thành phân tử Cl2]",
    "cặp electron dùng chung",
    "Cl + Cl $\\longrightarrow$ Cl $\\mathbf{:}$ Cl",
    "Hai nguyên tử Cl (2, 8, 7) $\\longrightarrow$ Phân tử Cl$_2$",
    "Cấu hình electron của mỗi nguyên tử: (2, 8, 8)",
    "Hình 12.1. Sơ đồ mô tả sự dùng chung cặp electron giữa hai nguyên tử chlorine, tạo thành phân tử chlorine",
    "",
    "Từ công thức electron, thay một cặp electron dùng chung bằng một gạch nối thì thu được công thức Lewis (Li-uýt).",
    "Có thể biểu diễn bằng sơ đồ:",
    "$\\mathbf{:}$ $\\ddot{\\text{Cl}}$ $\\cdot$ + $\\cdot$ $\\ddot{\\text{Cl}}$ $\\mathbf{:}$ $\\longrightarrow$ $\\mathbf{:}$ $\\ddot{\\text{Cl}}$ $\\mathbf{:}$ $\\ddot{\\text{Cl}}$ $\\mathbf{:}$ ; $\\mathbf{:}$ $\\ddot{\\text{Cl}}$ $-$ $\\ddot{\\text{Cl}}$ $\\mathbf{:}$ ; Cl $-$ Cl",
    "Công thức electron Công thức Lewis Công thức cấu tạo",
    "Hình 12.2. Sơ đồ sự tạo thành phân tử chlorine",
    "Giữa hai nguyên tử chlorine có một cặp electron dùng chung (biểu diễn bằng một gạch nối), đó là liên kết đơn.",
    "",
    "• Phân tử hydrogen chloride: Nguyên tử hydrogen liên kết với nguyên tử chlorine bằng cách mỗi nguyên tử góp 1 electron tạo thành 1 cặp electron dùng chung trong phân tử HCl. Khi đó nguyên tử hydrogen có 2 electron (cấu hình electron bền vững của nguyên tử khí hiếm He) và nguyên tử chlorine có 8 electron ở lớp ngoài cùng, thoả mãn quy tắc octet.",
    "H $\\cdot$ + $\\cdot$ $\\ddot{\\text{Cl}}$ $\\mathbf{:}$ $\\longrightarrow$ H $\\mathbf{:}$ $\\ddot{\\text{Cl}}$ $\\mathbf{:}$ ; H $-$ $\\ddot{\\text{Cl}}$ $\\mathbf{:}$ ; H $-$ Cl",
    "Công thức electron Công thức Lewis Công thức cấu tạo",
    "Hình 12.3. Sơ đồ sự tạo thành phân tử hydrogen chloride",
    "Giữa hai nguyên tử hydrogen và chlorine có một cặp electron dùng chung (biểu diễn bằng một gạch nối), đó là liên kết đơn.",
    "",
    "• Phân tử hợp chất có liên kết cho – nhận:",
    "Trong phân tử NH$_3$, lớp ngoài cùng của nguyên tử nitrogen có 5 electron, trong đó có cặp electron chưa liên kết. Ion H$^+$ có orbital trống, không có electron. Khi phân tử NH$_3$ kết hợp với ion H$^+$, nguyên tử nitrogen đóng góp cặp electron chưa liên kết để tạo liên kết với ion H$^+$ tạo thành NH$_4^+$. Khi đó, liên kết cho – nhận được hình thành, nguyên tử nitrogen là nguyên tử cho, ion H$^+$ là nguyên tử nhận. Trong ion NH$_4^+$, bốn liên kết N–H hoàn toàn tương đương nhau.",
    "[Hình ảnh sơ đồ tạo thành ion NH4+]",
    "H",
    "H $\\mathbf{:}$ $\\ddot{\\text{N}}$ $\\mathbf{:}$ + H$^+$ $\\longrightarrow$ $\\left[ \\begin{array}{c} \\text{H} \\\\ \\text{H} \\mathbf{:} \\ddot{\\text{N}} \\mathbf{:} \\text{H} \\\\ \\text{H} \\end{array} \\right]^+$ ; $\\left[ \\begin{array}{c} \\text{H} \\\\ | \\\\ \\text{H} - \\text{N} \\rightarrow \\text{H} \\\\ | \\\\ \\text{H} \\end{array} \\right]^+$",
