    "56",
    "",
    "2. Sự tạo thành phân tử có liên kết đôi",
    "• Phân tử oxygen: Mỗi nguyên tử oxygen có 6 electron hoá trị, hai nguyên tử oxygen liên kết với nhau bằng cách mỗi nguyên tử đóng góp 2 electron, tạo thành 2 cặp electron dùng chung. Trong phân tử O$_2$, mỗi nguyên tử oxygen đều có 8 electron ở lớp ngoài cùng, thoả mãn quy tắc octet.",
    "$\\mathbf{:}$ $\\ddot{\\text{O}}$ $\\cdot$ + $\\cdot$ $\\ddot{\\text{O}}$ $\\mathbf{:}$ $\\longrightarrow$ $\\mathbf{:}$ $\\ddot{\\text{O}}$ $\\mathbf{::}$ $\\ddot{\\text{O}}$ $\\mathbf{:}$ ; $\\mathbf{:}$ $\\ddot{\\text{O}}$ $=$ $\\ddot{\\text{O}}$ $\\mathbf{:}$ ; O $=$ O",
    "Công thức electron Công thức Lewis Công thức cấu tạo",
    "Hình 12.5. Sơ đồ sự tạo thành phân tử oxygen",
    "Giữa hai nguyên tử oxygen có hai cặp electron dùng chung (biểu diễn bằng hai gạch nối), đó là liên kết đôi.",
    "",
    "• Phân tử carbon dioxide: Nguyên tử carbon có 4 electron hoá trị, nguyên tử oxygen có 6 electron hoá trị. Hai nguyên tử oxygen liên kết với một nguyên tử carbon bằng cách mỗi nguyên tử oxygen đóng góp 2 electron và nguyên tử carbon đóng góp 4 electron tạo thành bốn cặp electron dùng chung. Khi đó, trong phân tử CO$_2$, mỗi nguyên tử đều có 8 electron ở lớp ngoài cùng, thoả mãn quy tắc octet.",
    "$\\mathbf{:}$ $\\ddot{\\text{O}}$ $\\cdot$ + $\\cdot$ $\\ddot{\\text{C}}$ $\\cdot$ + $\\cdot$ $\\ddot{\\text{O}}$ $\\mathbf{:}$ $\\longrightarrow$ $\\mathbf{:}$ $\\ddot{\\text{O}}$ $\\mathbf{::}$ C $\\mathbf{::}$ $\\ddot{\\text{O}}$ $\\mathbf{:}$ ; $\\mathbf{:}$ $\\ddot{\\text{O}}$ $=$ C $=$ $\\ddot{\\text{O}}$ $\\mathbf{:}$ ; O $=$ C $=$ O",
    "Công thức electron Công thức Lewis Công thức cấu tạo",
    "Hình 12.6. Sơ đồ sự tạo thành phân tử carbon dioxide",
    "Giữa nguyên tử C và nguyên tử O có 2 cặp electron dùng chung (biểu diễn bằng hai gạch nối), đó là liên kết đôi. Phân tử CO$_2$ có hai liên kết đôi.",
    "",
    "3. Sự tạo thành phân tử có liên kết ba",
    "Phân tử nitrogen: Nguyên tử nitrogen có 5 electron hoá trị, hai nguyên tử nitrogen liên kết với nhau bằng cách mỗi nguyên tử nitrogen đóng góp 3 electron, tạo thành ba cặp electron dùng chung. Khi đó, trong phân tử N$_2$, mỗi nguyên tử đều có 8 electron ở lớp ngoài cùng, thoả mãn quy tắc octet.",
    "$\\mathbf{:}$ $\\dot{\\text{N}}$ $\\cdot$ + $\\cdot$ $\\dot{\\text{N}}$ $\\mathbf{:}$ $\\longrightarrow$ $\\mathbf{:}$ N $\\mathbf{:::}$ N $\\mathbf{:}$ ; $\\mathbf{:}$ N $\\equiv$ N $\\mathbf{:}$ ; N $\\equiv$ N",
    "Công thức electron Công thức Lewis Công thức cấu tạo",
    "Hình 12.7. Sơ đồ sự tạo thành phân tử nitrogen",
    "Giữa hai nguyên tử nitrogen có ba cặp electron dùng chung (biểu diễn bằng ba gạch nối), đó là liên kết ba.",
    "Liên kết tạo thành trong các phân tử Cl$_2$, HCl, O$_2$, CO$_2$, N$_2$,... là liên kết cộng hoá trị.",
    "Liên kết cộng hoá trị là liên kết được tạo thành giữa hai nguyên tử bằng một hay nhiều cặp electron dùng chung.",
    "Liên kết trong các phân tử Cl$_2$, O$_2$, N$_2$,... có cặp electron dùng chung không bị hút lệch về phía nguyên tử nào được gọi là liên kết cộng hoá trị không phân cực. Liên kết trong phân tử HCl có cặp electron dùng chung lệch về phía nguyên tử có độ âm điện lớn hơn (Cl) được gọi là liên kết cộng hoá trị phân cực.",
    "",
    "57",
    "",
    "Lắp ráp mô hình một số phân tử",
    "Chuẩn bị: Bộ lắp ráp mô hình các phân tử CH$_4$, C$_2$H$_4$, C$_2$H$_2$, C$_2$H$_5$OH, CH$_3$COOH.",
    "Tiến hành:",
    "– Chọn hình cầu có màu sắc khác nhau đại diện cho nguyên tử C, O, H.",
    "– Lắp các hình cầu và que nối theo mẫu (Hình 12.8).",
    "",
    "[Hình ảnh mô hình phân tử Methane (CH4), Ethene (C2H4)]",
    "Methane (CH$_4$) Ethene (C$_2$H$_4$)",
    "[Hình ảnh mô hình phân tử Ethyne (C2H2)]",
    "Ethyne (C$_2$H$_2$)",
    "[Hình ảnh mô hình phân tử Ethanol (C2H5OH), Ethanoic acid (CH3COOH)]",
    "Ethanol (C$_2$H$_5$OH) Ethanoic acid (CH$_3$COOH)",
    "Hình 12.8. Mô hình một số phân tử có liên kết cộng hoá trị",
    "Quan sát mô hình và cho biết số liên kết đơn, liên kết đôi, liên kết ba trong mỗi phân tử.",
    "",
    "❓",
    "1. Viết công thức electron, công thức cấu tạo và công thức Lewis của các phân tử:",
    "a) Bromine (Br$_2$). b) Hydrogen sulfide (H$_2$S).",
    "c) Methane (CH$_4$). d) Ammonia (NH$_3$).",
    "e) Ethene (C$_2$H$_4$). g) Ethyne (C$_2$H$_2$).",
    "",
    "58",
    "",
    "II ĐỘ ÂM ĐIỆN VÀ LIÊN KẾT HOÁ HỌC",
    "Độ âm điện đặc trưng cho khả năng hút electron của nguyên tử khi hình thành liên kết hoá học. Dựa vào sự khác nhau về độ âm điện giữa các nguyên tử tham gia liên kết, có thể dự đoán được loại liên kết giữa hai nguyên tử đó$^*$ (Bảng 12.1):",
    "Bảng 12.1. Mối quan hệ giữa hiệu độ âm điện với liên kết hoá học",
    "",
    "| Trạng thái của cặp electron liên kết | Hiệu độ âm điện ($\\Delta\\chi$) | Đặc điểm liên kết | Loại liên kết |",
    "|---|---|---|---|",
    "| Cặp electron liên kết không bị hút lệch về phía nguyên tử nào. | $0 \\le |\\Delta\\chi| < 0,4$ | Liên kết không bị phân cực | Cộng hoá trị không phân cực |",
    "| Cặp electron liên kết bị hút lệch về phía nguyên tử có độ âm điện lớn hơn. | $0,4 \\le |\\Delta\\chi| < 1,7$ | Liên kết bị phân cực | Cộng hoá trị phân cực |",
    "| Cặp electron liên kết chuyển hẳn đến nguyên tử nhận electron tạo thành ion âm và nguyên tử nhường electron tạo thành ion dương. | $|\\Delta\\chi| \\ge 1,7$ | Liên kết bị phân cực mạnh | Ion |",
    "",
    "Ví dụ:",
    "– Trong phân tử HCl, hiệu độ âm điện của Cl và H: 3,16 – 2,20 = 0,96. Vì vậy, liên kết giữa H và Cl là liên kết cộng hoá trị phân cực.",
    "– Trong phân tử CO$_2$, hiệu độ âm điện của O và C: 3,44 – 2,55 = 0,89. Vì vậy, liên kết giữa C và O là liên kết cộng hoá trị phân cực. Tuy nhiên, do phân tử CO$_2$ có cấu tạo thẳng nên độ phân cực của hai liên kết đôi (C=O) triệt tiêu nhau, dẫn đến toàn bộ phân tử không bị phân cực.",
    "– Trong phân tử NaCl, hiệu độ âm điện của Cl và Na: 3,16 – 0,93 = 2,23. Vì vậy, liên kết giữa Na và Cl là liên kết ion.",
    "Liên kết cộng hoá trị phân cực có thể được coi là dạng trung gian giữa liên kết cộng hoá trị không phân cực và liên kết ion.",
    "",
    "❓",
    "2. Dựa vào giá trị độ âm điện trong Bảng 6.2, dự đoán loại liên kết (liên kết cộng hoá trị phân cực, liên kết cộng hoá trị không phân cực, liên kết ion) trong các phân tử: MgCl$_2$, AlCl$_3$, HBr, O$_2$, H$_2$, NH$_3$.",
    "",
    "$^*$ Trừ một số trường hợp ngoại lệ như: HF, MnI$_2$,...",
    "",
    "59",
    "",
    "EM CÓ BIẾT",
    "Tính chất của các chất có liên kết cộng hoá trị",
    "Tương tác giữa các phân tử có liên kết cộng hoá trị yếu hơn nhiều so với các phân tử có liên kết ion.",
    "Trạng thái: Các chất có liên kết cộng hoá trị có thể tồn tại ở các trạng thái rắn, lỏng và khí.",
    "– Khí: hydrogen, fluorine, carbon dioxide, chlorine,...",
    "– Lỏng: bromine, nước, alcohol,...",
    "– Rắn: sulfur, iodine, đường glucose, sucrose,...",
    "Tính tan: Nói chung, các chất có liên kết cộng hoá trị phân cực như ethanol, đường,... tan nhiều trong nước,... Các chất có liên kết cộng hoá trị không phân cực như iodine, hydrocarbon ít tan trong nước, tan trong benzene, carbon tetrachloride,...",
    "Nhiệt độ nóng chảy: Hợp chất cộng hoá trị không có lực hút tĩnh điện mạnh như hợp chất ion nên chúng có nhiệt độ nóng chảy và nhiệt độ sôi thấp.",
    "Khả năng dẫn điện: Nói chung, các chất có liên kết cộng hoá trị không phân cực không dẫn điện ở mọi trạng thái.",
    "",
    "III MÔ TẢ LIÊN KẾT CỘNG HOÁ TRỊ BẰNG SỰ XEN PHỦ CÁC ORBITAL NGUYÊN TỬ",
    "1. Sự xen phủ các orbital nguyên tử tạo liên kết $\\sigma$ (sigma)",
    "• Sự xen phủ s – s",
    "Phân tử H$_2$ tạo thành từ 2 nguyên tử H (1s$^1$). Khi 2 nguyên tử H tiến lại gần nhau, hạt nhân của nguyên tử này hút đám mây electron của nguyên tử kia, hai orbital nguyên tử xen phủ vào nhau một phần. Vùng xen phủ có mật độ điện tích âm lớn, làm tăng lực hút của mỗi hạt nhân với vùng này và làm cân bằng lực đẩy giữa hai hạt nhân, để hai nguyên tử liên kết với nhau.",
    "[Hình ảnh sơ đồ xen phủ orbital s và s]",
    "AO s + AO s $\\longrightarrow$ Xen phủ s – s (Vùng xen phủ)",
    "Hình 12.9. Sơ đồ xen phủ orbital s và s, tạo liên kết $\\sigma$",
    "Trong phân tử H$_2$, khoảng cách giữa tâm của hai hạt nhân nguyên tử H (độ dài liên kết H—H) là 74 pm, ngắn hơn tổng bán kính của hai nguyên tử H (106 pm). Phân tử H$_2$ bền hơn và có năng lượng thấp hơn tổng năng lượng của hai nguyên tử H riêng rẽ.",
    "",
    "• Sự xen phủ s – p",
    "Phân tử HF tạo thành khi orbital 1s của nguyên tử H (1s$^1$) xen phủ với orbital 2p của nguyên tử F (2s$^2$2p$^5$) theo trục liên kết, tạo liên kết cộng hoá trị giữa H và F, vùng xen phủ càng lớn thì liên kết càng bền.",
    "[Hình ảnh sơ đồ xen phủ orbital s và p]",
    "AO s + AO p $\\longrightarrow$ Xen phủ s – p",
    "Hình 12.10. Sơ đồ xen phủ orbital s và p, tạo liên kết $\\sigma$",
    "",
    "60",
    "",
    "• Sự xen phủ p – p.",
    "Phân tử Cl$_2$ tạo thành khi hai orbital 3p của hai nguyên tử Cl (3s$^2$3p$^5$) xen phủ theo trục liên kết của hai nguyên tử Cl.",
    "[Hình ảnh sơ đồ xen phủ orbital p và p]",
    "AO p + AO p $\\longrightarrow$ Xen phủ p – p",
    "Hình 12.11. Sơ đồ xen phủ orbital p và p, tạo liên kết $\\sigma$",
    "Trong các trường hợp xen phủ trên, để vùng xen phủ cực đại, các orbital sẽ xen phủ với nhau theo trục liên kết. Sự xen phủ như thế gọi là xen phủ trục, tạo ra liên kết $\\sigma$. Các liên kết cộng hoá trị đơn đều là liên kết $\\sigma$. Trong liên kết $\\sigma$, mật độ xác suất tìm thấy electron lớn nhất dọc theo trục liên kết.",
    "",
    "2. Sự xen phủ các orbital nguyên tử tạo liên kết $\\pi$ (pi)",
    "Sự xen phủ, trong đó trục của các orbital tham gia liên kết song song với nhau và vuông góc với đường nối tâm của hai nguyên tử liên kết, được gọi là xen phủ bên. Sự xen phủ bên tạo ra liên kết $\\pi$ (pi) (Hình 12.12).",
    "[Hình ảnh sơ đồ xen phủ orbital p và p tạo liên kết pi]",
    "Hình 12.12. Sơ đồ xen phủ orbital p và p, tạo liên kết $\\pi$",
    "Ở những liên kết đôi và ba (như trong phân tử N$_2$, C$_2$H$_4$,...), ngoài liên kết $\\sigma$ còn có liên kết $\\pi$.",
    "Liên kết đôi gồm một liên kết $\\sigma$ và một liên kết $\\pi$. Liên kết ba gồm một liên kết $\\sigma$ và hai liên kết $\\pi$.",
    "",
    "❓",
    "3. Sự hình thành liên kết $\\sigma$ và liên kết $\\pi$ khác nhau như thế nào?",
    "4. Số liên kết $\\sigma$ và $\\pi$ có trong phân tử C$_2$H$_4$ lần lượt là",
    "A. 4 và 0.          B. 2 và 0.          C. 1 và 1.          D. 5 và 1.",
    "",
    "IV NĂNG LƯỢNG LIÊN KẾT CỘNG HOÁ TRỊ",
    "Năng lượng liên kết ($E_b$)$^{(*)}$ là năng lượng cần thiết để phá vỡ một liên kết hoá học trong phân tử ở thể khí thành các nguyên tử ở thể khí. Năng lượng liên kết thường có đơn vị là kJ/mol.",
    "Ví dụ: Để phá vỡ 1 mol liên kết H—Cl thành các nguyên tử H và Cl (ở thể khí) theo phương trình:",
    "HCl(g) $\\longrightarrow$ H(g) + Cl(g)",
    "cần năng lượng là 432 kJ, nên năng lượng liên kết H—Cl là $E_b$ = 432 kJ/mol.",
    "",
    "$^{(*)}$ $E_b$ là năng lượng liên kết, chữ b viết tắt của từ tiếng Anh \"bond\", nghĩa là liên kết.",
    "",
    "61",
    "",
    "Bảng 12.2. Năng lượng liên kết trung bình của một số liên kết hoá học$^{(**)}$",
    "",
    "| Liên kết | E$_b$ (kJ/mol) | Liên kết | E$_b$ (kJ/mol) |",
    "|---|---|---|---|",
    "| F—F | 159 | C—C | 346 |",
    "| Cl—Cl | 243 | C$=$C | 612 |",
    "| Br—Br | 193 | C$\\equiv$C | 835 |",
    "| I—I | 151 | C—H | 418 |",
    "| H—F | 569 | C$=$O | 732 |",
    "| H—Cl | 432 | O$=$O | 494 |",
    "| H—Br | 366 | N$\\equiv$N | 945 |",
    "| H—I | 299 | N—H | 386 |",
    "| H—H | 436 | O—H | 459 |",
    "",
    "Năng lượng liên kết đặc trưng cho độ bền của liên kết. Năng lượng liên kết càng lớn thì liên kết càng bền và phân tử càng khó bị phân huỷ.",
    "",
    "EM CÓ BIẾT",
    "Dựa vào hiệu giữa năng lượng liên kết của các chất tham gia và tạo thành sau phản ứng, có thể biết được phản ứng nào toả nhiệt và phản ứng nào thu nhiệt, từ đó sử dụng biện pháp thích hợp để tận dụng nhiệt và sử dụng nhiệt phù hợp hoặc có thể tính được lượng nhiệt toả ra hay thu vào của phản ứng.",
    "Ví dụ: Trong phản ứng đốt than, dầu, xăng, do năng lượng liên kết của sản phẩm cháy lớn hơn năng lượng liên kết của chất bị đốt nên phản ứng toả nhiệt. Ngược lại, trong phản ứng phân huỷ nước để điều chế hydrogen làm nhiên liệu, do năng lượng liên kết của chất ban đầu lớn hơn năng lượng liên kết của sản phẩm nên phản ứng thu nhiệt, phải cung cấp nhiệt để phản ứng xảy ra.",
    "",
    "❓",
    "5. Năng lượng liên kết là gì? Năng lượng liên kết của phân tử Cl$_2$ là 243 kJ/mol cho biết điều gì?",
    "6. Dựa vào giá trị năng lượng liên kết ở Bảng 12.2, hãy chọn phương án đúng khi so sánh độ bền liên kết giữa Cl$_2$, Br$_2$ và I$_2$.",
    "A. I$_2$ > Br$_2$ > Cl$_2$.",
    "B. Br$_2$ > Cl$_2$ > I$_2$.",
    "C. Cl$_2$ > Br$_2$ > I$_2$.",
    "D. Cl$_2$ > I$_2$ > Br$_2$.",
    "",
    "$^{(**)}$ Nguồn: Raymond E. Davis, Regina Frey, Mickey Sarquis, Jerry L.Sarquis. (2009). Modern Chemistry. Holt, Rinehart and Wiston.",
    "",
    "62",
    "",
    "EM ĐÃ HỌC",
    "• Cách viết công thức Lewis của một số chất đơn giản.",
    "• Liên kết cộng hoá trị được tạo thành giữa hai nguyên tử bằng một hay nhiều cặp electron dùng chung.",
    "• Sự xen phủ orbital theo trục liên kết tạo ra liên kết $\\sigma$. Sự xen phủ bên của các orbital tạo ra liên kết $\\pi$.",
    "• Các liên kết cộng hoá trị đơn đều là liên kết $\\sigma$, 1 liên kết đôi gồm 1 liên kết $\\sigma$ và 1 liên kết $\\pi$, 1 liên kết ba gồm 1 liên kết $\\sigma$ và 2 liên kết $\\pi$.",
    "• Dựa vào hiệu độ âm điện của các nguyên tử, dự đoán loại liên kết:",
    "[Hình ảnh sơ đồ phân loại liên kết theo hiệu độ âm điện]",
    "0 $\\le$ $\\Delta\\chi$ < 0,4: Liên kết cộng hoá trị không phân cực",
    "0,4 $\\le$ $\\Delta\\chi$ < 1,7: Liên kết cộng hoá trị phân cực",
    "$\\Delta\\chi$ $\\ge$ 1,7: Liên kết ion",
    "• Năng lượng liên kết là năng lượng cần thiết để phá vỡ một liên kết hoá học trong phân tử ở thể khí thành các nguyên tử ở thể khí. Năng lượng liên kết đặc trưng cho độ bền của liên kết.",
    "",
    "EM CÓ THỂ",
    "Phân biệt được liên kết ion, liên kết cộng hoá trị phân cực và liên kết cộng hoá trị không phân cực theo độ âm điện.",
    "",
    "63"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'BAI_13', 'LIÊN KẾT HYDROGEN VÀ TƯƠNG TÁC VAN DER WAALS', 64, 13, $JSON$
{
  "content": [
    "BÀI 13 LIÊN KẾT HYDROGEN VÀ TƯƠNG TÁC VAN DER WAALS",
    "",
    "MỤC TIÊU:",
    "– Trình bày được khái niệm liên kết hydrogen. Vận dụng để giải thích sự xuất hiện liên kết hydrogen (với nguyên tố có độ âm điện lớn: N, O, F).",
    "– Nêu được vai trò, ảnh hưởng của liên kết hydrogen tới tính chất vật lí của nước.",
    "– Nêu được khái niệm về tương tác van der Waals và ảnh hưởng của tương tác này tới nhiệt độ nóng chảy, nhiệt độ sôi của các chất.",
    "",
    "❓",
    "Ở áp suất khí quyển, nhiệt độ sôi của H$_2$O là 100 $^\\circ$C, CH$_4$ là –161,58 $^\\circ$C, H$_2$S là –60,28 $^\\circ$C. Vì sao các chất trên có nhiệt độ sôi khác nhau?",
    "",
    "I MỞ ĐẦU",
    "Các tính chất vật lí của các chất có liên kết cộng hoá trị được quyết định bởi lực tương tác giữa các phân tử, hình dạng của phân tử và mức độ phân cực của liên kết cộng hoá trị trong phân tử. Keo dán là một ví dụ về việc sử dụng lực tương tác giữa các phân tử để gắn các vật với nhau. Bong bóng xà phòng thể hiện tương tác giữa các phân tử nước và các phân tử xà phòng tạo thành màng mỏng, giữ được không khí bên trong để bay lên.",
    "Lực tương tác giữa các phân tử yếu hơn rất nhiều so với lực liên kết ion, liên kết cộng hoá trị hay liên kết kim loại. Một số tương tác điển hình giữa các phân tử là liên kết hydrogen và tương tác van der Waals (Van đơ Van).",
    "",
    "II LIÊN KẾT HYDROGEN",
    "1. Bản chất của liên kết hydrogen",
    "Các phân tử HF, H$_2$O, NH$_3$ có chứa nguyên tử H (độ âm điện là 2,2) và các nguyên tử phi kim có độ âm điện lớn (F = 3,98; O = 3,44; N = 3,04). Sự chênh lệch độ âm điện lớn làm cho các liên kết phân cực, cặp electron dùng chung trong liên kết cộng hoá trị bị hút lệch về phía các nguyên tử F, O, N, tạo thành khu vực có điện tích âm ($\\delta^-$).",
    "Nguyên tử hydrogen trong các phân tử HF, H$_2$O, NH$_3$ rất linh động, có điện tích dương ($\\delta^+$) đủ lớn để hút cặp electron hoá trị chưa liên kết trên nguyên tử F, O hoặc N (của phân tử khác) có độ âm điện lớn tạo thành liên kết hydrogen. Liên kết hydrogen thường được biểu diễn bằng dấu ba chấm (...) giữa các nguyên tử (Hình 13.1).",
    "[Hình ảnh sơ đồ biểu diễn liên kết hydrogen giữa hai phân tử ammonia]",
    "hay vẽ đơn giản H—N $\\dots$ H—N",
    "Hình 13.1. Liên kết hydrogen giữa hai phân tử ammonia",
    "",
    "64",
    "",
    "Điều kiện cần và đủ để tạo thành liên kết hydrogen:",
    "• Nguyên tử hydrogen liên kết với các nguyên tử có độ âm điện lớn như F, O, N,...",
    "• Nguyên tử F, O, N,... liên kết với hydrogen phải có ít nhất một cặp electron hoá trị chưa liên kết.",
    "Một số kiểu tạo thành liên kết hydrogen:",
    "[Hình ảnh hai kiểu tạo thành liên kết hydrogen]",
    "a) Liên kết giữa các phân tử cùng loại      b) Liên kết giữa các phân tử khác loại",
    "Hình 13.2. Hai kiểu tạo thành liên kết hydrogen",
    "",
    "2. Vai trò và ảnh hưởng của liên kết hydrogen tới tính chất vật lí của nước",
    "Liên kết hydrogen làm tăng nhiệt độ nóng chảy, nhiệt độ sôi của nước.",
    "Bảng 13.1. Nhiệt độ nóng chảy và nhiệt độ sôi một số chất",
    "",
    "| | H$_2$O | H$_2$S | CH$_4$ |",
    "|---|---|---|---|",
    "| Nhiệt độ nóng chảy ($^\\circ$C) | 0 | –85,6 | –182,5 |",
    "| Nhiệt độ sôi ($^\\circ$C) | 100 | –60,75 | –161,58 |",
    "",
    "Số liệu Bảng 13.1 cho thấy: do ảnh hưởng của liên kết hydrogen nên nhiệt độ nóng chảy và nhiệt độ sôi của H$_2$O cao hơn nhiều so với H$_2$S và CH$_4$.",
    "",
    "EM CÓ BIẾT",
    "Liên kết hydrogen ảnh hưởng đến tính chất của nước đá. Nguyên tử O có 2 cặp electron chưa liên kết nên có thể tạo 2 liên kết hydrogen với 2 nguyên tử H của các phân tử nước khác, 2 nguyên tử H của phân tử nước đủ điều kiện để tạo liên kết hydrogen với 2 nguyên tử O của các phân tử nước khác. Như vậy, một phân tử nước có thể tạo ra 4 liên kết hydrogen với các phân tử nước khác xung quanh tạo thành cấu trúc tứ diện (Hình 13.3). Mạng tinh thể nước đá có vô số cấu trúc như vậy. Cấu trúc này khá “rỗng” nên nước đá nhẹ hơn nước lỏng và có thể nổi một phần trên bề mặt nước lỏng.",
    "Do có liên kết hydrogen mà nước dễ dàng dâng lên trong mao quản của rễ cây để vận chuyển lên thân và lá cây.",
    "Khi nhiệt độ tăng từ 0 $^\\circ$C đến 4 $^\\circ$C, các cấu trúc tứ diện trong nước đá bị phá vỡ một phần và các phân tử nước được sắp xếp lại gần nhau hơn, làm cho khối lượng riêng của nước tăng dần. Khi nhiệt độ tiếp tục tăng lên, khoảng cách giữa các phân tử nước tăng, làm khối lượng riêng của nước giảm. Các phân tử nước đóng vai trò điều hoà nhiệt độ trên Trái Đất.",
    "Liên kết hydrogen còn tạo nên cấu trúc xoắn của các protein, carbohydrate và nucleic acid, đảm bảo chức năng đặc biệt của chúng đối với cơ thể sống.",
    "",
    "[Hình ảnh mô hình cấu trúc nước đá]",
    "Phân tử H$_2$O",
    "Hình 13.3. Mô hình cấu trúc nước đá",
    "",
    "65",
    "",
    "❓",
    "1. Vẽ sơ đồ biểu diễn liên kết hydrogen giữa:",
    "a) hai phân tử hydrogen fluoride (HF).",
    "b) phân tử hydrogen fluoride (HF) và phân tử ammonia (NH$_3$).",
    "2. Những nguyên tử hydrogen nào trong phân tử ethanol (CH$_3$CH$_2$OH) không tham gia vào liên kết hydrogen? Vì sao?",
    "",
    "III TƯƠNG TÁC VAN DER WAALS",
    "1. Khái niệm tương tác van der Waals",
    "Cùng là phân tử không phân cực, ở nhiệt độ phòng, fluorine, chlorine là những chất khí còn bromine là chất lỏng. Như vậy, ở trạng thái lỏng, giữa các phân tử bromine tồn tại một tương tác yếu. Tương tác yếu đó gọi là tương tác van der Waals.",
    "Các khí hiếm như neon, argon,... tồn tại dưới dạng các nguyên tử độc lập. Tuy nhiên ở nhiệt độ thấp, khí hiếm có thể hoá lỏng. Như vậy, ở nhiệt độ thấp, giữa các nguyên tử khí hiếm tồn tại một tương tác yếu để giữ các nguyên tử khí hiếm lại với nhau trong trạng thái lỏng. Tương tác đó cũng là tương tác van der Waals.",
    "Tương tác van der Waals là tương tác tĩnh điện lưỡng cực – lưỡng cực giữa các nguyên tử hay phân tử.",
    "",
    "EM CÓ BIẾT",
    "Sự hình thành tương tác van der Waals",
    "Tương tác van der Waals thể hiện rõ ở các chất cộng hoá trị phân cực do chúng có cấu tạo lưỡng cực, một đầu mang một phần điện tích âm và một đầu mang một phần điện tích dương. Các nguyên tử khí hiếm hoặc các chất cộng hoá trị không phân cực, do đám mây electron luôn chuyển động nên cũng có thể tạo ra một lưỡng cực tạm thời (Hình 13.4). Lực hút giữa một đầu mang một phần điện tích âm ($\\delta^-$) của lưỡng cực trong phân tử này và một đầu mang một phần điện tích dương ($\\delta^+$) của lưỡng cực trong phân tử khác tạo thành tương tác van der Waals.",
    "[Hình ảnh mô tả sự tạo thành tương tác van der Waals]",
    "Chuyển động của electron dẫn đến lưỡng cực tạm thời Nguyên tử không có lưỡng cực",
    "lực đẩy lực hút",
    "Lưỡng cực trên một nguyên tử tạo ra lưỡng cực trên một nguyên tử khác",
    "Hình 13.4. Mô tả sự tạo thành tương tác van der Waals",
    "",
    "2. Ảnh hưởng của tương tác van der Waals đến nhiệt độ nóng chảy, nhiệt độ sôi của các chất",
    "Ví dụ 1: Trong dãy halogen, tương tác van der Waals tăng theo sự tăng của số electron (và proton) trong phân tử, làm tăng nhiệt độ nóng chảy, nhiệt độ sôi của các chất (Bảng 13.2).",
    "",
    "66",
    "",
    "Bảng 13.2. Nhiệt độ nóng chảy và nhiệt độ sôi tăng khi tương tác van der Waals tăng",
    "",
    "| Halogen | F$_2$ | Cl$_2$ | Br$_2$ | I$_2$ |",
    "|---|---|---|---|---|",
    "| Khối lượng mol (g/mol) | 38,0 | 70,9 | 159,8 | 253,8 |",
    "| Tổng số electron | 18 | 34 | 70 | 106 |",
    "| Nhiệt độ sôi ($^\\circ$C) | –188,1 | –34,1 | 59,2 | 185,5 |",
    "| Nhiệt độ nóng chảy ($^\\circ$C) | –219,6 | –101,0 | –7,3 | 113,6 |",
    "",
    "Ví dụ 2: Pentane là hydrocarbon no có công thức C$_5$H$_{12}$. Đồng phân mạch không phân nhánh pentane có nhiệt độ sôi (36 $^\\circ$C) cao hơn so với đồng phân mạch nhánh neopentane (9,5 $^\\circ$C) do diện tích tiếp xúc giữa các phân tử pentane lớn hơn nhiều so với neopentane.",
    "[Hình ảnh mô phỏng tương tác van der Waals giữa các phân tử pentane và neopentane]",
    "Hình 13.5. Tương tác van der Waals giữa các phân tử pentane và neopentane",
    "Hình 13.5 cho thấy để phá vỡ lực liên phân tử giữa các phân tử pentane cần nhiều năng lượng hơn so với neopentane, nên nhiệt độ sôi cao hơn.",
    "",
    "EM CÓ BIẾT",
    "Khi khối lượng phân tử tăng thì tương tác van der Waals tăng. Ví dụ, tổng tương tác van der Waals giữa các phân tử polyethene lớn hơn rất nhiều so với giữa các phân tử ethene. Đó là lí do tại sao polyethene là một chất rắn ở điều kiện thường.",
    "",
    "❓",
    "3. Hãy giải thích sự khác nhau về nhiệt độ sôi của butane và isobutane.",
    "",
    "EM ĐÃ HỌC",
    "• Liên kết hydrogen được hình thành giữa nguyên tử H (đã liên kết với một nguyên tử có độ âm điện lớn) với một nguyên tử khác (có độ âm điện lớn) còn cặp electron hoá trị chưa tham gia liên kết.",
    "• Liên kết hydrogen làm tăng nhiệt độ nóng chảy và nhiệt độ sôi của nước.",
    "• Tương tác van der Waals là tương tác tĩnh điện lưỡng cực – lưỡng cực được hình thành giữa các phân tử hay nguyên tử.",
    "• Tương tác van der Waals làm tăng nhiệt độ nóng chảy và nhiệt độ sôi của các chất.",
    "",
    "EM CÓ THỂ",
    "So sánh được tính chất vật lí giữa các phân tử dựa vào liên kết hydrogen và tương tác van der Waals.",
    "",
    "67"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_3' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'BAI_14', 'ÔN TẬP CHƯƠNG 3', 68, 14, $JSON$
{
  "content": [
    "BÀI 14 ÔN TẬP CHƯƠNG 3",
    "",
    "I HỆ THỐNG HOÁ KIẾN THỨC",
    "Hoàn thành sơ đồ hệ thống hoá kiến thức sau:",
    "",
    "[Sơ đồ tư duy]",
    "LIÊN KẾT HOÁ HỌC $\\rightarrow$ LIÊN KẾT CỘNG HOÁ TRỊ",
    "• KHÁI NIỆM: là liên kết hoá học được hình thành giữa hai nguyên tử bằng ................?....................",
    "• KIỂU LIÊN KẾT: ......?...... (–); ......?...... (=) và ......?...... ($\\equiv$).",
    "$\\rightarrow$ • KHÔNG PHÂN CỰC: cặp electron dùng chung .................?.........",
