    "Ví dụ: ...................?.....................",
    "",
    "LIÊN KẾT HOÁ HỌC $\\rightarrow$ LIÊN KẾT ION",
    "• KHÁI NIỆM: là liên kết hoá học được hình thành giữa hai .........?......... (tồn tại trong khối tinh thể)",
    "Ví dụ: ...................?.....................",
    "• TINH THỂ ION: Các ion ......?......và........?.... sắp xếp tại các nút của .....?..... theo trật tự luân phiên, liên kết bằng .....?.....",
    "",
    "Hiệu độ âm điện giữa hai nguyên tử liên kết có giá trị trong khoảng",
    "[Hình ảnh trục số phân loại liên kết theo hiệu độ âm điện]",
    "0 $\\le$ $\\Delta\\chi$ < 0,4: Liên kết cộng hoá trị không phân cực",
    "0,4 $\\le$ $\\Delta\\chi$ < 1,7: Liên kết cộng hoá trị phân cực",
    "$\\Delta\\chi$ $\\ge$ 1,7: Liên kết ion",
    "(Độ phân cực liên kết tăng dần)",
    "",
    "LIÊN KẾT HYDROGEN VÀ TƯƠNG TÁC VAN DER WAALS",
    "• KHÁI NIỆM: đều là liên kết giữa các ........?........ (..........?..........) trung hoà hút nhau bởi bản chất tĩnh điện giữa các lưỡng cực $\\delta+$ và $\\delta–$.",
    "• LIÊN KẾT HYDROGEN: ... H – O – H ... F – H ...",
    "• TƯƠNG TÁC VAN DER WAALS: $\\delta+$ $\\delta–$ $\\delta+$ $\\delta–$",
    "• ẢNH HƯỞNG: đều làm .....?..... nhiệt độ sôi, nhiệt độ nóng chảy của các chất.",
    "",
    "68",
    "",
    "II LUYỆN TẬP",
    "Câu 1. Dãy các chất nào dưới đây mà tất cả các phân tử đều có liên kết ion?",
    "A. Cl$_2$, Br$_2$, I$_2$, HCl.",
    "B. Na$_2$O, KCl, BaCl$_2$, Al$_2$O$_3$.",
    "C. HCl, H$_2$S, NaCl, N$_2$O.",
    "D. MgO, H$_2$SO$_4$, H$_3$PO$_4$, HCl.",
    "",
