    "",
    "Câu 3. Viết công thức cấu tạo và công thức Lewis của các phân tử sau: PH$_3$, H$_2$O, C$_2$H$_6$. Trong phân tử nào có liên kết phân cực mạnh nhất?",
    "",
    "Câu 4. Dựa vào giá trị độ âm điện của các nguyên tử trong Bảng 6.2, xác định loại liên kết trong phân tử các chất: CH$_4$, CaCl$_2$, HBr, NH$_3$.",
    "",
    "Câu 5. Cho dãy các oxide sau : Na$_2$O, MgO, Al$_2$O$_3$, SiO$_2$, P$_2$O$_5$, SO$_3$, Cl$_2$O$_7$.",
