INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'BAI_15', 'PHẢN ỨNG OXI HOÁ - KHỬ', 71, 15, $JSON$
{
  "content": [
    "BÀI 15 PHẢN ỨNG OXI HOÁ – KHỬ",
    "",
    "MỤC TIÊU:",
    "– Nêu được khái niệm và xác định được số oxi hoá của nguyên tử các nguyên tố trong hợp chất.",
    "– Nêu được khái niệm và ý nghĩa của phản ứng oxi hoá – khử.",
    "– Lập được phương trình hoá học của phản ứng oxi hoá – khử bằng phương pháp thăng bằng electron.",
    "– Mô tả được một số phản ứng oxi hoá – khử quan trọng trong cuộc sống.",
    "",
    "❓",
    "Trong lò luyện gang, xảy ra phản ứng oxi hoá – khử theo sơ đồ sau:",
    "Fe$_2$O$_3$ + CO $\\xrightarrow{t^\\circ}$ Fe + CO$_2$",
    "Về bản chất, phản ứng oxi hoá – khử là gì? Dựa vào dấu hiệu nào để nhận ra loại phản ứng đó?",
    "Làm thế nào để lập phương trình hoá học của phản ứng trên?",
    "",
    "I SỐ OXI HOÁ",
    "1. Khái niệm",
    "Số oxi hoá là điện tích quy ước của nguyên tử trong phân tử khi coi tất cả các electron liên kết đều chuyển hoàn toàn về nguyên tử có độ âm điện lớn hơn.",
    "Số oxi hoá được viết ở dạng số đại số, dấu viết trước, số viết sau.",
    "Ví dụ 1: Xét phân tử NaCl.",
    "Nguyên tử Na nhường 1 electron cho nguyên tử Cl, khi đó nguyên tử Na trở thành ion dương mang điện tích 1+ (số oxi hoá của Na là +1) và nguyên tử Cl nhận 1 electron của nguyên tử Na trở thành ion âm mang điện tích 1– (số oxi hoá của Cl là –1):",
    "$\\overset{+1}{\\text{Na}}\\overset{-1}{\\text{Cl}}$",
    "",
    "Ví dụ 2: Xét phân tử H$_2$O.",
    "H $\\mathbf{:}$ $\\ddot{\\text{O}}$ $\\mathbf{:}$ H",
    "Độ âm điện của nguyên tử O lớn hơn độ âm điện của nguyên tử H, nếu các cặp electron liên kết chuyển hoàn toàn về nguyên tử O thì nguyên tử O có thêm 2 electron và trở thành ion âm có điện tích 2– (số oxi hoá của O là –2); mỗi nguyên tử H mất đi 1 electron và trở thành ion dương có điện tích 1+ (số oxi hoá của H là +1):",
    "$\\overset{+1}{\\text{H}}_2\\overset{-2}{\\text{O}}$",
    "",
    "Ví dụ 3: Xét phân tử H$_2$.",
    "H $\\mathbf{:}$ H",
    "",
    "71",
    "",
    "Hai nguyên tử H giống nhau nên cặp electron liên kết không lệch về nguyên tử nào. Do vậy, mỗi nguyên tử H đều trung hoà điện, có điện tích bằng 0 và số oxi hoá là 0:",
    "$\\overset{0}{\\text{H}}_2$",
    "Số oxi hoá thường được dùng để lập phương trình hoá học của phản ứng oxi hoá – khử.",
    "",
    "2. Quy tắc xác định số oxi hoá",
    "Thông thường, số oxi hoá của nguyên tử được xác định trực tiếp từ công thức phân tử theo các quy tắc sau:",
    "",
    "Quy tắc 1. Trong đơn chất, số oxi hoá của nguyên tử bằng 0.",
    "Ví dụ:",
    "$\\overset{0}{\\text{C}}$      $\\overset{0}{\\text{Na}}$      $\\overset{0}{\\text{H}}_2$      $\\overset{0}{\\text{O}}_2$",
    "",
    "Quy tắc 2. Trong phân tử các hợp chất, thông thường số oxi hoá của hydrogen là +1, của oxygen là –2, các kim loại điển hình có số oxi hoá dương và có giá trị bằng số electron hoá trị.",
    "",
    "Bảng 15.1. Số oxi hoá thường gặp của một số nguyên tử trong hợp chất",
    "",
    "| Nguyên tử | Hydrogen | Oxygen | Kim loại kiềm (nhóm IA) | Kim loại kiềm thổ (nhóm IIA) | Aluminium |",
    "|---|---|---|---|---|---|",
    "| Số oxi hoá | +1 | –2 | +1 | +2 | +3 |",
    "",
    "Quy tắc 3. Trong hợp chất, tổng số oxi hoá của các nguyên tử trong phân tử bằng 0.",
    "Ví dụ: $\\overset{+3}{\\text{Al}}_2\\overset{-2}{\\text{O}}_3$",
    "Tổng số oxi hoá = (+3)$\\cdot$2 + (–2)$\\cdot$3 = 0.",
    "",
    "Quy tắc 4. Trong ion đơn nguyên tử, số oxi hoá của nguyên tử bằng điện tích ion; trong ion đa nguyên tử, tổng số oxi hoá của các nguyên tử bằng điện tích ion.",
    "Ví dụ: $\\left[ \\overset{-3}{\\text{N}}\\overset{+1}{\\text{H}}_4 \\right]^+$",
    "Tổng số oxi hoá = (–3) + (+1)$\\cdot$4 = +1.",
    "",
    "ÁP DỤNG: Sử dụng các quy tắc này có thể xác định số oxi hoá của một nguyên tử trong hợp chất khi biết số oxi hoá của các nguyên tử còn lại.",
    "",
    "Ví dụ: Xác định số oxi hoá của nguyên tử C trong phân tử CaCO$_3$.",
    "Dựa vào Bảng 15.1, biết được số oxi hoá của Ca là +2 và O là –2.",
    "Số oxi hoá của từng nguyên tử: $\\overset{+2}{\\text{Ca}}\\overset{x}{\\text{C}}\\overset{-2}{\\text{O}}_3$",
    "Phân tử CaCO$_3$ trung hoà điện nên tổng số oxi hoá của các nguyên tử bằng 0:",
    "(+2) + $x$ + (–2)$\\cdot$3 = 0 nên $x$ = +4.",
    "",
    "72",
    "",
    "❓",
    "1. Xác định số oxi hoá của nguyên tử Fe và S trong các chất sau:",
    "a) Fe, FeO, Fe$_2$O$_3$, Fe(OH)$_3$, Fe$_3$O$_4$.",
    "b) S, H$_2$S, SO$_2$, SO$_3$, H$_2$SO$_4$, Na$_2$SO$_3$.",
    "",
    "II CHẤT OXI HOÁ, CHẤT KHỬ, PHẢN ỨNG OXI HOÁ – KHỬ",
    "1. Chất oxi hoá, chất khử",
    "Ví dụ 1: Đưa mẩu than gỗ nóng đỏ vào bình đựng khí O$_2$, mẩu than cháy sáng.",
    "$\\overset{0}{\\text{C}} + \\overset{0}{\\text{O}}_2 \\xrightarrow{t^\\circ} \\overset{+4}{\\text{C}}\\overset{-2}{\\text{O}}_2$",
    "Trong phản ứng trên, nguyên tử C nhường 4 electron, là chất khử; phân tử O$_2$ nhận 4 electron, là chất oxi hoá.",
    "$\\overset{0}{\\text{C}} \\longrightarrow \\overset{+4}{\\text{C}} + 4\\text{e}$ (quá trình oxi hoá)",
    "$\\overset{0}{\\text{O}}_2 + 4\\text{e} \\longrightarrow 2\\overset{-2}{\\text{O}}$ (quá trình khử)",
    "",
    "Ví dụ 2: Phản ứng đốt cháy methane.",
    "$\\overset{-4}{\\text{C}}\\overset{+1}{\\text{H}}_4 + 2\\overset{0}{\\text{O}}_2 \\xrightarrow{t^\\circ} \\overset{+4}{\\text{C}}\\overset{-2}{\\text{O}}_2 + 2\\overset{+1}{\\text{H}}_2\\overset{-2}{\\text{O}}$",
    "Chất oxi hoá là oxygen, chất khử là methane.",
    "",
    "Ví dụ 3: Phản ứng khử Fe$_2$O$_3$ bằng CO để sản xuất gang và thép.",
    "$\\overset{+3}{\\text{Fe}}_2\\text{O}_3 + 3\\overset{+2}{\\text{C}}\\text{O} \\xrightarrow{t^\\circ} 2\\overset{0}{\\text{Fe}} + 3\\overset{+4}{\\text{C}}\\text{O}_2$",
    "Chất oxi hoá là iron(III) oxide, chất khử là carbon monooxide.",
    "",
    "Chất khử là chất nhường electron, chất oxi hoá là chất nhận electron.",
    "Quá trình oxi hoá là quá trình chất khử nhường electron, quá trình khử là quá trình chất oxi hoá nhận electron.",
    "",
    "Xác định chất oxi hoá, chất khử",
    "Chuẩn bị: đinh sắt, dung dịch CuSO$_4$, dung dịch H$_2$SO$_4$ loãng, ống nghiệm.",
    "Thực hiện:",
    "Thí nghiệm 1: Cho đinh sắt vào ống nghiệm đựng dung dịch CuSO$_4$.",
    "Thí nghiệm 2: Cho đinh sắt vào ống nghiệm đựng dung dịch H$_2$SO$_4$.",
    "Quan sát hiện tượng và thực hiện yêu cầu sau:",
    "1. Viết quá trình oxi hoá, quá trình khử.",
    "2. Xác định chất oxi hoá, chất khử trong hai phản ứng trên.",
    "",
    "73",
    "",
    "2. Phản ứng oxi hoá – khử",
    "Phản ứng oxi hoá – khử là phản ứng hoá học xảy ra đồng thời quá trình nhường electron và quá trình nhận electron.",
    "Dấu hiệu để nhận biết phản ứng oxi hoá – khử là có sự thay đổi số oxi hoá của các nguyên tử.",
    "",
    "❓",
    "2. Trong không khí ẩm, Fe(OH)$_2$ màu trắng xanh chuyển dần sang Fe(OH)$_3$ màu nâu đỏ theo sơ đồ sau:",
    "Fe(OH)$_2$ + O$_2$ + H$_2$O $\\longrightarrow$ Fe(OH)$_3$",
    "a) Hãy xác định các nguyên tử có sự thay đổi số oxi hoá.",
    "b) Viết quá trình oxi hoá, quá trình khử.",
    "c) Dùng mũi tên biểu diễn sự chuyển electron từ chất khử sang chất oxi hoá.",
    "",
    "III LẬP PHƯƠNG TRÌNH HOÁ HỌC CỦA PHẢN ỨNG OXI HOÁ – KHỬ",
    "Phương pháp thăng bằng electron được dùng để lập phương trình hoá học của phản ứng oxi hoá – khử theo nguyên tắc:",
    "Tổng số electron chất khử nhường bằng tổng số electron chất oxi hoá nhận.",
    "",
    "Ví dụ: Quá trình Ostwald (Ót-xvan) dùng để sản xuất nitric acid từ ammonia, được đề xuất vào năm 1902. Ở giai đoạn đầu của quá trình, ammonia bị oxi hoá bởi oxygen ở nhiệt độ cao khi có chất xúc tác:",
    "NH$_3$ + O$_2$ $\\xrightarrow{t^\\circ,\\text{ xúc tác}, p}$ NO + H$_2$O",
    "",
    "Theo phương pháp thăng bằng electron, phương trình hoá học của phản ứng trên được lập theo các bước như sau:",
    "Bước 1. Xác định các nguyên tử có sự thay đổi số oxi hoá, từ đó xác định chất oxi hoá, chất khử:",
    "$\\overset{-3}{\\text{N}}\\text{H}_3 + \\overset{0}{\\text{O}}_2 \\longrightarrow \\overset{+2}{\\text{N}}\\overset{-2}{\\text{O}} + \\text{H}_2\\overset{-2}{\\text{O}}$",
    "Chất khử     Chất oxi hoá",
    "",
    "Bước 2. Biểu diễn quá trình oxi hoá, quá trình khử:",
    "$\\overset{-3}{\\text{N}} \\longrightarrow \\overset{+2}{\\text{N}} + 5\\text{e}$",
    "$\\overset{0}{\\text{O}}_2 + 4\\text{e} \\longrightarrow 2\\overset{-2}{\\text{O}}$",
    "",
    "Bước 3. Tìm hệ số thích hợp cho chất khử và chất oxi hoá dựa trên nguyên tắc:",
    "Tổng số electron chất khử nhường bằng tổng số electron chất oxi hoá nhận.",
    "4 $\\times$ | $\\overset{-3}{\\text{N}} \\longrightarrow \\overset{+2}{\\text{N}} + 5\\text{e}$",
    "5 $\\times$ | $\\overset{0}{\\text{O}}_2 + 4\\text{e} \\longrightarrow 2\\overset{-2}{\\text{O}}$",
    "",
    "74",
    "",
    "Bước 4. Đặt hệ số của chất oxi hoá và chất khử vào sơ đồ phản ứng, từ đó tính ra hệ số của các chất khác có mặt trong phương trình hoá học. Kiểm tra sự cân bằng số nguyên tử của các nguyên tố ở hai vế.",
    "4NH$_3$ + 5O$_2$ $\\longrightarrow$ 4NO + 6H$_2$O",
    "",
    "❓",
    "3. Xét các phản ứng hoá học xảy ra trong công nghiệp:",
    "a) Al(OH)$_3$ $\\xrightarrow{t^\\circ}$ Al$_2$O$_3$ + H$_2$O",
    "b) C + CO$_2$ $\\xrightarrow{t^\\circ}$ CO",
    "Phản ứng nào là phản ứng oxi hoá – khử? Lập phương trình hoá học của phản ứng oxi hoá – khử theo phương pháp thăng bằng electron.",
    "",
    "IV PHẢN ỨNG OXI HOÁ – KHỬ TRONG THỰC TIỄN",
    "Trong thực tiễn, phản ứng oxi hoá – khử rất phổ biến, dưới đây là một số trường hợp điển hình.",
    "",
    "1. Sự cháy",
    "Phản ứng cháy là phản ứng oxi hoá – khử xảy ra ở nhiệt độ cao giữa chất cháy và chất oxi hoá.",
    "Trong phản ứng cháy, chất cháy thường là nhiên liệu (than đá, khí thiên nhiên, xăng, dầu,...), còn chất oxi hoá thường là oxygen. Sự cháy kèm theo sự toả nhiệt và phát sáng, tạo ra nhiệt lượng đủ để duy trì sự cháy.",
    "Ví dụ: Phản ứng oxi hoá – khử xảy ra khi đốt cháy carbon trong than đá và butane trong khí gas:",
    "C + O$_2$ $\\xrightarrow{t^\\circ}$ CO$_2$",
    "2C$_4$H$_{10}$ + 13O$_2$ $\\xrightarrow{t^\\circ}$ 8CO$_2$ + 10H$_2$O",
    "",
    "2. Sự han gỉ kim loại",
    "Sau một thời gian sử dụng, nhiều thiết bị, máy móc, vật dụng bằng kim loại thường bị han gỉ do sự oxi hoá bởi oxygen trong không khí. Đặc biệt, nước ta có khí hậu nhiệt đới, độ ẩm cao nên sự han gỉ kim loại xảy ra rất phổ biến.",
    "Ví dụ: Trong không khí ẩm, các vật dụng bằng thép bị oxi hoá tạo gỉ sắt.",
    "4Fe + 3O$_2$ + $x$H$_2$O $\\longrightarrow$ 2Fe$_2$O$_3$$\\cdot$$x$H$_2$O",
    "",
    "3. Sản xuất hoá chất",
    "Trong công nghiệp, phần lớn các phản ứng hoá học xảy ra trong các quy trình sản xuất là phản ứng oxi hoá – khử. Ví dụ: Sulfuric acid là hoá chất quan trọng trong công nghiệp, được sản xuất chủ yếu từ sulfur hoặc quặng pyrite.",
    "",
    "75",
    "",
    "Sơ đồ phản ứng:",
    "S $\\xrightarrow{+\\text{O}_2, t^\\circ}$",
    "        $\\searrow$",
    "FeS$_2$ $\\xrightarrow{+\\text{O}_2, t^\\circ}$ $\\rightarrow$ SO$_2$ $\\xrightarrow{+\\text{O}_2, \\text{xt}, t^\\circ}$ SO$_3$ $\\xrightarrow{+\\text{H}_2\\text{O}}$ H$_2$SO$_4$",
    "",
    "4. Chuyển hoá các chất trong tự nhiên",
    "Trong tự nhiên cũng xảy ra rất nhiều quá trình kèm theo phản ứng oxi hoá – khử.",
    "Ví dụ:",
    "Lúa chiêm lấp ló đầu bờ",
    "Hễ nghe tiếng sấm phất cờ mà lên",
    "(Ca dao Việt Nam)",
    "",
    "Đây là hiện tượng cây lúa phát triển nhanh khi có những cơn mưa rào đầu tiên kèm theo sấm sét vào khoảng cuối mùa xuân.",
    "Tia sét tạo ra tia lửa điện, là điều kiện cho nitrogen phản ứng với oxygen:",
    "N$_2$ + O$_2$ $\\xrightarrow{\\text{tia lửa điện}}$ 2NO",
    "",
    "Khí NO sinh ra nhanh chóng chuyển hoá thành NO$_2$, sau đó tiếp tục bị oxi hoá thành HNO$_3$:",
    "2NO + O$_2$ $\\longrightarrow$ 2NO$_2$",
    "4NO$_2$ + O$_2$ + 2H$_2$O $\\longrightarrow$ 4HNO$_3$",
    "",
    "Nitric acid tan vào nước mưa và chuyển hoá thành gốc nitrate (NO$_3^-$), cung cấp chất đạm cho cây lúa. Nhờ quá trình trên, hằng năm một lượng lớn phân đạm tự nhiên được bổ sung cho đất.",
    "",
    "❓",
    "4. Nêu một số phản ứng oxi hoá – khử có lợi và có hại trong thực tế.",
    "5. Lập phương trình hoá học của các phản ứng trong quá trình sản xuất sulfuric acid theo sơ đồ mục IV.3. Trong các phản ứng đó, phản ứng nào là phản ứng oxi hoá – khử?",
    "6. Đèn xì oxygen – acetylene có cấu tạo gồm hai ống dẫn khí: một ống dẫn khí oxygen, một ống dẫn khí acetylene (Hình 15.1). Khi đèn hoạt động, hai khí này được trộn vào nhau để thực hiện phản ứng đốt cháy theo sơ đồ:",
    "C$_2$H$_2$ + O$_2$ $\\xrightarrow{t^\\circ}$ CO$_2$ + H$_2$O",
    "Phản ứng toả nhiệt lớn, tạo ra ngọn lửa có nhiệt độ đạt đến 3 000 $^\\circ$C nên được dùng để hàn cắt kim loại.",
    "Hãy xác định chất oxi hoá, chất khử và lập phương trình hoá học của phản ứng trên theo phương pháp thăng bằng electron.",
    "",
    "[Hình ảnh mỏ hàn cắt kim loại bằng đèn xì oxygen - acetylene]",
    "Oxygen  Acetylene",
    "Hình 15.1. Sơ đồ cấu tạo đèn xì oxygen – acetylene",
    "",
    "76",
    "",
    "7. Trong quá trình luyện gang từ quặng chứa Fe$_2$O$_3$, ban đầu không khí nóng được nén vào lò cao, đốt cháy hoàn toàn than cốc kèm theo toả nhiệt mạnh:",
    "C + O$_2$ $\\xrightarrow{t^\\circ}$ CO$_2$",
    "Khí CO$_2$ đi lên phía trên, gặp các lớp than cốc và bị khử thành CO:",
    "CO$_2$ + C $\\xrightarrow{t^\\circ}$ CO",
    "Tiếp đó, khí CO khử Fe$_2$O$_3$ thành Fe theo phản ứng tổng quát:",
    "Fe$_2$O$_3$ + CO $\\xrightarrow{t^\\circ}$ Fe + CO$_2$",
    "Lập các phương trình hoá học ở trên, chỉ rõ chất oxi hoá, chất khử.",
    "",
    "5. Xác định nồng độ một chất bằng phản ứng oxi hoá – khử",
    "Trong thực tế, dung dịch thuốc tím (KMnO$_4$) được sử dụng phổ biến như một tác nhân oxi hoá mạnh để xác định hàm lượng các chất khử như iron(II), hydrogen peroxide, oxalic acid,...",
    "Ví dụ: Trong quá trình bảo quản, một mẫu iron(II) sulfate bị oxi hoá một phần thành hợp chất iron(III). Hàm lượng iron(II) sulfate còn lại trong mẫu được xác định thông qua phản ứng với dung dịch thuốc tím có nồng độ đã biết:",
    "10FeSO$_4$ + 2KMnO$_4$ + 8H$_2$SO$_4$ $\\longrightarrow$ 5Fe$_2$(SO$_4$)$_3$ + K$_2$SO$_4$ + 2MnSO$_4$ + 8H$_2$O",
    "",
    "EM ĐÃ HỌC",
    "• Số oxi hoá là điện tích quy ước của nguyên tử và được tính theo các quy tắc xác định số oxi hoá.",
    "• Chất khử là chất nhường electron, chất oxi hoá là chất nhận electron.",
    "• Bản chất của phản ứng oxi hoá – khử:",
    "Quá trình khử",
    "$\\downarrow$",
    "Chất oxi hoá 1 + Chất khử 2 $\\longrightarrow$ Chất khử 1 + Chất oxi hoá 2",
    "$\\uparrow$",
    "Quá trình oxi hoá",
    "• Nguyên tắc lập phương trình hoá học của phản ứng oxi hoá – khử theo phương pháp thăng bằng electron:",
    "$\\sum$ số electron chất khử nhường = $\\sum$ số electron chất oxi hoá nhận.",
    "• Các phản ứng oxi hoá – khử xảy ra phổ biến trong thực tiễn: sự cháy, sự han gỉ của kim loại, sản xuất hoá chất, chuyển hoá nitrogen trong tự nhiên,...",
    "",
    "EM CÓ THỂ",
    "Sử dụng phương trình hoá học của phản ứng oxi hoá – khử để giải thích một số quá trình liên quan trong thực tiễn.",
    "",
    "77"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_4' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'BAI_16', 'ÔN TẬP CHƯƠNG 4', 78, 16, $JSON$
{
  "content": [
    "BÀI 16 ÔN TẬP CHƯƠNG 4",
    "",
    "I HỆ THỐNG HOÁ KIẾN THỨC",
    "Hoàn thành các nội dung còn thiếu sau đây:",
    "",
    "Chất ........?........ electron là chất khử",
    "$\\uparrow$",
    "Phản ứng oxi hoá – khử $\\longrightarrow$ Quá trình oxi hoá là quá trình ........?........ nhường electron",
    "$\\downarrow$",
    "Chất ........?........ electron là chất oxi hoá $\\longrightarrow$ Quá trình khử là quá trình ........?........ nhận electron",
    "",
    "Lập phương trình hoá học của phản ứng oxi hoá – khử",
    "• Nguyên tắc:",
    "Tổng số electron chất khử nhường ...?... tổng số electron chất oxi hoá nhận",
    "• Nêu các bước lập phương trình hoá học của phản ứng oxi hoá – khử và cho ví dụ.",
    "",
    "II LUYỆN TẬP",
    "Câu 1. Trong phản ứng oxi hoá – khử, chất oxi hoá là chất",
    "A. nhận electron.             B. nhường proton.",
    "C. nhường electron.           D. nhận proton.",
    "",
    "Câu 2. Trong phản ứng hoá học: Fe + H$_2$SO$_4$ $\\longrightarrow$ FeSO$_4$ + H$_2$, mỗi nguyên tử Fe đã",
    "A. nhường 2 electron.         B. nhận 2 electron.",
    "C. nhường 1 electron.         D. nhận 1 electron.",
    "",
    "Câu 3. Trong phản ứng hoá học: 2Na + 2H$_2$O $\\longrightarrow$ 2NaOH + H$_2$, chất oxi hoá là",
    "A. H$_2$O.      B. NaOH.      C. Na.      D. H$_2$.",
    "",
    "Câu 4. Cho nước Cl$_2$ vào dung dịch NaBr xảy ra phản ứng hoá học:",
    "Cl$_2$ + 2NaBr $\\longrightarrow$ 2NaCl + Br$_2$",
    "Trong phản ứng hoá học trên, xảy ra quá trình oxi hoá chất nào?",
    "A. NaCl.      B. Br$_2$.      C. Cl$_2$.      D. NaBr.",
    "",
    "78",
    "",
    "Câu 5. Xét các phản ứng hoá học xảy ra trong các quá trình sau:",
    "a) Luyện gang từ quặng hematite đỏ:",
    "Fe$_2$O$_3$ + CO $\\xrightarrow{t^\\circ}$ FeO + CO$_2$",
    "FeO + CO $\\xrightarrow{t^\\circ}$ Fe + CO$_2$",
    "b) Luyện zinc (kẽm) từ quặng blend:",
    "ZnS + O$_2$ $\\xrightarrow{t^\\circ}$ ZnO + SO$_2$",
    "ZnO + C $\\xrightarrow{t^\\circ}$ Zn + CO",
    "c) Sản xuất xút, chlorine từ dung dịch muối ăn:",
    "NaCl + H$_2$O $\\xrightarrow[\\text{có màng ngăn xốp}]{\\text{điện phân dung dịch}}$ NaOH + Cl$_2$ + H$_2$",
    "d) Đốt cháy ethanol có trong xăng E5:",
    "C$_2$H$_5$OH + O$_2$ $\\xrightarrow{t^\\circ}$ CO$_2$ + H$_2$O",
    "Hãy chỉ ra các phản ứng oxi hoá – khử, lập phương trình hoá học của các phản ứng đó theo phương pháp thăng bằng electron và chỉ rõ chất oxi hoá, chất khử.",
    "",
    "Câu 6. Xét phản ứng trong giai đoạn đầu của quá trình Ostwald:",
    "NH$_3$ + O$_2$ $\\longrightarrow$ NO + H$_2$O",
    "Trong công nghiệp, cần trộn 1 thể tích khí ammonia với bao nhiêu thể tích không khí để thực hiện phản ứng trên? Biết không khí chứa 21% thể tích oxygen và các thể tích khí đo ở cùng điều kiện về nhiệt độ và áp suất.",
    "",
    "Câu 7. Copper(II) sulfate được dùng để diệt tảo, rong rêu trong nước bể bơi; dùng để pha chế thuốc Bordaux (trừ bệnh mốc sương trên cây cà chua, khoai tây; bệnh thối thân trên cây ăn quả, cây công nghiệp);...",
    "Trong công nghiệp, copper(II) sulfate thường được sản xuất bằng cách ngâm đồng phế liệu trong dung dịch sulfuric acid loãng và sục không khí:",
    "Cu + O$_2$ + H$_2$SO$_4$ $\\longrightarrow$ CuSO$_4$ + H$_2$O (1)",
    "a) Lập phương trình hoá học của phản ứng (1) theo phương pháp thăng bằng electron, chỉ rõ chất oxi hoá, chất khử.",
    "b) Copper(II) sulfate còn được điều chế bằng cách cho đồng phế liệu tác dụng với sulfuric acid đặc, nóng:",
    "Cu + H$_2$SO$_4$(đặc) $\\xrightarrow{t^\\circ}$ CuSO$_4$ + SO$_2$ + H$_2$O (2)",
    "Trong hai cách trên, cách nào sử dụng ít sulfuric acid hơn, cách nào ít gây ô nhiễm môi trường hơn?",
    "",
    "79"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_5' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'BAI_17', 'BIẾN THIÊN ENTHALPY TRONG CÁC PHẢN ỨNG HOÁ HỌC', 81, 17, $JSON$
{
  "content": [
    "BÀI 17 BIẾN THIÊN ENTHALPY TRONG CÁC PHẢN ỨNG HOÁ HỌC",
    "",
    "MỤC TIÊU:",
    "– Trình bày được khái niệm phản ứng toả nhiệt, thu nhiệt; điều kiện chuẩn; nhiệt tạo thành và biến thiên enthalpy (nhiệt phản ứng) của phản ứng.",
    "– Nêu được ý nghĩa của dấu và giá trị của biến thiên enthalpy chuẩn.",
    "– Tính được biến thiên enthalpy chuẩn của một số phản ứng theo năng lượng liên kết, nhiệt tạo thành.",
    "",
    "❓",
    "Phản ứng giữa đường glucose với oxygen tạo ra carbon dioxide, hơi nước và toả nhiều nhiệt.",
    "Sau khi chơi thể thao, cơ thể mệt mỏi, nghỉ ngơi một vài phút, sau đó nếu uống một cốc nước hoa quả, em sẽ cảm thấy khoẻ hơn. Có phải đường glucose đã \"cháy\" và cấp bù năng lượng cho cơ thể?",
    "",
    "I PHẢN ỨNG TOẢ NHIỆT, PHẢN ỨNG THU NHIỆT",
    "Khi các phản ứng hoá học xảy ra thường có sự trao đổi nhiệt với môi trường, làm thay đổi nhiệt độ môi trường.",
    "Phản ứng toả nhiệt là phản ứng giải phóng năng lượng dưới dạng nhiệt.",
    "Phản ứng thu nhiệt là phản ứng hấp thụ năng lượng dưới dạng nhiệt.",
    "",
    "Môi trường $\\downarrow$               Môi trường $\\uparrow$",
    "Môi trường $\\rightarrow$ Phản ứng thu nhiệt $\\leftarrow$ Môi trường           Môi trường $\\leftarrow$ Phản ứng toả nhiệt $\\rightarrow$ Môi trường",
    "Môi trường $\\uparrow$               Môi trường $\\downarrow$",
    "",
    "Ví dụ: Vào những ngày trời lạnh, nhiều người hay ngồi bên bếp lửa để sưởi. Khi than, củi cháy, không khí xung quanh ấm hơn do phản ứng toả nhiệt. Những lúc nóng nực, pha viên sủi vitamin C vào nước để giải khát, khi viên sủi tan, thấy nước trong cốc mát hơn, đó là do xảy ra phản ứng thu nhiệt.",
    "Khi nung vôi, người ta sử dụng phản ứng đốt cháy than để cung cấp nhiệt cho phản ứng phân huỷ đá vôi. Phản ứng đốt than là phản ứng toả nhiệt, phản ứng phân huỷ đá vôi là phản ứng thu nhiệt.",
    "",
    "❓",
    "1. Khi đun nóng ống nghiệm đựng KMnO$_4$ (thuốc tím), nhiệt của ngọn lửa làm cho KMnO$_4$ bị nhiệt phân, tạo hỗn hợp bột màu đen:",
    "2KMnO$_4$(s) $\\longrightarrow$ K$_2$MnO$_4$(s) + MnO$_2$(s) + O$_2$(g)",
    "Em hãy dự đoán phản ứng này toả nhiệt hay thu nhiệt.",
    "",
    "81",
    "",
    "Theo dõi sự thay đổi nhiệt độ của phản ứng trung hoà",
    "Chuẩn bị: dung dịch HCl 0,5 M, dung dịch NaOH 0,5 M, 1 cốc 250 mL, giá treo nhiệt kế, nhiệt kế (có dải đo đến 100 $^\\circ$C), que khuấy và 2 ống đong 50 mL.",
    "Tiến hành:",
    "• Dùng ống đong lấy 50 mL dung dịch HCl 0,5 M cho vào cốc phản ứng, lắp nhiệt kế lên giá sao cho đầu nhiệt kế nhúng vào dung dịch trong cốc (Hình 17.1). Đọc nhiệt độ dung dịch.",
    "• Dùng ống đong khác lấy 50 mL dung dịch NaOH 0,5 M cho vào cốc phản ứng. Khuấy nhẹ.",
    "Theo dõi sự thay đổi nhiệt độ của dung dịch và trả lời câu hỏi:",
    "[Hình ảnh thí nghiệm đo sự thay đổi nhiệt độ phản ứng trung hoà]",
    "Hình 17.1. Theo dõi sự thay đổi nhiệt độ của phản ứng trung hoà",
    "1. Nhiệt độ trên nhiệt kế thay đổi như thế nào sau khi rót dung dịch NaOH vào cốc? Phản ứng trung hoà là phản ứng toả nhiệt hay thu nhiệt?",
    "2. Trong thí nghiệm trên, nếu thay các dung dịch HCl và NaOH bằng các dung dịch loãng hơn thì nhiệt độ thay đổi như thế nào so với thí nghiệm trên?",
    "",
    "EM CÓ BIẾT",
    "Sự đốt cháy các loại nhiên liệu như xăng, dầu, cồn, khí gas,... xảy ra nhanh, toả nhiều nhiệt, dễ gây hoả hoạn, thậm chí gây nổ mạnh, rất khó kiểm soát. Vì vậy, khi sử dụng chúng cần tuân thủ nghiêm ngặt các nguyên tắc phòng cháy.",
    "",
    "II BIẾN THIÊN ENTHALPY CỦA PHẢN ỨNG",
    "1. Biến thiên enthalpy",
    "Hầu hết các quá trình hoá học trong thực tế xảy ra ở điều kiện áp suất không đổi. Nhiệt lượng toả ra hay thu vào của phản ứng ở điều kiện này gọi là biến thiên enthalpy của phản ứng (nhiệt phản ứng), kí hiệu là $\\Delta_{\\text{r}}\\text{H}^{(*)}$.",
    "Phương trình hoá học kèm theo trạng thái của các chất và giá trị $\\Delta_{\\text{r}}\\text{H}$ gọi là phương trình nhiệt hoá học.",
    "Ví dụ 1: Phản ứng đốt cháy 2 mol khí hydrogen bằng 1 mol khí oxygen, tạo thành 2 mol nước ở trạng thái lỏng, toả ra nhiệt lượng 571,6 kJ. Phản ứng trên có biến thiên enthalpy $\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = –571,6 kJ, biểu diễn bằng phương trình nhiệt hoá học như sau:",
    "2H$_2$(g) + O$_2$(g) $\\longrightarrow$ 2H$_2$O(l)      $\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = –571,6 kJ",
    "",
    "$^{(*)}$ $\\Delta_{\\text{r}}\\text{H}$ là biến thiên enthalpy của phản ứng (nhiệt phản ứng). Chữ \"r\" là viết tắt của từ tiếng Anh reaction, nghĩa là phản ứng.",
    "",
    "82",
    "",
    "Ví dụ 2: Phản ứng nhiệt phân hoàn toàn 1 mol Cu(OH)$_2$, tạo thành 1 mol CuO và 1 mol H$_2$O, thu vào nhiệt lượng 9,0 kJ. Phản ứng trên có biến thiên enthalpy $\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = +9,0 kJ và biểu diễn bằng phương trình nhiệt hoá học như sau:",
    "Cu(OH)$_2$(s) $\\xrightarrow{t^\\circ}$ CuO(s) + H$_2$O(l)      $\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = +9,0 kJ",
    "",
    "2. Biến thiên enthalpy chuẩn",
    "Biến thiên enthalpy của các phản ứng phụ thuộc vào điều kiện xảy ra phản ứng (như nhiệt độ, áp suất) và trạng thái vật lí của các chất. Để so sánh biến thiên enthalpy của các phản ứng khác nhau thì cần xác định chúng ở cùng một điều kiện. Biến thiên enthalpy chuẩn là nhiệt toả ra hay thu vào của phản ứng được xác định ở điều kiện chuẩn: áp suất 1 bar (đối với chất khí), nồng độ 1 mol/L (đối với chất tan trong dung dịch) và nhiệt độ thường được chọn là 25 $^\\circ$C (298 K), kí hiệu $\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$.",
    "Ví dụ: Phản ứng đốt cháy hoàn toàn 1 mol carbon graphite trong khí oxygen dư (ở điều kiện chuẩn) tạo ra 1 mol CO$_2$, nhiệt lượng toả ra là 393,5 kJ. Phương trình nhiệt hoá học của phản ứng được viết như sau:",
    "C(graphite) + O$_2$(g) $\\xrightarrow{t^\\circ}$ CO$_2$(g)      $\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = –393,5 kJ",
    "",
    "3. Ý nghĩa của biến thiên enthalpy",
    "Dấu của biến thiên enthalpy cho biết phản ứng toả nhiệt hay thu nhiệt:",
    "$\\Delta_{\\text{r}}\\text{H}$ > 0: phản ứng thu nhiệt.",
    "$\\Delta_{\\text{r}}\\text{H}$ < 0: phản ứng toả nhiệt.",
    "Giá trị tuyệt đối của biến thiên enthalpy càng lớn thì nhiệt lượng toả ra hay thu vào của phản ứng càng nhiều.",
    "Ví dụ: Xét 2 phản ứng",
    "CH$_4$(g) + 2O$_2$(g) $\\xrightarrow{t^\\circ}$ CO$_2$(g) + 2H$_2$O(l)      $\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = –890 kJ / mol",
    "CH$_3$OH(l) + $\\frac{3}{2}$O$_2$(g) $\\xrightarrow{t^\\circ}$ CO$_2$(g) + 2H$_2$O(l)      $\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = –726 kJ / mol",
    "Vậy, khi đốt 1 mol methane (16 g) toả ra nhiệt lượng nhiều hơn đốt 1 mol methanol (32 g).",
    "Các phản ứng xảy ra ở nhiệt độ phòng thường là phản ứng toả nhiệt, các phản ứng thu nhiệt thường xảy ra khi đun nóng.",
    "",
    "❓",
    "2. Cho các phương trình nhiệt hoá học:",
    "(1) CaCO$_3$(s) $\\longrightarrow$ CaO(s) + CO$_2$(g)      $\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = +176,0 kJ",
    "(2) C$_2$H$_4$(g) + H$_2$(g) $\\longrightarrow$ C$_2$H$_6$(g)      $\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = –137,0 kJ",
    "(3) Fe$_2$O$_3$(s) + 2Al(s) $\\longrightarrow$ Al$_2$O$_3$(s) + 2Fe(s)      $\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = –851,5 kJ",
    "Trong các phản ứng trên, phản ứng nào toả nhiệt, phản ứng nào thu nhiệt?",
    "3. Biết phản ứng đốt cháy khí carbon monoxide (CO) như sau:",
    "CO(g) + $\\frac{1}{2}$O$_2$(g) $\\longrightarrow$ CO$_2$(g)      $\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = –283,0 kJ",
    "",
    "83",
    "",
    "Ở điều kiện chuẩn, nếu đốt cháy hoàn toàn 2,479 L khí CO thì nhiệt lượng toả ra là bao nhiêu?",
    "4. Phản ứng tôi vôi toả ra nhiệt lượng rất lớn, có thể làm sôi nước. Hãy nêu các biện pháp để đảm bảo an toàn khi thực hiện quá trình tôi vôi.",
    "",
    "EM CÓ BIẾT",
    "Trên các vỏ hộp thực phẩm thường ghi giá trị năng lượng – đó là năng lượng do một lượng thực phẩm nhất định cung cấp khi chuyển hoá hoàn toàn trong cơ thể.",
    "[Hình ảnh bảng giá trị dinh dưỡng trên vỏ hộp thực phẩm]",
    "",
    "III TÍNH BIẾN THIÊN ENTHALPY CỦA PHẢN ỨNG THEO NHIỆT TẠO THÀNH",
    "1. Khái niệm nhiệt tạo thành",
    "Nhiệt tạo thành ($\\Delta_{\\text{f}}\\text{H}$)$^{(*)}$ của một chất là biến thiên enthalpy của phản ứng tạo thành 1 mol chất đó từ các đơn chất ở dạng bền vững nhất, ở một điều kiện xác định.",
    "Nhiệt tạo thành chuẩn ($\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$) là nhiệt tạo thành ở điều kiện chuẩn.",
    "Nhiệt tạo thành chuẩn của các đơn chất ở dạng bền vững nhất bằng không, ví dụ:",
    "$\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$(O$_2$ (g)) = 0 kJ/mol.",
    "",
    "Ví dụ 1: Nước lỏng được tạo thành từ khí hydrogen và khí oxygen theo phản ứng:",
    "H$_2$(g) + $\\frac{1}{2}$O$_2$(g) $\\longrightarrow$ H$_2$O(l)",
    "Ở điều kiện chuẩn, cứ 1 mol H$_2$O(l) tạo thành từ 1 mol H$_2$(g) và $\\frac{1}{2}$ mol O$_2$(g) giải phóng nhiệt lượng là 285,8 kJ.",
    "Như vậy nhiệt tạo thành của nước lỏng:",
    "$\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$(H$_2$O(l)) = –285,8 kJ/mol.",
    "",
    "Ví dụ 2: Phản ứng $\\frac{1}{2}$N$_2$(g) + $\\frac{1}{2}$O$_2$(g) $\\longrightarrow$ NO(g)",
    "có biến thiên enthalpy: $\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$(NO(g))= +90,3 kJ/mol. Giá trị $\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$ > 0, tức phản ứng này là phản ứng thu nhiệt.",
    "",
    "$^{(*)}$ $\\Delta_{\\text{f}}\\text{H}$ là nhiệt tạo thành (chữ f viết tắt của từ tiếng Anh “formation”, nghĩa là tạo thành).",
    "",
    "84",
    "",
    "Bảng 17.1. Nhiệt tạo thành chuẩn của một số chất thường gặp$^{(*)}$",
    "",
    "| Chất | $\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$ (kJ/mol) | Chất | $\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$ (kJ/mol) |",
    "|---|---|---|---|",
    "| AgCl(s) | –127,0 | HCl(g) | –92,3 |",
    "| BaCl$_2$(s) | –806,1 | HI(g) | +25,9 |",
    "| BaSO$_4$(s) | –1 465,0 | H$_2$O(l) | –285,8 |",
    "| CaCl$_2$(s) | –795,0 | H$_2$O(g) | –241,8 |",
    "| CaCO$_3$(s) | –1 206,9 | KCl(s) | –436,7 |",
    "| CaO(s) | –635,1 | KOH(s) | –424,8 |",
    "| CH$_4$(g) | –74,9 | Fe$_2$O$_3$(s) | –825,5 |",
    "| C$_2$H$_6$(g) | –84,7 | NaCl(s) | –411,1 |",
    "| C$_2$H$_2$(g) | +227,0 | NaOH(s) | –425,6 |",
    "| CO(g) | –110,5 | NH$_3$(g) | –45,9 |",
    "| CO$_2$(g) | –393,5 | O$_3$(g) | +143,0 |",
    "| Ca(OH)$_2$(s) | –986,1 | SO$_2$(g) | –296,8 |",
    "| HBr(g) | –36,3 | SO$_3$(l) | –441,0 |",
    "",
    "2. Tính biến thiên enthalpy của phản ứng theo nhiệt tạo thành",
    "Biến thiên enthalpy của phản ứng được xác định bằng hiệu số giữa tổng nhiệt tạo thành các chất sản phẩm (sp) và tổng nhiệt tạo thành của các chất đầu (cđ).",
    "Ở điều kiện chuẩn:",
    "$\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = $\\sum\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$(sp) – $\\sum\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$(cđ)",
    "Trong tính toán cần lưu ý đến hệ số của các chất trong phương trình hoá học.",
    "Ví dụ 1: Xác định biến thiên enthalpy của phản ứng sau ở điều kiện chuẩn:",
    "SO$_2$(g) + $\\frac{1}{2}$O$_2$(g) $\\longrightarrow$ SO$_3$(l)",
    "biết nhiệt tạo thành $\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$ của SO$_2$(g) là –296,8 kJ/ mol, của SO$_3$(l) là –441,0 kJ/mol.",
    "Lời giải:",
    "$\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = $\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$(SO$_3$(l)) – [$\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$(SO$_2$(g)) + $\\frac{1}{2}$ $\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$(O$_2$(g))]",
    "= –441,0 – (–296,8 + 0 $\\cdot$ $\\frac{1}{2}$) = –144,2 (kJ).",
    "",
    "$^{(*)}$ Nguồn: Silberberg, Martin. (2018). Chemistry: the molecular nature of matter and change with advanced topics. McGraw-Hill Education.",
    "",
    "85",
    "",
    "Ví dụ 2: Xác định biến thiên enthalpy của phản ứng sau ở điều kiện chuẩn:",
    "4FeS$_2$(s) + 11O$_2$(g) $\\longrightarrow$ 2Fe$_2$O$_3$(s) + 8SO$_2$(g)",
    "biết nhiệt tạo thành $\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$ của các chất FeS$_2$(s), Fe$_2$O$_3$(s) và SO$_2$(g) lần lượt là –177,9 kJ/mol, –825,5 kJ/mol và –296,8 kJ/mol.",
    "Lời giải:",
    "Tổng nhiệt tạo thành các chất đầu là:",
    "$\\sum\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$(cđ) = $\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$(FeS$_2$(s)) $\\cdot$ 4 + $\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$(O$_2$(g)) $\\cdot$ 11 = (–177,9) $\\cdot$ 4 + 0 $\\cdot$ 11 = –711,6 (kJ)",
    "Tổng nhiệt tạo thành các chất sản phẩm là:",
    "$\\sum\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$(sp) = $\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$(Fe$_2$O$_3$(s)) $\\cdot$ 2 + $\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$(SO$_2$(g)) $\\cdot$ 8 = (–825,5) $\\cdot$ 2 + (–296,8) $\\cdot$ 8 = –4 025,4 (kJ)",
    "Vậy, biến thiên enthalpy của phản ứng:",
    "$\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = $\\sum\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$(sp) – $\\sum\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$(cđ) = –4 025,4 – (–711,6) = –3 313,8 (kJ)",
    "",
    "EM CÓ BIẾT",
    "Từ các nghiên cứu thực nghiệm, năm 1840, nhà hoá học người Thuỵ Sĩ là G. Hess (He-xơ) đã đề xuất một định luật về sau mang tên ông, trong đó nói rằng những sự thay đổi năng lượng trong một quá trình hoá học chỉ phụ thuộc vào trạng thái của các chất ban đầu và sản phẩm mà không phụ thuộc vào cách phản ứng xảy ra và các sản phẩm trung gian.",
    "Dựa vào định luật Hess, các nhà khoa học đã thu thập các số liệu thực nghiệm của các phản ứng cơ bản như nhiệt tạo thành, nhiệt cháy, năng lượng liên kết,... đưa vào các tài liệu tra cứu. Từ các số liệu thực nghiệm này, ta có thể tính được các đại lượng của các phản ứng khác mà không cần tiến hành thí nghiệm.",
    "",
    "❓",
    "5. Cho phản ứng:",
    "C(kim cương) $\\longrightarrow$ C(graphite)      $\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = –1,9 kJ",
    "a) Ở điều kiện chuẩn, kim cương hay graphite có mức năng lượng thấp hơn?",
    "b) Trong phản ứng xác định nhiệt tạo thành của CO$_2$(g): C(s) + O$_2$(g) $\\longrightarrow$ CO$_2$(g), carbon ở dạng kim cương hay graphite?",
    "6. Từ số liệu Bảng 17.1, hãy xác định biến thiên enthalpy chuẩn của phản ứng đốt cháy ethane:",
    "C$_2$H$_6$(g) + $\\frac{7}{2}$O$_2$(g) $\\xrightarrow{t^\\circ}$ 2CO$_2$(g) + 3H$_2$O(l)",
    "",
    "IV TÍNH BIẾN THIÊN ENTHALPY CỦA PHẢN ỨNG THEO NĂNG LƯỢNG LIÊN KẾT",
    "Phản ứng hoá học là quá trình phá vỡ các liên kết trong chất đầu và hình thành các liên kết mới để tạo thành sản phẩm. Sự phá vỡ liên kết cần cung cấp năng lượng, trong khi sự hình thành liên kết lại giải phóng năng lượng. Biến thiên enthalpy của phản ứng (mà các chất đều ở thể khí), bằng hiệu số giữa tổng năng lượng liên kết của các",
    "",
    "86",
    "",
    "chất đầu và tổng năng lượng liên kết của các sản phẩm (ở cùng điều kiện nhiệt độ và áp suất).",
    "Ở điều kiện chuẩn:",
    "$\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = $\\sum\\text{E}_\\text{b}$(cđ) – $\\sum\\text{E}_\\text{b}$(sp)",
    "Ví dụ 1: Tính biến thiên enthalpy chuẩn của phản ứng",
    "H$_2$(g) + Cl$_2$(g) $\\longrightarrow$ 2HCl(g)",
    "biết E$_\\text{b}$ (H–H) = 436 kJ/mol, E$_\\text{b}$ (Cl–Cl) = 243 kJ/mol, E$_\\text{b}$ (H–Cl) = 432 kJ/mol.",
    "Lời giải:",
    "Biến thiên enthalpy chuẩn của phản ứng là:",
    "$\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = E$_\\text{b}$(H–H) + E$_\\text{b}$(Cl–Cl) – 2 $\\cdot$ E$_\\text{b}$(H–Cl) = 436 + 243 – 2 $\\cdot$ 432 = –185 (kJ)",
    "Phản ứng toả nhiệt vì khi tạo thành 2 liên kết H–Cl toả ra năng lượng lớn hơn năng lượng cần thiết để phá vỡ liên kết H–H và Cl–Cl.",
    "Ví dụ 2: Xác định biến thiên enthalpy chuẩn của phản ứng",
    "C$_2$H$_4$(g) + H$_2$(g) $\\longrightarrow$ C$_2$H$_6$(g)",
    "biết năng lượng liên kết (ở điều kiện chuẩn):",
    "",
    "| Liên kết | H–H | C–H | C–C | C=C |",
    "|---|---|---|---|---|",
    "| Phân tử | hydrogen | hydrocarbon | alkane | alkene |",
    "| E$_\\text{b}$ (kJ/mol) | 436 | 418 | 346 | 612 |",
    "",
    "Lời giải:",
    "H    H                      H    H",
    "|     |                       |     |",
    "H–C=C–H + H–H $\\longrightarrow$ H–C–C–H",
    "|     |",
    "H   H",
    "$\\Rightarrow$ $\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = E$_\\text{b}$(C=C) + 4E$_\\text{b}$(C–H) + E$_\\text{b}$(H–H) – E$_\\text{b}$(C–C) – 6E$_\\text{b}$(C–H)",
    "= 612 + 4 $\\cdot$ 418 + 436 – 346 – 6 $\\cdot$ 418 = –134 (kJ)",
    "",
    "EM CÓ BIẾT",
    "Xác định biến thiên enthalpy bằng thực nghiệm",
    "Biến thiên enthalpy của phản ứng có thể xác định bằng nhiệt lượng kế (Hình 17.2). Dựa vào kết quả khi xác định sự thay đổi nhiệt độ của nước sẽ tính được nhiệt lượng đã cho đi (hoặc nhận vào), từ đó xác định được biến thiên enthalpy của phản ứng.",
    "[Hình ảnh mô hình nhiệt lượng kế]",
    "Hình 17.2. Một mô hình nhiệt lượng kế",
    "",
    "87",
    "",
    "❓",
    "7. ",
    "a) Cho biết năng lượng liên kết trong các phân tử O$_2$, N$_2$ và NO lần lượt là 494 kJ/mol, 945 kJ/mol và 607 kJ/mol. Tính biến thiên enthalpy chuẩn của phản ứng:",
    "N$_2$(g) + O$_2$(g) $\\longrightarrow$ 2NO(g)",
    "b) Giải thích vì sao nitrogen chỉ phản ứng với oxygen ở nhiệt độ cao hoặc khi có tia lửa điện.",
    "8. Từ số liệu năng lượng liên kết ở Bảng 12.2, hãy tính biến thiên enthalpy của phản ứng đốt cháy butane theo năng lượng liên kết, biết sản phẩm phản ứng đều ở thể khí.",
    "",
    "EM ĐÃ HỌC",
    "• Phản ứng toả nhiệt là phản ứng khi xảy ra kèm theo sự truyền nhiệt từ chất phản ứng ra môi trường.",
    "• Phản ứng thu nhiệt là phản ứng khi xảy ra kèm theo sự truyền nhiệt từ môi trường vào chất phản ứng.",
    "• Biến thiên enthalpy của phản ứng là nhiệt lượng toả ra hay thu vào của phản ứng ở một điều kiện xác định.",
    "• Biểu thức tính biến thiên enthalpy của các phản ứng ở điều kiện chuẩn:",
    "– Theo nhiệt tạo thành:",
    "$\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = $\\sum\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$(sp) – $\\sum\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$(cđ).",
    "– Theo năng lượng liên kết (các chất đều ở thể khí)",
    "$\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = $\\sum\\text{E}_\\text{b}$(cđ) – $\\sum\\text{E}_\\text{b}$(sp)",
    "",
    "EM CÓ THỂ",
    "• Nhận biết được một phản ứng là toả nhiệt hay thu nhiệt.",
    "• Tính được biến thiên enthalpy của một số phản ứng khi biết nhiệt tạo thành hoặc năng lượng liên kết của các chất.",
    "",
    "88"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_5' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'BAI_18', 'ÔN TẬP CHƯƠNG 5', 89, 18, $JSON$
{
  "content": [
    "BÀI 18 ÔN TẬP CHƯƠNG 5",
    "",
    "I HỆ THỐNG HOÁ KIẾN THỨC",
    "Hoàn thành các nội dung còn thiếu sau đây:",
    "Chất phản ứng $\\longrightarrow$ Sản phẩm, $\\Delta_{\\text{r}}\\text{H}$ > 0 (phản ứng ...?... nhiệt)",
    "                                               $\\Delta_{\\text{r}}\\text{H}$ < 0 (phản ứng ...?... nhiệt)",
    "",
    "Tính biến thiên enthalpy của phản ứng theo nhiệt tạo thành (ở điều kiện chuẩn):",
    "$\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = ....................................?....................................",
    "",
    "Tính biến thiên enthalpy của phản ứng (mà các chất đều ở thể khí) theo năng lượng liên kết (ở điều kiện chuẩn):",
    "$\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = ....................................?....................................",
    "",
    "II LUYỆN TẬP",
    "Câu 1. Phản ứng chuyển hoá giữa hai dạng đơn chất của phosphorus (P):",
    "P (s, đỏ) $\\longrightarrow$ P (s, trắng)      $\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = 17,6 kJ",
    "Điều này chứng tỏ phản ứng:",
    "A. thu nhiệt, P đỏ bền hơn P trắng.",
    "B. thu nhiệt, P trắng bền hơn P đỏ.",
    "C. toả nhiệt, P đỏ bền hơn P trắng.",
    "D. toả nhiệt, P trắng bền hơn P đỏ.",
    "",
    "Câu 2. Cho biết biến thiên enthalpy của phản ứng sau ở điều kiện chuẩn:",
    "CO(g) + $\\frac{1}{2}$O$_2$(g) $\\longrightarrow$ CO$_2$(g)      $\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = –283,0 kJ",
    "Biết nhiệt tạo thành chuẩn của CO$_2$: $\\Delta_{\\text{f}}\\text{H}_{298}^\\circ$(CO$_2$(g)) = –393,5 kJ/mol.",
    "Nhiệt tạo thành chuẩn của CO là",
    "A. –110,5 kJ/mol.      B. +110,5 kJ/mol.      C. –141,5 kJ/mol.      D. –221,0 kJ/mol.",
    "",
    "Câu 3. Dung dịch glucose (C$_6$H$_{12}$O$_6$) 5%, có khối lượng riêng là 1,02 g/mL, phản ứng oxi hoá 1 mol glucose tạo thành CO$_2$(g) và H$_2$O(l) toả ra nhiệt lượng là 2 803,0 kJ.",
    "Một người bệnh được truyền một chai chứa 500 mL dung dịch glucose 5%. Năng lượng tối đa từ phản ứng oxi hoá hoàn toàn glucose mà bệnh nhân đó có thể nhận được là",
    "A. +397,09 kJ.      B. +381,67 kJ.      C. +389,30 kJ.      D. +416,02 kJ.",
    "",
    "89",
    "",
    "Câu 4. Cho giá trị trung bình của các năng lượng liên kết ở điều kiện chuẩn:",
    "| Liên kết | C–H | C–C | C=C |",
    "|---|---|---|---|",
    "| E$_\\text{b}$ (kJ/mol) | 418 | 346 | 612 |",
    "Biến thiên enthalpy của phản ứng C$_3$H$_8$(g) $\\longrightarrow$ CH$_4$(g) + C$_2$H$_4$(g) có giá trị là",
    "A. +103 kJ.      B. –103 kJ.      C. +80 kJ.      D. –80 kJ.",
    "",
    "Câu 5. Methane là thành phần chính của khí thiên nhiên. Xét phản ứng đốt cháy methane:",
    "CH$_4$(g) + 2O$_2$(g) $\\longrightarrow$ CO$_2$(g) + 2H$_2$O(l)      $\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = –890,3 kJ",
    "Biết nhiệt tạo thành chuẩn của CO$_2$(g) và H$_2$O(l) tương ứng là –393,5 và –285,8 kJ/mol. Hãy tính nhiệt tạo thành chuẩn của khí methane.",
    "",
    "Câu 6. So sánh nhiệt toả ra khi đốt cháy hoàn toàn 1 kg cồn (C$_2$H$_5$OH) và 1 kg tristearin (C$_{57}$H$_{110}$O$_6$, có trong mỡ lợn). Cho biết:",
    "C$_2$H$_5$OH(l) + 3O$_2$(g) $\\longrightarrow$ 2CO$_2$(g) + 3H$_2$O(l)      $\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = –1 365 kJ",
    "C$_{57}$H$_{110}$O$_6$(s) + $\\frac{163}{2}$O$_2$(g) $\\longrightarrow$ 57CO$_2$(g) + 55H$_2$O(l)      $\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = –35 807 kJ",
    "",
    "Câu 7. Biết CH$_3$COCH$_3$ có công thức cấu tạo:",
    "H      H",
    "|       |",
    "H–C–C–C–H",
    "|   ||   |",
    "H  O  H",
    "Từ số liệu năng lượng liên kết ở Bảng 12.2, hãy xác định biến thiên enthalpy của phản ứng đốt cháy acetone (CH$_3$COCH$_3$):",
    "CH$_3$COCH$_3$(g) + 4O$_2$(g) $\\longrightarrow$ 3CO$_2$(g) + 3H$_2$O(g)",
    "",
    "Câu 8. Một bình gas (khí hoá lỏng) chứa hỗn hợp propane và butane với tỉ lệ số mol 1 : 2. Xác định nhiệt lượng toả ra khi đốt cháy hoàn toàn 12 kg khí gas trên ở điều kiện chuẩn. Cho biết:",
    "C$_3$H$_8$(g) + 5O$_2$(g) $\\longrightarrow$ 3CO$_2$(g) + 4H$_2$O(l)      $\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = –2 220 kJ",
    "C$_4$H$_{10}$(g) + $\\frac{13}{2}$O$_2$(g) $\\longrightarrow$ 4CO$_2$(g) + 5H$_2$O(l)      $\\Delta_{\\text{r}}\\text{H}_{298}^\\circ$ = –2 874 kJ",
    "Trung bình mỗi ngày, một hộ gia đình cần đốt gas để cung cấp 10 000 kJ nhiệt (hiệu suất hấp thụ nhiệt là 80%). Sau bao nhiêu ngày hộ gia đình trên sẽ sử dụng hết bình gas 12 kg?",
    "",
    "90"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_6' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'BAI_19', 'TỐC ĐỘ PHẢN ỨNG', 92, 19, $JSON$
{
  "content": [
    "BÀI 19 TỐC ĐỘ PHẢN ỨNG",
    "",
    "MỤC TIÊU:",
    "– Trình bày được khái niệm tốc độ phản ứng hoá học và cách tính tốc độ trung bình của phản ứng.",
    "– Viết được biểu thức tốc độ phản ứng theo hằng số tốc độ phản ứng và nồng độ (còn gọi là định luật tác dụng khối lượng, chỉ đúng cho phản ứng đơn giản nên không tuỳ ý áp dụng cho mọi phản ứng). Từ đó nêu được ý nghĩa hằng số tốc độ phản ứng.",
    "– Thực hiện được một số thí nghiệm nghiên cứu và giải thích được các yếu tố ảnh hưởng tới tốc độ phản ứng (nồng độ, nhiệt độ, áp suất, diện tích bề mặt, chất xúc tác).",
    "– Nêu được ý nghĩa của hệ số nhiệt độ Van’t Hoff.",
    "– Vận dụng được kiến thức tốc độ phản ứng hoá học vào việc giải thích một số vấn đề trong cuộc sống và sản xuất.",
    "",
    "❓ Làm thế nào có thể so sánh sự nhanh, chậm của các phản ứng hoá học để thúc đẩy hoặc kìm hãm nó theo mong muốn?",
    "",
    "I TỐC ĐỘ PHẢN ỨNG HOÁ HỌC",
    "1. Khái niệm tốc độ phản ứng hoá học",
    "Khi phản ứng hoá học xảy ra, lượng chất đầu giảm dần theo thời gian, trong khi lượng chất sản phẩm tăng dần theo thời gian (Hình 19.1).",
    "Tốc độ phản ứng được xác định bằng sự thay đổi lượng chất đầu hoặc chất sản phẩm trong một đơn vị thời gian: giây (s), phút (min), giờ (h), ngày (d),... Lượng chất có thể được biểu diễn bằng số mol, nồng độ mol, khối lượng, hoặc thể tích.",
    "[Đồ thị sự thay đổi lượng chất theo thời gian]",
    "Hình 19.1. Sự thay đổi lượng chất theo thời gian",
    "",
    "Các phản ứng khác nhau xảy ra với tốc độ khác nhau, có phản ứng xảy ra nhanh, có phản ứng xảy ra chậm (Hình 19.2).",
    "[Hình ảnh 19.2 a, b, c]",
    "a)                                           b)                                           c)",
    "Hình 19.2. Phản ứng xảy ra nhanh: a) Than cháy; Phản ứng xảy ra chậm: b) Sắt bị gỉ, c) Tinh bột lên men rượu",
