    "92",
    "",
    "❓ 1. Xét phản ứng: H$_2$ + Cl$_2$ $\\longrightarrow$ 2HCl.",
    "Nghiên cứu sự thay đổi nồng độ một chất trong phản ứng theo thời gian, thu được đồ thị sau:",
    "[Đồ thị sự thay đổi nồng độ theo thời gian]",
    "a) Đồ thị này mô tả sự thay đổi nồng độ theo thời gian của chất nào?",
    "b) Nêu đơn vị của tốc độ phản ứng trong trường hợp này.",
    "",
    "2. Tốc độ trung bình của phản ứng",
    "Phản ứng phân huỷ H$_2$O$_2$:",
    "H$_2$O$_2$ $\\longrightarrow$ H$_2$O + $\\frac{1}{2}$O$_2$",
    "Kết quả thí nghiệm đo nồng độ H$_2$O$_2$ tại các thời điểm khác nhau được trình bày trên Bảng 19.1.",
    "Bảng 19.1. Kết quả thí nghiệm phân huỷ H$_2$O$_2$",
    "| Thời gian phản ứng (h) | 0 | 3 | 6 | 9 | 12 |",
    "|---|---|---|---|---|---|",
    "| Nồng độ H$_2$O$_2$ (mol/L) | 1,000 | 0,707 | 0,500 | 0,354 | 0,250 |",
    "",
    "Biến thiên nồng độ trong khoảng thời gian từ 0 giờ đến 3 giờ là:",
    "0,707 – 1,000 = – 0,293 (mol/L)",
    "(Dấu \"–\" thể hiện rằng nồng độ H$_2$O$_2$ giảm dần khi phản ứng xảy ra).",
    "Tốc độ phản ứng trong khoảng thời gian từ 0 giờ đến 3 giờ được tính như sau:",
    "$\\text{v}_\\text{tb} = -\\frac{\\text{C}_{\\text{H}_2\\text{O}_2\\text{ (3h)}} - \\text{C}_{\\text{H}_2\\text{O}_2\\text{ (0h)}}}{3 - 0} = -\\frac{0,707 - 1,000}{3} \\approx 0,098 \\text{ (mol / (L }\\cdot\\text{ h))}$",
    "(Đặt dấu \"–\" trước biểu thức để tốc độ phản ứng có giá trị dương.)",
    "",
    "93",
    "",
    "Thực hiện các yêu cầu sau:",
    "1. Hãy tính tốc độ phản ứng theo nồng độ H$_2$O$_2$ trong các khoảng thời gian từ:",
    "a) 3 giờ đến 6 giờ;",
    "b) 6 giờ đến 9 giờ;",
    "c) 9 giờ đến 12 giờ.",
    "2. Nhận xét về sự thay đổi tốc độ phản ứng theo thời gian.",
    "",
    "Đa số các phản ứng hoá học có tốc độ giảm dần theo thời gian. Để đặc trưng cho sự nhanh chậm của phản ứng trong một khoảng thời gian, ta dùng tốc độ phản ứng trung bình.",
    "Ví dụ: Xét phản ứng",
    "2CO + O$_2$ $\\longrightarrow$ 2CO$_2$",
    "Tại thời điểm t$_1$, nồng độ CO, O$_2$, CO$_2$ lần lượt là C$_\\text{CO}$(1), C$_{\\text{O}_2}$(1), C$_{\\text{CO}_2}$(1).",
    "Tại thời điểm t$_2$, nồng độ CO, O$_2$, CO$_2$ lần lượt là C$_\\text{CO}$(2), C$_{\\text{O}_2}$(2), C$_{\\text{CO}_2}$(2).",
    "Vậy, trong khoảng thời gian $\\Delta$t = t$_2$ – t$_1$, biến thiên nồng độ các chất là:",
    "$\\Delta$C$_\\text{CO}$ = C$_\\text{CO}$(2) – C$_\\text{CO}$(1)",
    "$\\Delta$C$_{\\text{O}_2}$ = C$_{\\text{O}_2}$(2) – C$_{\\text{O}_2}$(1)",
    "$\\Delta$C$_{\\text{CO}_2}$ = C$_{\\text{CO}_2}$(2) – C$_{\\text{CO}_2}$(1)",
    "",
    "EM CÓ BIẾT",
    "Sự thay đổi lượng chất trong khoảng thời gian vô cùng ngắn được gọi là tốc độ tức thời của phản ứng.",
    "",
    "Khi phản ứng xảy ra, theo thời gian, nồng độ CO và O$_2$ giảm, nồng độ CO$_2$ tăng, nên $\\Delta$C$_\\text{CO}$ và $\\Delta$C$_{\\text{O}_2}$ âm, $\\Delta$C$_{\\text{CO}_2}$ dương.",
    "Từ phương trình hoá học, cho thấy tỉ lệ: cứ 2 mol CO phản ứng với 1 mol O$_2$, sinh ra 2 mol CO$_2$. Vì vậy:",
    "$-\\frac{1}{2}\\Delta\\text{C}_\\text{CO} = -\\Delta\\text{C}_{\\text{O}_2} = \\frac{1}{2}\\Delta\\text{C}_{\\text{CO}_2}$",
    "Tốc độ trung bình của phản ứng được tính theo biểu thức:",
    "$\\text{v}_\\text{tb} = -\\frac{1}{2}\\frac{\\Delta\\text{C}_\\text{CO}}{\\Delta\\text{t}} = -\\frac{\\Delta\\text{C}_{\\text{O}_2}}{\\Delta\\text{t}} = \\frac{1}{2}\\frac{\\Delta\\text{C}_{\\text{CO}_2}}{\\Delta\\text{t}}$",
    "",
    "Đối với phản ứng tổng quát: aA + bB $\\longrightarrow$ cC + dD",
    "Gọi $\\Delta$C$_\\text{A}$, $\\Delta$C$_\\text{B}$, $\\Delta$C$_\\text{C}$, $\\Delta$C$_\\text{D}$ lần lượt là biến thiên lượng chất các chất A, B, C, D trong khoảng thời gian $\\Delta$t. Tốc độ trung bình của phản ứng được tính theo biểu thức:",
    "$\\text{v}_\\text{tb} = -\\frac{1}{\\text{a}}\\frac{\\Delta\\text{C}_\\text{A}}{\\Delta\\text{t}} = -\\frac{1}{\\text{b}}\\frac{\\Delta\\text{C}_\\text{B}}{\\Delta\\text{t}} = \\frac{1}{\\text{c}}\\frac{\\Delta\\text{C}_\\text{C}}{\\Delta\\text{t}} = \\frac{1}{\\text{d}}\\frac{\\Delta\\text{C}_\\text{D}}{\\Delta\\text{t}}$",
    "",
    "❓ 2. Cho phản ứng của các chất ở thể khí:",
