    "Chuẩn bị: Các dung dịch: Na$_2$S$_2$O$_3$ 0,05 M; Na$_2$S$_2$O$_3$ 0,10 M; Na$_2$S$_2$O$_3$ 0,30 M; H$_2$SO$_4$ 0,50 M; 3 bình tam giác; đồng hồ bấm giờ; tờ giấy trắng có kẻ chữ X.",
