    "",
    "Quan sát vạch chữ X trên tờ giấy dưới đáy bình, ghi lại thời điểm không nhìn thấy vạch chữ X nữa và trả lời câu hỏi:",
    "1. Phản ứng ở bình nào xảy ra nhanh nhất? Chậm nhất?",
