    "EM CÓ BIẾT",
    "Quá trình chín của trái cây",
    "Khi các phản ứng hoá học chuyển hoá tinh bột thành đường xảy ra, trái cây sẽ chín. Khi thời tiết nóng lên, phản ứng xảy ra nhanh hơn nên trái cây chín nhanh hơn.",
    "",
    "Ví dụ: xét phản ứng của acetone với iodine.",
    "CH$_3$COCH$_3$ + I$_2$ $\\longrightarrow$ CH$_3$COCH$_2$I + HI",
    "Phản ứng có hệ số nhiệt độ $\\gamma$ trong khoảng từ 30 $^\\circ$C đến 50 $^\\circ$C là 2,5. Nếu ở 35 $^\\circ$C, phản ứng có tốc độ là 0,036 mol/(L.h) thì ở 45 $^\\circ$C, phản ứng có tốc độ là 0,036 $\\cdot$ 2,5 = 0,09 mol/(L.h).",
    "",
    "97",
    "",
    "❓ 6. Hãy giải thích tại sao khi nhiệt độ tăng thì tốc độ phản ứng tăng.",
    "7. Nêu ý nghĩa của hệ số nhiệt độ Van’t Hoff.",
    "8. Ở 20 $^\\circ$C, tốc độ một phản ứng là 0,05 mol/(L.min). Ở 30 $^\\circ$C, tốc độ phản ứng này là 0,15 mol/(L.min).",
    "a) Hãy tính hệ số nhiệt độ Van’t Hoff của phản ứng trên.",
    "b) Dự đoán tốc độ phản ứng trên ở 40 $^\\circ$C (giả thiết hệ số nhiệt độ $\\gamma$ trong khoảng nhiệt độ này không đổi).",
    "",
    "4. Ảnh hưởng của diện tích bề mặt đến tốc độ phản ứng",
    "Nghiên cứu ảnh hưởng của diện tích bề mặt đến tốc độ phản ứng:",
    "CaCO$_3$ + 2HCl $\\longrightarrow$ CaCl$_2$ + CO$_2$ + H$_2$O",
    "Chuẩn bị: 2 bình tam giác, dung dịch HCl 0,5 M, đá vôi dạng viên, đá vôi đập nhỏ.",
    "Tiến hành:",
    "• Cho cùng một lượng (khoảng 2 g) đá vôi dạng viên vào bình tam giác (1) và đá vôi đập nhỏ vào bình tam giác (2).",
    "• Rót 20 mL dung dịch HCl 0,5 M vào mỗi bình.",
    "Quan sát hiện tượng và thực hiện yêu cầu sau:",
    "1. Phản ứng trong bình nào có tốc độ thoát khí nhanh hơn?",
    "2. Đá vôi dạng nào có tổng diện tích bề mặt lớn hơn?",
    "3. Nêu ảnh hưởng của diện tích bề mặt tiếp xúc đến tốc độ phản ứng.",
    "",
    "Khi tăng diện tích bề mặt tiếp xúc, số va chạm giữa các chất đầu tăng lên, số va chạm hiệu quả cũng tăng theo, dẫn đến tốc độ phản ứng tăng.",
    "",
    "EM CÓ BIẾT",
    "Nếu kích thước hạt càng nhỏ thì tổng diện tích bề mặt càng lớn, nên có thể tăng diện tích tiếp xúc bằng cách đập nhỏ hạt.",
    "Ngoài ra, có thể tăng diện tích bề mặt của một khối chất bằng cách tạo nhiều đường rãnh, lỗ xốp trong lòng khối chất đó (tương tự như miếng bọt biển). Khi đó diện tích bề mặt bao gồm diện tích bề mặt trong và diện tích bề mặt ngoài.",
    "[Hình ảnh minh hoạ diện tích bề mặt]",
    "",
    "98",
    "",
    "5. Ảnh hưởng của chất xúc tác đến tốc độ phản ứng",
    "Nghiên cứu ảnh hưởng của chất xúc tác đến tốc độ phản ứng:",
    "2H$_2$O$_2$ $\\longrightarrow$ 2H$_2$O + O$_2$",
    "Chuẩn bị: 2 bình tam giác, dung dịch H$_2$O$_2$ 10%, MnO$_2$.",
    "Tiến hành:",
    "• Rót vào 2 bình tam giác, mỗi bình 20 mL dung dịch H$_2$O$_2$ 10%.",
    "• Thêm khoảng 0,1 g xúc tác MnO$_2$ vào một bình và lắc đều.",
    "Quan sát hiện tượng và thực hiện yêu cầu sau:",
    "1. So sánh tốc độ thoát khí ở hai bình.",
    "2. Chất xúc tác ảnh hưởng thế nào đến tốc độ phản ứng?",
    "",
    "Ảnh hưởng của xúc tác đến tốc độ phản ứng được giải thích dựa vào năng lượng hoạt hoá. Đây là năng lượng tối thiểu cần cung cấp cho các hạt (nguyên tử, phân tử hoặc ion) để va chạm giữa chúng gây ra phản ứng hoá học.",
    "Khi có xúc tác, phản ứng sẽ xảy ra qua nhiều giai đoạn. Mỗi giai đoạn đều có năng lượng hoạt hoá thấp hơn so với phản ứng không xúc tác (Hình 19.5). Do đó số hạt có đủ năng lượng hoạt hoá sẽ nhiều hơn, dẫn đến tốc độ phản ứng tăng lên.",
    "[Đồ thị năng lượng hoạt hoá của phản ứng]",
    "Hình 19.5. Năng lượng hoạt hoá của phản ứng khi không có xúc tác là A và khi có xúc tác với năng lượng hoạt hoá là B, C của các giai đoạn",
    "",
    "Sau phản ứng, khối lượng, bản chất hoá học của xúc tác không đổi, tuy nhiên, kích thước, hình dạng hạt, độ xốp,... có thể thay đổi.",
    "",
    "❓ 9. Thực hiện hai phản ứng phân huỷ H$_2$O$_2$: một phản ứng có xúc tác MnO$_2$, một phản ứng không xúc tác. Đo thể tích khí oxygen theo thời gian và biểu diễn trên đồ thị như hình bên:",
    "[Đồ thị tiến trình của phản ứng phân huỷ H2O2]",
    "Đường phản ứng nào trên đồ thị (Hình 19.6) tương ứng với phản ứng có xúc tác, với phản ứng không có xúc tác?",
    "Hình 19.6. Tiến trình của phản ứng phân huỷ H$_2$O$_2$",
    "",
    "99",
    "",
    "III MỘT SỐ ỨNG DỤNG CỦA VIỆC THAY ĐỔI TỐC ĐỘ PHẢN ỨNG",
    "Trong đời sống và trong sản xuất, con người áp dụng nhiều biện pháp kĩ thuật để thay đổi tốc độ phản ứng như thay đổi nồng độ, nhiệt độ, dùng chất xúc tác,... Ví dụ: Trong hàn xì, đốt acetylene bằng oxygen nguyên chất cháy nhanh và cho nhiệt độ cao hơn khi đốt bằng oxygen trong không khí.",
    "[Hình ảnh 19.7 a, b, c]",
    "a) Đèn xì oxygen – acetylene       b) Tủ lạnh bảo quản thức ăn       c) Bình dưa muối",
    "Hình 19.7. Một số ứng dụng thay đổi tốc độ phản ứng",
    "",
    "❓ 10. Yếu tố nào đã được áp dụng để làm thay đổi tốc độ của các phản ứng trong Hình 19.7?",
    "11. Phản ứng tạo NO từ NH$_3$ là một giai đoạn trung gian trong quá trình sản xuất nitric acid: 4NH$_3$(g) + 5O$_2$(g) $\\longrightarrow$ 4NO(g) + 6H$_2$O(g)",
    "Hãy nêu một số cách để tăng tốc độ phản ứng này.",
    "",
    "EM ĐÃ HỌC",
    "• Tốc độ phản ứng đặc trưng cho sự nhanh chậm của một phản ứng hoá học.",
    "• Tốc độ trung bình của phản ứng được tính bằng sự thay đổi lượng chất trong một đơn vị thời gian.",
    "• Khi nồng độ chất tan trong dung dịch tăng, tốc độ phản ứng tăng.",
    "• Đối với phản ứng có sự tham gia của chất khí, khi áp suất tăng, tốc độ phản ứng tăng.",
    "• Khi nhiệt độ phản ứng tăng dẫn đến số va chạm hiệu quả giữa các chất phản ứng tăng, làm tốc độ phản ứng tăng.",
    "• Để tăng tốc độ phản ứng ta có thể tăng diện tích bề mặt tiếp xúc của chất phản ứng bằng cách làm giảm kích thước hạt rắn hoặc tạo những hạt xốp.",
    "• Chất xúc tác làm tăng tốc độ phản ứng nhưng nó không bị biến đổi về lượng và chất sau phản ứng.",
    "",
    "EM CÓ THỂ",
    "Giải thích được tại sao nhiều phản ứng hoá học trong công nghiệp cần tiến hành ở nhiệt độ cao và sử dụng chất xúc tác.",
    "",
    "100"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_6' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'BAI_20', 'ÔN TẬP CHƯƠNG 6', 101, 20, $JSON$
{
  "content": [
    "BÀI 20 ÔN TẬP CHƯƠNG 6",
    "",
    "I HỆ THỐNG HOÁ KIẾN THỨC",
    "Hoàn thành các nội dung còn thiếu sau đây:",
    "Tốc độ phản ứng:",
    "Xét phản ứng hoá học dạng tổng quát: aA + bB $\\longrightarrow$ cC + dD.",
    "Biểu thức tốc độ trung bình của phản ứng: v$_\\text{tb}$ = ...?...",
    "Nếu phản ứng trên là một phản ứng đơn giản thì biểu thức tốc độ phản ứng theo hằng số tốc độ phản ứng: v = ...?...",
    "",
    "Các yếu tố ảnh hưởng đến tốc độ phản ứng",
    "[Sơ đồ tư duy]",
    "Các yếu tố ảnh hưởng đến tốc độ phản ứng $\\longrightarrow$",
    "...?... $\\longrightarrow$ Khi tăng các yếu tố này làm tăng số va chạm hiệu quả, dẫn đến tốc độ phản ứng tăng.",
    "...?... $\\longrightarrow$ Khi tăng các yếu tố này làm tăng số va chạm hiệu quả, dẫn đến tốc độ phản ứng tăng.",
    "...?... $\\longrightarrow$ Khi tăng các yếu tố này làm tăng số va chạm hiệu quả, dẫn đến tốc độ phản ứng tăng.",
    "...?... $\\longrightarrow$ Khi có chất này, năng lượng hoạt hoá giảm dẫn đến tốc độ phản ứng tăng.",
    "",
    "101",
    "",
    "II LUYỆN TẬP",
    "Câu 1. Hãy cho biết trong các phản ứng sau, phản ứng nào có tốc độ nhanh, phản ứng nào có tốc độ chậm?",
    "(a) Đốt cháy nhiên liệu.",
    "(b) Sắt bị gỉ.",
    "(c) Trung hoà acid – base.",
    "",
    "Câu 2. Cho khoảng 2 g zinc (kẽm) dạng hạt vào một cốc đựng dung dịch H$_2$SO$_4$ 2 M (dư) ở nhiệt độ phòng. Nếu chỉ biến đổi một trong các điều kiện sau đây (các điều kiện khác giữ nguyên) thì tốc độ phản ứng sẽ thay đổi thế nào (tăng lên, giảm xuống hay không đổi)?",
    "(a) Thay kẽm hạt bằng kẽm bột cùng khối lượng và khuấy đều.",
    "(b) Thay dung dịch H$_2$SO$_4$ 2 M bằng dung dịch H$_2$SO$_4$ 1 M có cùng thể tích.",
    "(c) Thực hiện phản ứng ở nhiệt độ cao hơn (khoảng 50 $^\\circ$C).",
    "",
    "Câu 3. Hydrogen peroxide phân huỷ theo phản ứng: 2H$_2$O$_2$ $\\longrightarrow$ 2H$_2$O + O$_2$.",
    "Đo thể tích oxygen thu được theo thời gian, kết quả được ghi trong bảng sau:",
    "| Thời gian (min) | 0 | 15 | 30 | 45 | 60 |",
    "|---|---|---|---|---|---|",
    "| Thể tích khí oxygen (cm$^3$) | 0 | 16 | 30 | 40 | 48 |",
    "",
    "a) Vẽ đồ thị mô tả sự phụ thuộc của thể tích khí oxygen theo thời gian.",
    "b) Tính tốc độ trung bình của phản ứng (theo cm$^3$/min) trong các khoảng thời gian:",
    "– Từ 0 $\\div$ 15 phút;",
    "– Từ 15 $\\div$ 30 phút;",
    "– Từ 30 $\\div$ 45 phút;",
    "– Từ 45 $\\div$ 60 phút.",
    "Nhận xét sự thay đổi tốc độ trung bình theo thời gian.",
    "",
    "Câu 4. Hãy thiết kế một thí nghiệm để chứng minh ảnh hưởng của nhiệt độ đến tốc độ phản ứng của zinc và sulfuric acid loãng.",
    "",
    "Câu 5. Một phản ứng ở 45 $^\\circ$C có tốc độ là 0,068 mol/(L$\\cdot$min). Hỏi phải giảm xuống nhiệt độ bao nhiêu để tốc độ phản ứng là 0,017 mol/(L$\\cdot$min). Giả sử, trong khoảng nhiệt độ thí nghiệm, hệ số nhiệt độ Van't Hoff của phản ứng bằng 2.",
    "",
    "102"
  ]
}
$JSON$) ON CONFLICT DO NOTHING;

INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_7' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'BAI_21', 'NHÓM HALOGEN', 104, 21, $JSON$
{
  "content": [
    "BÀI 21",
    "NHÓM HALOGEN",
    "",
    "MỤC TIÊU:",
    "– Nêu được trạng thái tự nhiên của các nguyên tố halogen.",
    "– Mô tả được trạng thái, màu sắc, nhiệt độ nóng chảy, nhiệt độ sôi của các đơn chất halogen.",
    "– Giải thích được sự biến đổi nhiệt độ nóng chảy, nhiệt độ sôi của các đơn chất halogen dựa vào tương tác van der Waals.",
    "– Trình bày được xu hướng các halogen nhận thêm 1 electron (từ kim loại) hoặc dùng chung electron (với phi kim) để tạo hợp chất ion hoặc hợp chất cộng hoá trị dựa theo cấu hình electron.",
    "– Giải thích được xu hướng phản ứng của các đơn chất halogen với hydrogen.",
    "– Viết được phương trình hoá học của phản ứng tự oxi hoá – khử của chlorine.",
    "– Thực hiện được (hoặc quan sát video) một số thí nghiệm chứng minh tính oxi hoá mạnh của các halogen và so sánh tính oxi hoá của các halogen trong nhóm VIIA.",
    "",
    "❓ Trong tự nhiên, một số phi kim như carbon, nitrogen, oxygen tồn tại ở cả dạng đơn chất và hợp chất, còn các halogen đều chỉ tồn tại ở dạng hợp chất. Vì sao có sự khác biệt này?",
    "",
    "I TRẠNG THÁI TỰ NHIÊN",
    "Nhóm VIIA trong bảng tuần hoàn các nguyên tố hoá học còn gọi là nhóm halogen, gồm sáu nguyên tố: fluorine (F), chlorine (Cl), bromine (Br), iodine (I), astatine (At) và tennessine (Ts). Bốn nguyên tố F, Cl, Br và I tồn tại trong tự nhiên, còn At và Ts là các nguyên tố phóng xạ.",
    "Trong tự nhiên, halogen chỉ tồn tại ở dạng hợp chất, phần lớn ở dạng muối halide, phổ biến như calcium fluoride, sodium chloride.",
    "Bảng 21.1. Nồng độ các ion halide trong nước biển$^{(*)}$",
    "| Ion halide | F$^-$ | Cl$^-$ | Br$^-$ | I$^-$ |",
    "|---|---|---|---|---|",
    "| Nồng độ (mg/kg) | 1 | 18 980 | 65 | 0,06 |",
    "",
    "Trong cơ thể người, nguyên tố chlorine có trong máu và dịch vị dạ dày (ở dạng ion Cl$^-$), nguyên tố iodine có ở tuyến giáp (ở dạng hợp chất hữu cơ).",
    "[Hình ảnh rong biển chứa nguyên tố iodine]",
    "Hình 21.1. Rong biển chứa nguyên tố iodine",
    "$^{(*)}$ Nguồn: John Wright, Angela Colling (2004). Seawater: Its Composition, Properties and Behaviour. The Open University.",
    "",
    "104",
    "",
    "EM CÓ BIẾT",
    "Muối mỏ",
    "Ngoài khai thác chủ yếu từ nước biển, muối ăn còn được khai thác từ mỏ muối. Muối mỏ có nhiều ứng dụng, ví dụ đá muối Himalaya (Hình 21.2) được sử dụng trong ẩm thực, chăm sóc sức khoẻ, sắc đẹp, trang trí nội thất,...",
    "[Hình ảnh đá muối Himalaya]",
    "Hình 21.2. Đá muối Himalaya",
    "",
    "❓ 1. Kể tên một số hợp chất phổ biến của halogen trong tự nhiên.",
    "",
    "II CẤU TẠO NGUYÊN TỬ, PHÂN TỬ",
    "1. Tra cứu số liệu Bảng 6.1, Bảng 6.2 và Hình 6.2 để hoàn thành bảng mô tả một số đặc điểm cấu tạo của các nguyên tử halogen theo mẫu sau:",
    "| Nguyên tử | Lớp electron ngoài cùng | Bán kính nguyên tử | Độ âm điện |",
    "|---|---|---|---|",
    "| Fluorine | ? | ? | ? |",
    "| Chlorine | ? | ? | ? |",
    "| Bromine | ? | ? | ? |",
    "| Iodine | ? | ? | ? |",
    "",
    "Từ bảng số liệu thu được, hãy:",
    "a) Giải thích tại sao nguyên tử halogen có xu hướng nhận 1 electron từ nguyên tử kim loại, hoặc góp chung 1 electron với nguyên tử phi kim, để hình thành liên kết.",
    "b) Nêu và giải thích xu hướng biến đổi bán kính nguyên tử, độ âm điện của các nguyên tử halogen. Từ đó dự đoán xu hướng biến đổi tính oxi hoá từ F đến I.",
    "c) Dựa vào cấu hình electron lớp ngoài cùng và độ âm điện, giải thích tại sao nguyên tử fluorine chỉ có số oxi hoá –1 trong các hợp chất?",
    "",
    "2. Tham khảo Bài 12 (Liên kết cộng hoá trị), hãy:",
    "a) Mô tả sự hình thành liên kết trong phân tử halogen bằng công thức electron.",
    "b) Liên kết trong phân tử halogen là liên kết cộng hoá trị phân cực hay không phân cực?",
    "c) Dựa vào bán kính nguyên tử (Hình 6.2), hãy dự đoán xu hướng biến đổi độ dài liên kết trong dãy các phân tử halogen.",
    "",
    "105",
    "",
    "Các nguyên tử halogen có 7 electron ở lớp ngoài cùng, dễ nhận thêm 1 electron để đạt được cấu hình electron bền của khí hiếm gần nhất:",
    "ns$^2$np$^5$ + 1e $\\longrightarrow$ ns$^2$np$^6$",
    "Do vậy, số oxi hoá đặc trưng của các halogen trong hợp chất là –1.",
    "Tuy nhiên, khi liên kết với các nguyên tố có độ âm điện lớn, các halogen có thể có các số oxi hoá dương: +1, +3, +5, +7 (trừ fluorine có độ âm điện lớn nhất, nên fluorine luôn có số oxi hoá bằng –1 trong mọi hợp chất).",
    "",
    "1. Xác định số oxi hoá của chlorine trong các chất sau: Cl$_2$, HCl, HClO, HClO$_2$, HClO$_3$, HClO$_4$.",
    "2. Từ các số oxi hoá của chlorine, hãy giải thích tại sao Cl$_2$ vừa có tính oxi hoá vừa có tính khử?",
    "",
    "EM CÓ BIẾT",
    "Đồng vị phóng xạ trong y học",
    "• Kĩ thuật chụp PET-CT nhằm phát hiện vị trí các tế bào có tốc độ tiêu thụ glucose lớn, thường là tế bào ung thư.",
    "Dược chất $^{18}$F–FDG dùng trong chụp PET-CT được tạo ra khi thay thế một nhóm OH trong phân tử glucose bằng nguyên tử đồng vị đánh dấu $^{18}$F.",
    "• Đồng vị phóng xạ $^{131}$I dùng điều trị một số bệnh lí tuyến giáp như cường giáp tự miễn (Basedow), ung thư tuyến giáp.",
    "[Hình ảnh thiết bị chụp PET-CT]",
    "Hình 21.3. Thiết bị chụp PET-CT",
    "",
    "❓ 2. Trong tự nhiên, các nguyên tố halogen tồn tại ở dạng hợp chất. Viết công thức một vài hợp chất của halogen thường được dùng trong thực tế.",
    "3. Nguyên tử halogen có thể nhận 1 electron từ nguyên tử kim loại hoặc góp chung electron với nguyên tử phi kim.",
    "Hãy mô tả sự hình thành liên kết trong phân tử NaCl và HCl để minh hoạ.",
    "",
    "106",
    "",
    "III TÍNH CHẤT VẬT LÍ",
    "Trạng thái tồn tại, màu sắc, nhiệt độ nóng chảy (t$_\\text{nc}$), nhiệt độ sôi (t$_\\text{s}$) của halogen được trình bày ở Bảng 21.2:",
    "Bảng 21.2. Một số tính chất vật lí của đơn chất halogen$^{(*)}$",
    "| Đơn chất | Trạng thái | Màu sắc | t$_\\text{nc}$ ($^\\circ$C) | t$_\\text{s}$ ($^\\circ$C) | Độ tan trong nước (mol/L) (ở 25 $^\\circ$C) |",
    "|---|---|---|---|---|---|",
    "| F$_2$ | Khí | Lục nhạt | –219,6 | –188,1 | – |",
    "| Cl$_2$ | Khí | Vàng lục | –101,0 | –34,1 | 0,091 |",
    "| Br$_2$ | Lỏng | Nâu đỏ | –7,3 | 59,2 | 0,21 |",
    "| I$_2$ | Rắn | Tím đen | 113,6 | 185,5 | 0,0013 |",
    "",
    "Nhiệt độ nóng chảy, nhiệt độ sôi tăng từ F$_2$ đến I$_2$ do:",
    "• Tương tác van der Waals giữa các phân tử tăng.",
    "• Khối lượng phân tử tăng.",
    "Ở điều kiện thường, các halogen ít tan trong nước nhưng tan nhiều trong dung môi hữu cơ như alcohol, benzene. Trong y học, dung dịch iodine loãng trong ethanol được dùng làm thuốc sát trùng.",
    "Bromine gây bỏng sâu khi tiếp xúc với da. Hít thở không khí có chứa halogen với nồng độ vượt ngưỡng cho phép làm tổn hại niêm mạc tế bào đường hô hấp, gây co thắt phế quản, khó thở.",
    "",
    "EM CÓ BIẾT",
    "Iodine thăng hoa",
    "Ở nhiệt độ cao, iodine thăng hoa, chuyển từ thể rắn sang thể hơi dưới áp suất thường.",
    "[Hình ảnh sự thăng hoa của iodine]",
    "Hình 21.4. Sự thăng hoa của iodine",
    "",
    "❓ 4. Từ Bảng 21.2, nhận xét xu hướng biến đổi nhiệt độ nóng chảy, nhiệt độ sôi của các halogen và giải thích.",
    "",
    "IV TÍNH CHẤT HOÁ HỌC",
    "Halogen là các phi kim điển hình, có tính oxi hoá mạnh, tính oxi hoá giảm dần từ fluorine đến iodine.",
    "1. Tác dụng với kim loại",
    "Các halogen phản ứng trực tiếp với nhiều kim loại, tạo muối halide.",
    "",
    "$^{(*)}$ Nguồn: http://chem.libretexts.org.",
    "",
    "107",
    "",
    "Sodium nóng chảy sẽ cháy với ngọn lửa sáng chói trong khí chlorine, tạo thành sodium chloride:",
    "2Na + Cl$_2$ $\\xrightarrow{\\text{t}^\\circ}$ 2NaCl",
    "Dây sắt (iron) nung đỏ sẽ bốc cháy trong khí chlorine, tạo thành khói màu nâu đỏ là iron(III) chloride (Hình 21.5):",
    "2Fe + 3Cl$_2$ $\\xrightarrow{\\text{t}^\\circ}$ 2FeCl$_3$",
    "[Hình ảnh chlorine tác dụng với dây sắt]",
    "Hình 21.5. Chlorine tác dụng với dây sắt (iron) ở nhiệt độ cao",
    "",
    "❓ 5. Xác định chất oxi hoá, chất khử trong phản ứng của sodium và iron với chlorine, dùng mũi tên chỉ rõ sự nhường electron từ chất khử sang chất oxi hoá.",
    "",
    "2. Tác dụng với hydrogen",
    "Các halogen phản ứng với hydrogen, tạo thành hydrogen halide.",
    "Bảng 21.3. Một số đặc điểm của phản ứng giữa halogen và hydrogen",
    "| Phản ứng | Điều kiện | Đặc điểm phản ứng |",
    "|---|---|---|",
    "| H$_2$ + F$_2$ $\\longrightarrow$ 2HF | Phản ứng ngay ở nhiệt độ phòng và trong bóng tối | Nổ mạnh |",
    "| H$_2$ + Cl$_2$ $\\longrightarrow$ 2HCl | Ánh sáng hoặc t$^\\circ$ | Gây nổ |",
    "| H$_2$ + Br$_2$ $\\longrightarrow$ 2HBr | ~200 $^\\circ$C, xúc tác Pt | Không gây nổ |",
    "| H$_2$ + I$_2$ $\\rightleftharpoons$ 2HI | ~300 $^\\circ$C, xúc tác Pt | Thuận nghịch $^{(*)}$ |",
    "",
    "Mức độ phản ứng của các halogen với hydrogen giảm dần khi đi từ fluorine đến iodine, phù hợp với tính oxi hoá của các halogen giảm dần từ F$_2$ đến I$_2$.",
    "",
    "Xét các phản ứng hoá học: H$_2$(g) + X$_2$(g) $\\longrightarrow$ 2HX(g) (X là các halogen).",
    "Tra số liệu trong Bảng 12.2 để:",
    "1. Giải thích xu hướng phản ứng của các đơn chất halogen với hydrogen theo khả năng hoạt động của các halogen.",
    "2. Dựa vào số liệu năng lượng liên kết H–X, giải thích xu hướng phản ứng giảm dần từ F$_2$ đến I$_2$.",
    "",
    "$^{(*)}$ Phản ứng thuận nghịch là phản ứng xảy ra theo hai chiều trái ngược nhau ở cùng điều kiện.",
    "",
    "108",
    "",
    "3. Tác dụng với nước",
    "Khi tan vào nước, một phần Cl$_2$ tác dụng với nước tạo thành HCl (hydrochloric acid) và HClO (hypochlorous acid):",
    "Cl$_2$ + H$_2$O $\\rightleftharpoons$ HCl + HClO",
    "Hypochlorous acid có tính oxi hoá mạnh nên chlorine trong nước có khả năng diệt khuẩn, tẩy màu và được ứng dụng trong khử trùng nước sinh hoạt.",
    "",
    "EM CÓ BIẾT",
    "F$_2$ phản ứng mạnh với nước ngay ở nhiệt độ thường, giải phóng khí O$_2$:",
    "2F$_2$ + 2H$_2$O $\\longrightarrow$ 4HF + O$_2$",
    "Các halogen Cl$_2$, Br$_2$ và I$_2$ phản ứng chậm với nước và mức độ phản ứng giảm dần từ Cl$_2$ đến I$_2$.",
    "",
    "❓ 6. Một nhà máy nước sử dụng 5 mg Cl$_2$ để khử trùng 1 L nước sinh hoạt. Tính khối lượng Cl$_2$ nhà máy cần dùng để khử trùng 80 000 m$^3$ nước sinh hoạt.",
    "",
    "Tìm hiểu tính tẩy màu của khí chlorine ẩm",
    "Tiến hành:",
    "Đính một mẩu giấy màu ẩm vào dây kim loại gắn với nút đậy bình tam giác. Sau đó, đưa mẩu giấy vào bình tam giác chứa khí chlorine (Hình 21.6).",
    "Quan sát hiện tượng và thực hiện yêu cầu sau:",
    "1. Nhận xét màu của mẩu giấy trước và sau khi cho vào bình tam giác. Giải thích.",
    "2. Xác định vai trò của chlorine trong phản ứng với nước, tại sao nói chlorine tự oxi hoá – tự khử trong phản ứng này?",
    "[Hình ảnh thí nghiệm tẩy màu của khí chlorine ẩm]",
    "Hình 21.6. Tính tẩy màu của khí chlorine ẩm",
    "",
    "4. Tác dụng với dung dịch kiềm",
    "Chlorine phản ứng với dung dịch sodium hydroxide ở điều kiện thường, tạo thành nước Javel (Gia-ven):",
    "Cl$_2$ + 2NaOH $\\longrightarrow$ NaCl + NaClO + H$_2$O",
    "Nước Javel (chứa NaClO (sodium hypochlorite), NaCl và một phần NaOH dư) được dùng làm chất tẩy rửa, khử trùng.",
    "Khi đun nóng, Cl$_2$ phản ứng với dung dịch potassium hydroxide tạo thành muối chlorate:",
    "3Cl$_2$ + 6KOH $\\xrightarrow{\\text{t}^\\circ}$ 5KCl + KClO$_3$ + 3H$_2$O",
    "Potassium chlorate là chất oxi hoá mạnh, được sử dụng chế tạo thuốc nổ, hỗn hợp đầu que diêm,...",
    "",
    "109",
    "",
    "❓ 7. Khí Cl$_2$ phản ứng với dung dịch sodium hydroxide nóng tạo thành sodium chloride, sodium chlorate và nước.",
    "Lập phương trình hoá học của phản ứng trên theo phương pháp thăng bằng electron, chỉ rõ chất oxi hoá, chất khử.",
    "",
    "5. Tác dụng với dung dịch halide",
    "Chlorine có thể oxi hoá ion Br$^-$ trong dung dịch muối bromide và ion I$^-$ trong dung dịch muối iodide, bromine có thể oxi hoá ion I$^-$ trong dung dịch muối iodide.",
    "Cl$_2$ + 2NaBr $\\longrightarrow$ 2NaCl + Br$_2$",
    "Br$_2$ + 2NaI $\\longrightarrow$ 2NaBr + I$_2$",
    "Trong công nghiệp, phản ứng giữa chlorine và ion bromide được ứng dụng để điều chế bromine từ nước biển.",
    "",
    "Phản ứng thế của một số muối halide",
    "Chuẩn bị: 3 ống nghiệm, dung dịch NaBr, dung dịch NaI, nước Cl$_2$, nước Br$_2$ loãng.",
    "Tiến hành:",
    "• Lấy khoảng 2 mL dung dịch NaBr vào ống nghiệm (1), 2 mL dung dịch NaI vào mỗi ống nghiệm (2) và (3).",
    "• Thêm vào ống nghiệm (1) và (2) vài giọt nước Cl$_2$, thêm vào ống (3) vài giọt nước Br$_2$, lắc đều các ống nghiệm.",
    "Lưu ý: Cẩn thận không để nước Cl$_2$, nước Br$_2$ giây ra tay, quần áo.",
    "[Hình ảnh phản ứng thế của một số muối halide]",
    "Hình 21.7. Phản ứng thế của một số muối halide",
    "Quan sát hiện tượng và thực hiện yêu cầu sau:",
    "1. Nhận xét sự thay đổi màu của dung dịch trong các ống nghiệm.",
    "2. So sánh tính oxi hoá của Cl$_2$, Br$_2$, I$_2$.",
    "3. Hãy chọn một thuốc thử để chứng tỏ có sự tạo thành I$_2$ khi cho nước chlorine (hoặc nước bromine) tác dụng với dung dịch sodium iodide.",
    "",
    "❓ 8. Viết phương trình hoá học minh hoạ tính oxi hoá giảm dần trong dãy Cl$_2$, Br$_2$, I$_2$.",
    "",
    "110",
    "",
    "V ĐIỀU CHẾ CHLORINE",
    "Năm 1774, C. W. Scheele (Se-lơ), nhà hoá học người Thuỵ Điển, điều chế được chlorine khi cho quặng pyrolusite (MnO$_2$) tác dụng với hydrochloric acid đặc:",
    "MnO$_2$ + 4HCl(đặc) $\\xrightarrow{\\text{t}^\\circ}$ MnCl$_2$ + Cl$_2$ + 2H$_2$O",
    "Ngày nay, phản ứng trên vẫn được dùng khi cần điều chế khí Cl$_2$ trong phòng thí nghiệm. Ngoài ra, còn có thể thay MnO$_2$ bằng KMnO$_4$ rắn để điều chế khí Cl$_2$:",
    "2KMnO$_4$ + 16HCl(đặc) $\\longrightarrow$ 2KCl + 2MnCl$_2$ + 5Cl$_2$ + 8H$_2$O",
    "Trong công nghiệp, chlorine được sản xuất ở nhiệt độ thường bằng cách điện phân dung dịch muối ăn bão hoà, có màng ngăn giữa các điện cực:",
    "2NaCl + 2H$_2$O $\\xrightarrow[\\text{có màng ngăn xốp}]{\\text{điện phân dung dịch}}$ 2NaOH + H$_2$ + Cl$_2$",
    "",
    "❓ 9. Khi sản xuất chlorine trong công nghiệp, NaOH và H$_2$ được tạo thành ở cực âm, còn Cl$_2$ được tạo thành ở cực dương. Tại sao cần sử dụng màng ngăn xốp để ngăn cách hai điện cực?",
    "",
    "EM ĐÃ HỌC",
    "• Các nguyên tố halogen tồn tại trong tự nhiên ở dạng hợp chất, phổ biến là muối của fluorine và chlorine.",
    "• Các đơn chất halogen từ fluorine đến iodine:",
    "– Nhiệt độ nóng chảy tăng dần, nhiệt độ sôi tăng dần.",
    "– Là phi kim điển hình, tính oxi hoá giảm dần.",
    "",
    "EM CÓ THỂ",
    "• Thực hiện được thí nghiệm chứng minh và so sánh tính oxi hoá của đơn chất halogen.",
    "• Sử dụng nước Javel an toàn.",
    "",
    "111"
  ]
}
