{
  "content": [
    "BÀI 22",
    "HYDROGEN HALIDE . MUỐI HALIDE",
    "",
    "MỤC TIÊU:",
    "– Nhận xét và giải thích được xu hướng biến đổi nhiệt độ sôi của các hydrogen halide từ HCl tới HI. Giải thích được sự bất thường về nhiệt độ sôi của HF so với các HX khác.",
    "– Trình bày được xu hướng biến đổi tính acid của dãy hydrohalic acid.",
    "– Thực hiện được thí nghiệm phân biệt các ion F$^-$, Cl$^-$, Br$^-$, I$^-$.",
    "– Trình bày được tính khử của các ion halide (Cl$^-$, Br$^-$, I$^-$) thông qua phản ứng với chất oxi hoá là sulfuric acid đặc.",
    "– Nêu được ứng dụng của một số hydrogen halide.",
    "",
    "❓ Hydrochloric acid được sử dụng rộng rãi trong sản xuất, điển hình là dùng để đánh sạch bề mặt kim loại trước khi gia công, sơn, hàn, mạ điện,... Trong công đoạn này, thép được đưa qua các bể chứa dung dịch HCl (được gọi là bể Picking) để tẩy bỏ lớp rỉ sét, sau đó rửa sạch bằng nước trước khi qua các công đoạn tiếp theo. Vậy các ứng dụng trên dựa vào tính chất quan trọng nào của hydrochloric acid?",
    "",
    "I HYDROGEN HALIDE",
    "1. Cấu tạo phân tử",
