INSERT INTO lessons (chapter_id, code, name, page, sort_order, knowledge_json) VALUES
((SELECT id FROM chapters WHERE code = 'CH_8' AND textbook_id = (SELECT id FROM textbooks WHERE code = 'HOA_10')), 'PHULUC', 'GIẢI THÍCH MỘT SỐ THUẬT NGỮ DÙNG TRONG SÁCH', 119, 24, $JSON$
{
  "content": [
    "GIẢI THÍCH MỘT SỐ THUẬT NGỮ DÙNG TRONG SÁCH",
    "| | THUẬT NGỮ | Trang |",
    "|---|---|---|",
    "| C | Chất xúc tác: chất làm tăng tốc độ phản ứng nhưng khối lượng và bản chất của chất không bị thay đổi sau khi phản ứng kết thúc. | 74 |",
    "| Đ | Đồng vị phóng xạ: dạng nguyên tử không bền của một nguyên tố hoá học mà hạt nhân có thể biến đổi thành hạt nhân khác và phát ra tia phóng xạ. | 18 |",
    "| L | Liên kết cho – nhận: liên kết được tạo thành giữa hai nguyên tử bằng các cặp electron dùng chung, các electron này chỉ do một nguyên tử đóng góp. | 55 |",
    "| | Liên kết cộng hoá trị: liên kết giữa hai nguyên tử được tạo ra bằng sự dùng chung một hay nhiều cặp electron. | 55 |",
    "| | Liên kết cộng hoá trị không phân cực (không cực): liên kết mà cặp electron dùng chung không bị lệch về phía nguyên tử nào. | 57 |",
    "| | Liên kết cộng hoá trị phân cực (có cực): liên kết mà cặp electron chung lệch về phía nguyên tử có độ âm điện lớn hơn. | 57 |",
    "| | Liên kết ion: liên kết được tạo thành do lực hút tĩnh điện giữa các ion mang điện tích trái dấu. | 51 |",
    "| N | Năng lượng hoạt hoá: năng lượng tối thiểu mà các chất phản ứng cần có để phản ứng hoá học có thể xảy ra được. | 99 |",
    "| | Nguyên lí Pauli: trong một ô orbital có tối đa 2 electron, ngược nhau về chiều tự quay. | 22 |",
    "| | Nguyên lí vững bền: ở trạng thái cơ bản, trong nguyên tử các electron chiếm lần lượt những orbital có mức năng lượng từ thấp đến cao. | 23 |",
    "| | Nhiệt lượng kế: dụng cụ dùng để đo nhiệt lượng thu vào hoặc toả ra. | 87 |",
    "| P | Phổ khối lượng (phổ khối): phương pháp ion hoá chất và sử dụng mối quan hệ giữa số ion với tỉ lệ khối lượng/điện tích của ion nhằm xác định khối lượng nguyên tử hoặc phân tử của chất. | 19 |",
    "| | Phương trình nhiệt hoá học: phương trình hoá học có ghi đầy đủ trạng thái của các chất và biến thiên enthalpy của phản ứng. | 82 |",
    "| Q | Quy tắc Hund: trong cùng một phân lớp, các electron sẽ phân bố trên các orbital sao cho số electron độc thân là tối đa, trong đó các electron này phải có chiều tự quay giống nhau. | 23 |",
    "| T | Tinh thể: dạng rắn của chất trong đó các nguyên tử, ion hoặc phân tử được sắp xếp một cách đều đặn, theo một trật tự nhất định trong không gian. | 48 |",
    "",
    "119",
    "",
    "Nhà xuất bản Giáo dục Việt Nam xin trân trọng cảm ơn các tác giả có tác phẩm, tư liệu được sử dụng, trích dẫn trong cuốn sách này.",
    "",
    "Chịu trách nhiệm xuất bản:",
    "Chủ tịch Hội đồng Thành viên NGUYỄN ĐỨC THÁI",
    "Tổng Giám đốc HOÀNG LÊ BÁCH",
    "",
    "Chịu trách nhiệm nội dung:",
    "Tổng biên tập PHẠM VĨNH THÁI",
    "",
    "Biên tập nội dung: NGUYỄN THANH GIANG – VĂN THỊ MINH HUỆ – PHÙNG THỊ PHƯƠNG LIÊN",
    "Biên tập mĩ thuật: NGUYỄN BÍCH LA",
    "Thiết kế sách: PHẠM THỊ MINH THU",
    "Trình bày bìa: NGUYỄN BÍCH LA",
    "Minh hoạ: NGUYỄN BÍCH LA",
    "Sửa bản in: PHẠM THỊ TÌNH",
    "Chế bản: CTCP MĨ THUẬT VÀ TRUYỀN THÔNG",
    "",
    "Bản quyền © (2022) thuộc Nhà xuất bản Giáo dục Việt Nam.",
    "Xuất bản phẩm đã đăng kí quyền tác giả. Tất cả các phần của nội dung cuốn sách này đều không được sao chép, lưu trữ, chuyển thể dưới bất kì hình thức nào khi chưa có sự cho phép bằng văn bản của Nhà xuất bản Giáo dục Việt Nam.",
    "",
